# ══════════════════════════════════════════════════════════════════════
# S21 — WHATSAPP SEND ELIGIBILITY GATE (suppression + 24h window pre-check)
#
# Two classes of send were being attempted that CANNOT succeed:
#   131026 — recipient can't receive (not on WhatsApp). Permanent. ...2333
#            failed on three consecutive days; we kept retrying it.
#   131047 — >24h since the customer last replied. A FREE-FORM send outside
#            the window is structurally impossible. ...1224 was attempted
#            twice in one day, burning the send both times.
# Approved TEMPLATES are exempt from the window rule (that is the correct Meta
# mechanism for out-of-window contact) but are still subject to suppression.
# ══════════════════════════════════════════════════════════════════════

WA_HARD_FAIL_CODES = {131026}   # permanent, number-level. Suppress on first hit.
WA_WINDOW_HOURS    = 24

# S28 — INTERNAL NUMBERS (Michael/test lines). These are real, reachable
# numbers that legitimately receive DIRECT sends (file deliveries, live
# tests), so full suppression is wrong. But they must never be treated as
# leads by automated outreach: re-engagement kept burning sends to ...1224
# (Michael's own WhatsApp) because his test-lead row sat in the queue.
# Comma-separated digits in INTERNAL_NUMBERS env; default = Michael's line.
INTERNAL_NUMBERS = {
    re.sub(r"\D", "", _n) for _n in
    os.getenv("INTERNAL_NUMBERS", "18135031224").split(",")
    if re.sub(r"\D", "", _n)
}


def _is_internal_number(phone):
    """True if this number belongs to Michael/an internal test line.
    Matches on full digits or the 10-digit tail (handles +1 variants)."""
    d = re.sub(r"\D", "", str(phone or ""))
    if not d:
        return False
    return any(d == n or d[-10:] == n[-10:] for n in INTERNAL_NUMBERS if len(n) >= 10)


def _wa_digits(phone):
    return re.sub(r"\D", "", str(phone or ""))


def _wa_tail(phone):
    d = _wa_digits(phone)
    return ("..." + d[-4:]) if len(d) >= 4 else "????"


def _wa_is_suppressed(phone):
    """True if this number is on the bad-number suppression list."""
    d = _wa_digits(phone)
    if not d:
        return False
    try:
        import pg_store as _p
        if not _p.enabled():
            return False
        return bool(_p.load_state("wa_suppressed:" + d, False))
    except Exception:
        return False   # infra error -> fail OPEN (never block a good send)


def _wa_suppress(phone, code, reason=""):
    """Add a number to the suppression list (idempotent). Alerts #dev once."""
    d = _wa_digits(phone)
    if not d:
        return
    try:
        import pg_store as _p
        if not _p.enabled():
            return
        if _p.load_state("wa_suppressed:" + d, False):
            return   # already suppressed — stay quiet
        _p.save_state("wa_suppressed:" + d, {
            "code": code,
            "reason": str(reason)[:200],
            "at": datetime.now(pytz.timezone(TIMEZONE)).isoformat(),
        })
        print(f"[WA-GATE] SUPPRESSED {_wa_tail(phone)} — code={code} ({reason})")
        _report_error("wa_number_suppressed",
                      f"number suppressed after hard failure {code}",
                      f"to={_wa_tail(phone)} reason={str(reason)[:120]} — no further sends will be attempted")
    except Exception as _e:
        print(f"[WA-GATE] suppress failed (non-fatal): {_e}")


def _wa_mark_window_expired(phone):
    """Record a Meta 131047 verdict (24h window expired) for this number.

    S24: Meta telling us the window is closed beats our own unknown/stale
    last-inbound data. Free-form sends are refused until an INBOUND newer than
    this mark arrives (customer wrote in -> window reopened). Templates are
    unaffected — they are the correct out-of-window mechanism. This stops the
    daily burn loop where the same doomed free-form send was retried against
    a number whose last reply we never recorded (...1224, 4 days running).
    """
    d = _wa_digits(phone)
    if not d:
        return
    try:
        import pg_store as _p
        if not _p.enabled():
            return
        _p.save_state("wa_window_expired:" + d,
                      datetime.now(pytz.timezone(TIMEZONE)).isoformat())
        print(f"[WA-GATE] window-expired mark set for {_wa_tail(phone)} (131047)")
    except Exception as _e:
        print(f"[WA-GATE] window mark failed (non-fatal): {_e}")


def _wa_window_expired_mark(phone):
    """Return the stored 131047 mark timestamp for this number, or None."""
    d = _wa_digits(phone)
    if not d:
        return None
    try:
        import pg_store as _p
        if not _p.enabled():
            return None
        return _p.load_state("wa_window_expired:" + d, None)
    except Exception:
        return None


def _wa_last_inbound(phone):
    """Timestamp of the customer's last INBOUND message, or None if unknown."""
    d = _wa_digits(phone)
    if not d:
        return None
    for _k in (f"whatsapp:+{d}", f"whatsapp:{d}", d, "+" + d):
        _v = (lead_data.get(_k) or {}).get("last_message_time")
        if _v:
            return _v
    return None


def wa_send_eligibility(phone, is_template=False):
    """Shared pre-send gate. Returns (ok: bool, reason: str).

    Fails OPEN on anything unknown — an unknown last-reply time means we let
    Meta decide, rather than risk blocking a legitimate reply.
    """
    if _wa_is_suppressed(phone):
        return False, "suppressed"

    # ── S-6 (Patch #30) · SHAPE GATE ──────────────────────────────────
    # Placed ABOVE the template short-circuit ON PURPOSE. The Ehmcke burn was
    # a TEMPLATE send (mwm_lara_shoot_reminder, Meta 131009): an Instagram-
    # scoped ID was fed into the WhatsApp `to=` field. A gate placed below the
    # short-circuit would not have seen it, which is why this one is here.
    #
    # This is the only place in the gate that fails CLOSED. It refuses ONLY
    # what is provably impossible — an identifier that is affirmatively
    # Instagram-scoped (explicit marker, or more digits than E.164 permits).
    # Short or unusual numbers still fail open, per the docstring above.
    if is_ig_scoped(phone):
        try:
            _tail = _wa_tail(phone)
        except Exception:
            _tail = str(phone)[-4:]
        print(f"[WA-SHAPE-GATE] REFUSED — {_tail} is an Instagram-scoped ID, not a phone number")
        try:
            _report_error(
                "wa_send_refused_ig_identifier",
                "Instagram-scoped ID cannot receive a WhatsApp message",
                f"to={_tail} template={is_template} — refused pre-flight; "
                f"Meta would return 131009. Use the email fallback (S-4) or an IG DM reply.",
            )
        except Exception:
            pass
        return False, "ig_scoped_identifier"

    if is_template:
        return True, "ok"   # templates are valid outside the 24h window

    last = _wa_last_inbound(phone)

    # S24: honor a prior Meta 131047 verdict. If Meta told us the window is
    # closed and the customer has NOT written in since, refuse the free-form
    # send instead of burning it again. A newer inbound reopens the window.
    _mark = _wa_window_expired_mark(phone)
    if _mark:
        try:
            _tz = pytz.timezone(TIMEZONE)
            _mark_dt = datetime.fromisoformat(_mark) if isinstance(_mark, str) else None
            if _mark_dt is not None:
                if _mark_dt.tzinfo is None:
                    _mark_dt = _tz.localize(_mark_dt)
                _last_dt = None
                if last:
                    _last_dt = datetime.fromisoformat(last) if isinstance(last, str) else last
                    if _last_dt is not None and _last_dt.tzinfo is None:
                        _last_dt = _tz.localize(_last_dt)
                if _last_dt is None or _last_dt <= _mark_dt:
                    return False, "window_expired"
        except Exception:
            pass   # any parse trouble -> fall through to the normal check

    if not last:
        return True, "ok"   # unknown -> fail open

    try:
        _tz = pytz.timezone(TIMEZONE)
        if isinstance(last, str):
            last = datetime.fromisoformat(last)
        if last.tzinfo is None:
            last = _tz.localize(last)
        hours = (datetime.now(_tz) - last).total_seconds() / 3600.0
    except Exception:
        return True, "ok"   # unparseable -> fail open

    if hours > WA_WINDOW_HOURS:
        return False, "window_expired"
    return True, "ok"


def send_whatsapp_meta(to: str, body: str = None, media_url: str = None,
                       phone_number_id: str = None, filename: str = None,
                       caption: str = None):
    """Send a WhatsApp message via Meta Cloud API.

    phone_number_id selects which Meta sender number to send FROM.
    Defaults to META_PHONE_NUMBER_ID (Maya). Pass LARA_PHONE_NUMBER_ID
    to send as LARA. Both numbers live on the same WABA + access token.
    """
    pn_id = phone_number_id or META_PHONE_NUMBER_ID

    # S21: pre-send eligibility gate — refuse sends that cannot succeed.
    _ok, _why = wa_send_eligibility(to, is_template=False)
    if not _ok:
        print(f"[WA-GATE] BLOCKED free-form send to {_wa_tail(to)} — {_why}")
        try:
            _report_error(f"wa_send_blocked_{_why}",
                          "send prevented pre-flight (would have failed at Meta)",
                          f"to={_wa_tail(to)} — this is a PREVENTED send, not a burned one")
        except Exception:
            pass
        return None

    # Strip Slack "Sent using Claude/Cowork" suffix before sending to WhatsApp
    if body:
        body = re.sub(r"\s*\*?Sent using\s*\*?\s+\w+\s*$", "", body, flags=re.IGNORECASE).strip()
    phone = to.replace("whatsapp:", "").lstrip("+")
    url = f"https://graph.facebook.com/v19.0/{pn_id}/messages"
    headers = {
        "Authorization": f"Bearer {META_ACCESS_TOKEN}",
        "Content-Type": "application/json",
    }
    if media_url:
        # S25a: classify by filename when given (Drive direct-download URLs have
        # no extension), else by the URL path. Documents/video/audio/image all
        # supported as link-based media per Meta Cloud API.
        ml = (filename or media_url.split("?")[0]).lower()
        _m = {"link": media_url}
        if caption:
            _m["caption"] = caption
        if any(ml.endswith(ext) for ext in (".mp3", ".ogg", ".wav", ".amr", ".m4a")):
            _m.pop("caption", None)  # audio does not support captions
            payload = {"messaging_product": "whatsapp", "to": phone, "type": "audio", "audio": _m}
        elif any(ml.endswith(ext) for ext in (".mp4", ".3gp", ".mov")):
            payload = {"messaging_product": "whatsapp", "to": phone, "type": "video", "video": _m}
        elif any(ml.endswith(ext) for ext in (".pdf", ".doc", ".docx", ".xls", ".xlsx",
                                              ".ppt", ".pptx", ".csv", ".txt", ".zip")):
            if filename:
                _m["filename"] = filename
            payload = {"messaging_product": "whatsapp", "to": phone, "type": "document", "document": _m}
        else:
            payload = {"messaging_product": "whatsapp", "to": phone, "type": "image", "image": _m}
    else:
        payload = {"messaging_product": "whatsapp", "to": phone, "type": "text", "text": {"body": body or ""}}
    import time as _time_wa
    last_err = None
    for _attempt in range(3):
        try:
            resp = http_requests.post(url, json=payload, headers=headers, timeout=30)
            resp.raise_for_status()
            print(f"\u2705 Meta API message sent to {phone}")
            return resp.json()
        except Exception as e:
            last_err = e
            if hasattr(e, "response") and e.response is not None:
                print(f"   Response: {e.response.text}")
            if _attempt < 2:
                _wait = (2 ** _attempt) * 0.5
                print(f"\u26a0\ufe0f Meta API attempt {_attempt + 1}/3 failed: {e} \u2014 retrying in {_wait}s")
                _time_wa.sleep(_wait)
            else:
                print(f"\u274c Meta API all 3 attempts failed: {e}")
                _notify_error_to_dev(
                    "WhatsApp Send Failed",
                    f"Could not send message to {phone} after 3 attempts: {e}",
                    lead_info=f"Phone: {phone}",
                    severity="CRITICAL"
                )
    return None


def _ig_digits(igsid):
    """The bare IGSID for `igsid`, accepting an `instagram:`-prefixed sender."""
    return (event_rail.ig_mark_key(igsid) or "").replace(
        event_rail.IG_WINDOW_MARK_PREFIX, "") or None


def _ig_mark_window_expired(igsid):
    """Persist a Meta 403 verdict (24h IG messaging window closed).

    S84: the WhatsApp twin of this has existed since S24. Instagram only ever
    had an in-memory set, so the verdict died at every restart and was
    consulted on exactly one code path. Everything else re-attempted, got 403,
    and alerted again — eight times for one lead on Aug 10.
    """
    key = event_rail.ig_mark_key(igsid)
    if not key:
        return
    try:
        import pg_store as _p
        if not _p.enabled():
            return
        _p.save_state(key, datetime.now(pytz.timezone(TIMEZONE)).isoformat())
        print(f"[IG-GATE] window-expired mark set for {_ig_digits(igsid)}")
    except Exception as _e:
        print(f"[IG-GATE] window mark failed (non-fatal): {_e}")


def _ig_window_expired_mark(igsid):
    """Return the stored 403 mark timestamp for this IGSID, or None."""
    key = event_rail.ig_mark_key(igsid)
    if not key:
        return None
    try:
        import pg_store as _p
        if not _p.enabled():
            return None
        return _p.load_state(key, None)
    except Exception:
        return None


def _ig_clear_window_expired(igsid):
    """Drop the 403 mark — the lead wrote in, so the window reopened."""
    key = event_rail.ig_mark_key(igsid)
    if not key:
        return
    try:
        import pg_store as _p
        if _p.enabled():
            _p.save_state(key, "")
    except Exception:
        pass


def _ig_last_inbound(igsid):
    """Timestamp of this IGSID's last INBOUND message, or None if unknown."""
    d = _ig_digits(igsid)
    if not d:
        return None
    for _k in (f"instagram:{d}", d):
        _v = (lead_data.get(_k) or {}).get("last_message_time")
        if _v:
            return _v
    return None


def _ig_can_send_dm(igsid):
    """(ok, reason) — refuse a free-form IG DM whose window Meta already closed.

    Mirrors _wa_can_send(). Fails OPEN on anything unreadable: one wasted API
    call is a smaller failure than silently refusing to answer a live lead.
    """
    d = _ig_digits(igsid)
    if not d:
        return True, "ok"
    if d in _ig_403_blocked:
        return False, "window_expired"
    if event_rail.ig_window_blocked(_ig_window_expired_mark(d), _ig_last_inbound(d)):
        return False, "window_expired"
    return True, "ok"


def send_instagram_dm(recipient_id: str, body: str = None, media_url: str = None):
    """Send an Instagram DM via Meta's Instagram Messaging API (Graph API).

    Uses the same META_PAGE_ACCESS_TOKEN as WhatsApp — both go through the
    Facebook Page linked to the Instagram Business account.

    recipient_id: The Instagram-scoped User ID (IGSID) of the recipient.
    body: Text message to send.
    media_url: URL of image/video to attach (optional).
    """
    # ── S84: refuse a send Meta has already told us will 403 ──
    _ig_ok, _ig_why = _ig_can_send_dm(recipient_id)
    if not _ig_ok:
        _TALLY.bump("ig.send_blocked_window_expired", str(recipient_id))
        print(f"[IG-GATE] send refused for {recipient_id} — {_ig_why} "
              f"(mark stands; no API call, no alert)")
        return None

    if not INSTAGRAM_PAGE_ID:
        print("[IG DM] INSTAGRAM_PAGE_ID not configured — cannot send")
        return None
    token = INSTAGRAM_ACCESS_TOKEN
    if not token:
        print("[IG DM] No access token configured (INSTAGRAM_ACCESS_TOKEN) — cannot send")
        return None

    # Strip Slack "Sent using Claude/Cowork" suffix before sending
    if body:
        body = re.sub(r"\s*\*?Sent using\s*\*?\s+\w+\s*$", "", body, flags=re.IGNORECASE).strip()

    # Use graph.instagram.com for IGAAX-prefix tokens (Instagram Login API),
    # graph.facebook.com for EAA-prefix tokens (Page Access Token)
    if token.startswith("IGAA"):
        url = f"https://graph.instagram.com/v21.0/{INSTAGRAM_PAGE_ID}/messages"
    else:
        url = f"https://graph.facebook.com/v19.0/{INSTAGRAM_PAGE_ID}/messages"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }

    if media_url:
        # Image attachment
        payload = {
            "recipient": {"id": recipient_id},
            "message": {
                "attachment": {
                    "type": "image",
                    "payload": {"url": media_url, "is_reusable": True}
                }
            }
        }
    else:
        payload = {
            "recipient": {"id": recipient_id},
            "message": {"text": body or ""}
        }

    import time as _time_ig
    last_err = None
    for _attempt in range(3):
        try:
            resp = http_requests.post(url, json=payload, headers=headers, timeout=30)
            resp.raise_for_status()
            print(f"✅ Instagram DM sent to {recipient_id}")
            return resp.json()
        except Exception as e:
            last_err = e
            if hasattr(e, "response") and e.response is not None:
                print(f"   Response: {e.response.text}")
                # ── 403 = messaging window closed — do NOT retry ──
                if e.response.status_code == 403:
                    print(f"🚫 IG DM 403 Forbidden for {recipient_id} — messaging window closed. Not retrying.")
                    # S84: the mark is what makes the claim in the alert TRUE.
                    # Persist BEFORE deciding whether to alert, and count every
                    # 403 even when the alert is suppressed — a capped job
                    # announces what it did not do.
                    _already = bool(_ig_window_expired_mark(recipient_id)) or (
                        recipient_id in _ig_403_blocked)
                    _ig_403_blocked.add(recipient_id)
                    _ig_mark_window_expired(recipient_id)
                    _TALLY.bump("ig.window_expired_403", str(recipient_id))
                    if event_rail.ig_should_alert_403(recipient_id, _already):
                        _notify_error_to_dev(
                            "Instagram DM Window Closed",
                            f"IG DM to {recipient_id} blocked (403) — 24h messaging "
                            f"window expired. The block is now recorded and further "
                            f"sends to this lead are refused before they are "
                            f"attempted; a reply from the lead reopens the window. "
                            f"Repeat 403s are counted at /health "
                            f"(ig.window_expired_403), not re-alerted here.",
                            lead_info=f"IGSID: {recipient_id}",
                            severity="WARNING"
                        )
                    else:
                        _TALLY.bump("ig.window_expired_403_alert_suppressed",
                                    str(recipient_id))
                    return None
            if _attempt < 2:
                _wait = (2 ** _attempt) * 0.5
                print(f"⚠️ IG DM attempt {_attempt + 1}/3 failed: {e} — retrying in {_wait}s")
                _time_ig.sleep(_wait)
            else:
                print(f"❌ IG DM all 3 attempts failed: {e}")
                _notify_error_to_dev(
                    "Instagram DM Send Failed",
                    f"Could not send IG DM to {recipient_id} after 3 attempts: {e}",
                    lead_info=f"IGSID: {recipient_id}",
                    severity="CRITICAL"
                )
    return None


def download_meta_media(media_id: str):
    """Download media from Meta Cloud API. Returns (bytes, content_type)."""
    headers = {"Authorization": f"Bearer {META_ACCESS_TOKEN}"}
    resp = http_requests.get(f"https://graph.facebook.com/v19.0/{media_id}", headers=headers, timeout=15)
    resp.raise_for_status()
    download_url = resp.json().get("url")
    resp2 = http_requests.get(download_url, headers=headers, timeout=30)
    resp2.raise_for_status()
    return resp2.content, resp2.headers.get("Content-Type", "")

