# GOOGLE CALENDAR FUNCTIONS
# âââââââââââââââââââââââââââââââââââââââââââââ

def get_calendar_service(impersonate=None):
    """
    Authenticate and return a Google Calendar service client.

    DWD is used ONLY when `impersonate` is explicitly passed.
    Read-only operations (get_available_slots, check_specific_slot) call this
    without impersonate so they never trigger DWD — the service account accesses
    the MWM CREATIONS calendar directly (service account must be a calendar member).

    Write operations (book_appointment) pass impersonate=MICHAEL_EMAIL to try DWD,
    but the caller handles the fallback if DWD is not configured.
    """
    # When impersonating via DWD, only request calendar scope (DWD config doesn't include spreadsheets)
    cal_only_scopes = ["https://www.googleapis.com/auth/calendar"]
    scopes = cal_only_scopes if impersonate else SCOPES
    creds_json = (os.getenv("GOOGLE_CREDENTIALS_JSON") or os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON"))  # S0.1: accept either env name
    if creds_json:
        creds_dict = json.loads(creds_json)
        creds = service_account.Credentials.from_service_account_info(
            creds_dict, scopes=scopes
        )
        sa_email = creds_dict.get("client_email", "unknown")
        print(f"[calendar] service account: {sa_email}")
    else:
        # Fallback: load from local file (for local dev)
        creds = service_account.Credentials.from_service_account_file(
            "service_account.json", scopes=scopes
        )

    # Domain-Wide Delegation — ONLY when explicitly requested by the caller
    if impersonate:
        creds = creds.with_subject(impersonate)
        print(f"[calendar] DWD as: {impersonate}")

    return build("calendar", "v3", credentials=creds)


def _get_calendar_sa_email():
    """S5.2: service-account email from creds env — safe to expose (not a secret);
    needed so a human can grant it calendar ACL."""
    try:
        cj = os.getenv("GOOGLE_CREDENTIALS_JSON") or os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON")
        return json.loads(cj).get("client_email", "unknown") if cj else None
    except Exception:
        return "parse-error"


def get_gmail_service(impersonate=None):
    """Gmail API client via Domain-Wide Delegation."""
    import json
    creds_json = os.getenv("GOOGLE_CREDENTIALS_JSON", "") or os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "")  # S0.1
    if not creds_json:
        raise RuntimeError("GOOGLE_CREDENTIALS_JSON not set")
    info = json.loads(creds_json)
    from google.oauth2 import service_account as _sa
    creds = _sa.Credentials.from_service_account_info(info, scopes=GMAIL_SCOPES)
    if impersonate:
        creds = creds.with_subject(impersonate)
    from googleapiclient.discovery import build as _build
    return _build("gmail", "v1", credentials=creds)


def get_available_slots():
    """
    Return exactly 3 available slots — one per each of the next 3 available business days,
    alternating morning -> afternoon -> morning.
      Morning options (tried in order): 10:00 AM, then 11:00 AM
      Afternoon options (tried in order): 3:00 PM, then 2:00 PM
    Checks the MWM CREATIONS calendar (CALENDAR_ID).
    All-day events are intentionally ignored so they don't block real availability.
    """
    try:
        service = get_calendar_service()
        tz = pytz.timezone(TIMEZONE)
        now = datetime.now(tz)
        end_window = now + timedelta(days=21)

        print(f"[get_available_slots] checking calendar: {CALENDAR_ID}")

        # Fetch all timed events in the window
        events_result = service.events().list(
            calendarId=CALENDAR_ID,
            timeMin=now.isoformat(),
            timeMax=end_window.isoformat(),
            singleEvents=True,
            orderBy="startTime"
        ).execute(num_retries=3)

        busy_times = []
        for event in events_result.get("items", []):
            start_info = event.get("start", {})
            end_info = event.get("end", {})
            # Skip FREE events (transparency="transparent") — they're reminders,
            # not real blocks. Only "opaque" (busy) events block availability.
            if event.get("transparency") == "transparent":
                continue
            if "dateTime" in start_info and "dateTime" in end_info:
                busy_times.append({
                    "start": start_info["dateTime"],
                    "end": end_info["dateTime"]
                })

        # Alternating pattern: morning -> afternoon -> morning
        # morning = [10am, 11am] in priority order
        # afternoon = [3pm, 2pm] in priority order
        day_patterns = [
            [(10, 0), (11, 0)],   # Slot 1: morning
            [(15, 0), (14, 0)],   # Slot 2: afternoon
            [(10, 0), (11, 0)],   # Slot 3: morning
        ]

        slots = []
        current_day = now.date() - timedelta(days=1)  # loop increments before checking
        days_checked = 0

        while len(slots) < 3 and days_checked < 21:
            current_day += timedelta(days=1)
            days_checked += 1

            # Monday-Friday only
            if current_day.weekday() >= 5:
                continue

            # ── Capacity check: skip days that are fully booked ──
            if _count_bookings_on_date(current_day) >= MAX_BOOKINGS_PER_DAY:
                print(f"[Capacity] {current_day} has {MAX_BOOKINGS_PER_DAY}+ bookings — skipping")
                continue

            times_to_try = day_patterns[len(slots)]

            for (hour, minute) in times_to_try:
                candidate = tz.localize(datetime(
                    current_day.year, current_day.month, current_day.day,
                    hour, minute, 0
                ))

                # Skip if already in the past
                if candidate <= now:
                    continue

                slot_end = candidate + timedelta(minutes=60)
                # 15-min buffer before and after to avoid back-to-back meetings
                buffer_start = candidate - timedelta(minutes=15)
                buffer_end = slot_end + timedelta(minutes=15)
                is_busy = any(
                    datetime.fromisoformat(b["start"]).astimezone(tz) < buffer_end
                    and datetime.fromisoformat(b["end"]).astimezone(tz) > buffer_start
                    for b in busy_times
                )

                if not is_busy:
                    slots.append({
                        "id": candidate.isoformat(),
                        "display": candidate.strftime("%A, %B %d at %I:%M %p EST")
                    })
                    break  # one slot per day, move to next day

            # If this day had no available slot in the desired period, the while loop
            # retries the same pattern index on the next business day automatically.

        print(f"[get_available_slots] returning {len(slots)} slots: {[s['display'] for s in slots]}")
        return slots

    except Exception as e:
        print(f"[get_available_slots] ERROR: {e}")
        return []


def book_appointment(slot_id, lead_name, lead_email, lead_business, lead_phone=None, appointment_type="studio_visit", booked_via=None,
                     callback_phone=None):
    """
    Create a 1-hour Google Calendar event on the MWM Creations calendar.

    PATCH #30 / SPEC §2.4 — `booked_via` no longer defaults to "WhatsApp".
    It was a DEFAULT PARAMETER VALUE, not a typed label and not stored data:
    every caller that omitted the argument stamped "WhatsApp" on the event
    regardless of the real thread, which is how Instagram-sourced bookings
    came to be structurally unremindable while looking healthy in the data.
    It is now a HINT only. The true channel is resolved from `lead_phone`
    (the identifier), and when the two disagree the identifier wins.
    Tries three strategies in order, using the first that succeeds:

      1. MWM Creations calendar  + attendees + send invites
         (works when Domain-Wide Delegation is configured via GOOGLE_DELEGATE_EMAIL)
      2. MWM Creations calendar  + attendees, no email invites
         (silent attendee add — may still fail if DWD not set up)
      3. MWM Creations calendar  + no attendees
         (works when service account has WRITER access but DWD is not configured)

    Returns the event ID on success, or None on failure.

    PATCH #57 — a `strategy_call` is a call MICHAEL PLACES. The event
    location literally reads "Michael will dial the number on this
    booking". Before this patch nothing checked that a number existed,
    and an Instagram lead was booked for Fri Aug 7 10:00 whose only
    identifier was an IGSID. The rail had already written the note
    "IG-scoped identifier — WhatsApp impossible" onto that very event;
    it just had no authority to stop it. It does now. A studio visit is
    unaffected — the lead walks through the door, and refusing an
    in-person booking over a missing phone number costs more than it saves.
    """
    try:
        _num_ok, _dial_number, _num_why = resolve_callback_number(
            appointment_type, identifier=lead_phone, callback=callback_phone,
        )
        if not _num_ok:
            print(f"[book_appointment] REFUSED — no dialable number: {_num_why}")
            _notify_error_to_dev(
                "Call Booked With No Number",
                f"Refused a {appointment_type} for {lead_name}: {_num_why}. "
                f"Maya has been told to ask for the number and book again.",
                lead_info=f"{lead_name} ({lead_phone})",
                severity="WARNING",
            )
            return {"refused": True, "reason": _num_why,
                    "instruction": missing_number_note(appointment_type, _num_why)}
        if booking_needs_number(appointment_type) is False and not _dial_number:
            print(f"[book_appointment] note: booking without a phone number — {_num_why}")

        # Try with DWD first (sends proper calendar invites as Michael)
        # Falls back to no-DWD if unauthorized_client (DWD not configured in Google Admin)
        delegate = os.getenv("GOOGLE_DELEGATE_EMAIL")
        try:
            service = get_calendar_service(impersonate=delegate) if delegate else get_calendar_service()
            # Quick test — will raise if DWD creds are invalid
            service.calendarList().list(maxResults=1).execute(num_retries=3)
            print(f"[book_appointment] using DWD as {delegate}")
        except Exception as dwd_err:
            if "unauthorized_client" in str(dwd_err) or "invalid_grant" in str(dwd_err):
                print(f"[book_appointment] DWD failed ({dwd_err}), falling back to service account direct access")
                service = get_calendar_service()  # no DWD
            else:
                raise
        tz = pytz.timezone(TIMEZONE)
        start_dt = datetime.fromisoformat(slot_id).astimezone(tz)
        end_dt = start_dt + timedelta(minutes=60)

        # ── Auto-cleanup: delete any existing event for this lead before creating a new one ──
        # This prevents ghost events when a lead reschedules, even if Maya forgets to
        # call cancel_appointment first. Belt-and-suspenders on top of the prompt rule.
        try:
            _cleanup_name = (lead_name or "").strip()
            _cleanup_phone = (lead_phone or "").replace("whatsapp:", "").replace("+", "")
            if _cleanup_name or _cleanup_phone:
                now_iso = datetime.now(tz).isoformat()
                future_iso = (datetime.now(tz) + timedelta(days=90)).isoformat()
                existing_events = service.events().list(
                    calendarId=CALENDAR_ID,
                    timeMin=now_iso,
                    timeMax=future_iso,
                    singleEvents=True,
                    orderBy="startTime"
                ).execute(num_retries=3).get("items", [])

                for ev in existing_events:
                    ev_summary = ev.get("summary", "")
                    ev_description = ev.get("description", "")
                    ev_text = f"{ev_summary} {ev_description}".lower()
                    matched = False

                    # Match by lead name in event summary/description
                    if _cleanup_name and _cleanup_name.lower() in ev_text:
                        matched = True
                    # Match by phone number in event description
                    elif _cleanup_phone and len(_cleanup_phone) >= 7 and _cleanup_phone in ev_description:
                        matched = True

                    if matched:
                        old_event_id = ev["id"]
                        old_start = ev.get("start", {}).get("dateTime", "unknown")
                        print(f"[book_appointment] AUTO-CLEANUP: Found existing event for {lead_name}: "
                              f"'{ev_summary}' at {old_start} (ID: {old_event_id}) — deleting before rebooking")
                        try:
                            service.events().delete(
                                calendarId=CALENDAR_ID,
                                eventId=old_event_id,
                                sendUpdates="all"
                            ).execute(num_retries=3)
                            print(f"[book_appointment] AUTO-CLEANUP: Deleted old event {old_event_id}")
                            # Update lead_data if available
                            if lead_phone and lead_phone in lead_data:
                                lead_data[lead_phone]["event_id"] = None
                                lead_data[lead_phone]["booked"] = False
                        except Exception as del_err:
                            print(f"[book_appointment] AUTO-CLEANUP WARNING: Could not delete old event {old_event_id}: {del_err}")
                        break  # Only delete the first match — one lead, one event
        except Exception as cleanup_err:
            # Non-fatal: if cleanup fails, still proceed with creating the new event
            print(f"[book_appointment] AUTO-CLEANUP ERROR (non-fatal, proceeding with booking): {cleanup_err}")

        if appointment_type == "strategy_call":
            event_title = f"Strategy Call — {lead_name} ({lead_business})"
            event_desc_header = "Strategy Call with Michael Moraes / MWM Creations"
        else:
            event_title = f"Studio Visit — {lead_name} ({lead_business})"
            event_desc_header = "Studio Visit with Michael Moraes / MWM Creations Studios"

        # ── S-1/S-2 (Patch #30): resolve the channel, then harden the body ──
        # Description now reads "Booked by: Maya" (the AGENT) and carries the
        # source CHANNEL separately, resolved from the identifier. The old
        # single line "Booked via: Maya (WhatsApp)" conflated the two, which
        # is what made the mislabel invisible for months.
        _true_channel = resolve_channel(lead_phone, hint=booked_via)
        event_base = {
            "summary": event_title,
            "description": (
                f"{event_desc_header}\n\n"
                f"Lead: {lead_name}\n"
                f"Business: {lead_business}\n"
                f"Email: {lead_email}\n"
                f"Booked by: Maya\n"
                f"Booked via: {_true_channel}"
                # Patch #57 — the number to dial, on the event, where the
                # person who has to place the call will actually look.
                + (f"\nCall this number: {_dial_number}" if _dial_number else "")
            ),
            "start": {"dateTime": start_dt.isoformat(), "timeZone": TIMEZONE},
            "end": {"dateTime": end_dt.isoformat(), "timeZone": TIMEZONE},
            "location": (STRATEGY_CALL_LOCATION if appointment_type == "strategy_call"
                         else STUDIO_ADDRESS),
        }
        _is_call = (appointment_type == "strategy_call")

        # S-1 gate. strict=False here on purpose: this is a live Maya
        # conversation and a lead who has just said yes should not be refused
        # over an address. Every issue is still reported to #dev.
        try:
            event_base, _rail_issues = harden_event_body(
                event_base,
                source_identifier=lead_phone,
                attendee_email=lead_email,
                context="book_appointment",
                strict=False,
                reporter=_report_error,
                default_location=(STRATEGY_CALL_LOCATION if _is_call else STUDIO_ADDRESS),
                channel_hint=booked_via,
                require_postal=not _is_call,
            )
            if _rail_issues:
                print(f"[EVENT-RAIL] book_appointment issues: {_rail_issues}")
        except Exception as _rail_err:
            # The rail must never be the reason a booking fails.
            print(f"[EVENT-RAIL] harden failed (non-fatal): {_rail_err}")

        # ── Race condition guard: re-check availability right before booking ──
        # Between get_available_slots showing the slot and the lead confirming,
        # another lead may have booked the same time. Re-check now.
        try:
            buffer_start = start_dt - timedelta(minutes=15)
            buffer_end = end_dt + timedelta(minutes=15)
            conflict_events = service.events().list(
                calendarId=CALENDAR_ID,
                timeMin=buffer_start.isoformat(),
                timeMax=buffer_end.isoformat(),
                singleEvents=True,
            ).execute(num_retries=3).get("items", [])
            # Filter to timed BUSY events only (ignore all-day events and FREE events)
            # transparency="transparent" means FREE — it's a reminder, not a real block
            timed_conflicts = [
                ev for ev in conflict_events
                if "dateTime" in ev.get("start", {})
                and ev.get("transparency") != "transparent"
            ]
            if timed_conflicts:
                conflict_names = [ev.get("summary", "Unknown") for ev in timed_conflicts]
                print(f"[book_appointment] RACE CONDITION CAUGHT: slot {start_dt} already taken by {conflict_names}")
                _notify_error_to_dev(
                    "Double-Booking Prevention",
                    f"Blocked duplicate booking at {start_dt.strftime('%B %d %I:%M %p')} — slot already taken by {conflict_names[0]}",
                    lead_info=f"{lead_name} ({lead_phone})",
                    severity="WARNING"
                )
                return None
        except Exception as race_err:
            # Non-fatal: if re-check fails, still attempt the booking
            print(f"[book_appointment] Race-check failed (non-fatal): {race_err}")

        # ── Capacity guard: enforce daily booking limit ──
        try:
            _booking_date = start_dt.date()
            _day_count = _count_bookings_on_date(_booking_date)
            if _day_count >= MAX_BOOKINGS_PER_DAY:
                print(f"[Capacity] BLOCKED: {_booking_date} already has {_day_count} bookings (max {MAX_BOOKINGS_PER_DAY})")
                _notify_error_to_dev(
                    "Capacity Limit Reached",
                    f"Booking blocked for {_booking_date.strftime('%B %d')} — already {_day_count}/{MAX_BOOKINGS_PER_DAY} bookings",
                    lead_info=f"{lead_name} ({lead_phone})",
                    severity="WARNING"
                )
                return None
        except Exception as _cap_err:
            print(f"[Capacity] Check failed (non-fatal): {_cap_err}")

        # Each attempt: (calendarId, include_attendees, sendUpdates, label)
        attempts = [
            (CALENDAR_ID, True,  "all",  "MWM Creations cal + attendees + invites"),
            (CALENDAR_ID, True,  "none", "MWM Creations cal + attendees, no invites"),
            (CALENDAR_ID, False, "none", "MWM Creations cal, no attendees"),
        ]

        created = None
        used_attendees = False
        used_send_updates = "none"
        used_calendar = CALENDAR_ID

        # harden_event_body() has already put the ASCII-folded attendee on
        # event_base. Capture it here so the no-attendee fallback can strip it
        # cleanly — without this, attempt 3 would still carry attendees and the
        # fallback that exists for non-DWD setups would silently stop working.
        _rail_attendees = event_base.pop("attendees", None)

        for cal_id, with_attendees, send_upd, label in attempts:
            event = dict(event_base)
            if with_attendees:
                event["attendees"] = ([dict(a) for a in _rail_attendees]
                                      if _rail_attendees else [{"email": lead_email}])
            else:
                event.pop("attendees", None)
            try:
                created = service.events().insert(
                    calendarId=cal_id,
                    body=event,
                    sendUpdates=send_upd
                ).execute(num_retries=3)
                _SA_CACHE.clear()  # S25d: new calendar booking invalidates availability cache
                used_attendees = with_attendees
                used_send_updates = send_upd
                used_calendar = cal_id
                print(f"â Booking strategy used: {label}")
                break
            except Exception as attempt_err:
                print(f"â ï¸ Attempt [{label}] failed: {attempt_err}")
                continue

        if not created:
            print("â All booking attempts failed.")
            return None

        event_link = created.get("htmlLink", "")

        # ── Michael short-circuit (Session 30.9): skip lead-funnel pollution for test bookings ──
        import re as _re_bk
        _lead_digits = _re_bk.sub(r"\D", "", (lead_phone or "").replace("whatsapp:", ""))
        _michael_env_bk = os.getenv("MICHAEL_PHONE", "") or ""
        _michael_digits_bk = _re_bk.sub(r"\D", "", _michael_env_bk)
        is_michael_booking = bool(_lead_digits and _michael_digits_bk and _lead_digits == _michael_digits_bk)
        if is_michael_booking:
            print(f"🧪 book_appointment: Michael test booking — skipping Slack notify + Sheet update")

        # ── Slack: notify appointment booked ──
        if not is_michael_booking:
            try:
                _slot_str = f"{start_dt.strftime('%B %d, %Y at %I:%M %p')} ET"
                _interest = appointment_type.replace("_", " ").title()
                _contact = lead_phone or lead_email or "N/A"
                # Use the RESOLVED channel, not the caller's hint. booked_via
                # may now be None (Patch #30 removed its "WhatsApp" default).
                _source_label = f" · via {_true_channel}" if _true_channel != CH_WHATSAPP_LABEL else ""
                _notify_appointment_booked(lead_name or "Prospect", _contact + _source_label, _slot_str, _interest, lead_email=lead_email)
                # ── Update Google Sheet: mark as booked ──
                try:
                    if lead_phone:
                        update_lead_columns(lead_phone, {
                            "Status": booking_status_for(appointment_type),  # Jul 8 2026 stage-sync fix
                            "WhatsApp Status": "Booked",
                            "Appointment Booked": "Y",
                            "Lead Temperature": "Hot",
                        })
                except Exception as _sheet_err:
                    print(f"\u26a0\ufe0f Sheet booking update failed (non-fatal): {_sheet_err}")
            except Exception as slack_err:
                print(f"⚠️ Slack booking notification failed (non-fatal): {slack_err}")
        print(f"â Appointment booked: {created.get('id')} for {lead_name} at {start_dt}")
        print(f"ð Calendar: {used_calendar} | Attendees included: {used_attendees}")
        print(f"ð Event link: {event_link}")

        # ââ WhatsApp notification to Michael ââââââââââââââââââ
        michael_phone = os.getenv("MICHAEL_PHONE")

        if michael_phone and META_ACCESS_TOKEN:
            try:
                if used_attendees and used_send_updates == "all":
                    invite_note = "\u2709\ufe0f Calendar invite sent to lead."
                elif used_attendees:
                    invite_note = "\u2709\ufe0f Lead added as attendee (no email invite)."
                else:
                    invite_note = "\u26a0\ufe0f Calendar invite NOT sent (DWD not configured — see setup guide)."
                phone_line = ""
                if lead_phone:
                    clean_phone = lead_phone.replace("whatsapp:", "")
                    phone_line = f"📱 Phone: {clean_phone}\n"
                notification = (
                    f"🎉 *New Studio Visit Booked via Maya!*\n\n"
                    f"👤 Name: {lead_name}\n"
                    f"🏢 Business: {lead_business}\n"
                    f"📧 Email: {lead_email}\n"
                    f"{phone_line}"
                    f"🕐 Time: {start_dt.strftime('%A, %B %d at %I:%M %p %Z')}\n\n"
                    f"{invite_note}"
                )
                send_whatsapp_meta(michael_phone, body=notification)
                print(f"\u2705 Michael notified via WhatsApp at {michael_phone}")
            except Exception as notify_err:
                print(f"\u26a0\ufe0f Could not notify Michael via WhatsApp: {notify_err}")

        return created.get("id")

    except Exception as e:
        print(f"Error booking appointment: {e}")
        try:  # S0.4: booking failures must never be silent
            _post_to_slack_async(SLACK_DEV_CHANNEL, f"\U0001f6a8 *BOOKING FAILED* \u2014 book_appointment raised: `{e}`. Lead may believe they are booked \u2014 verify calendar + GOOGLE_CREDENTIALS_JSON.")
        except Exception as _sx:
            _report_error("book_appointment:L3147", _sx)  # S6.5 silent-except sweep
        return None


# ══════════════════════════════════════════════════════════════════════
# PATCH #58 — the out-of-hours approval rail
#
# Michael found the Andrea Battis thread by chance, reading Instagram on
# his phone. Maya had told her three times over three days that an answer
# was coming. No request existed. There was nothing to answer.
#
# The whole design goal is ONE TAP. His standing rule is that the machine
# runs with minimal use of his time, so an approval that costs him a login
# is a failed approval. He gets an email, taps a time, and the lead is
# booked and told. Nothing else is asked of him.
#
# Notification is EMAIL, deliberately:
#   · Slack #matt has zero human-authored messages from him — that channel
#     does not reach him and pretending otherwise is how this failed.
#   · WhatsApp to his own number is currently bouncing on expired 24h
#     windows (wa_send_blocked_window_expired, several a day).
#   · Email demonstrably lands.
# ══════════════════════════════════════════════════════════════════════

# request id -> request dict (see event_rail.build_approval_request)
approval_requests = {}
_approval_lock = threading.Lock()
# PATCH #66 — last time each request's undeliverable-email alarm was posted to
# #dev, so a permanent failure pages once an hour instead of six times.
_APPROVAL_ALARM_SENT = {}


def _approval_base_url():
    """Public origin for the one-tap links."""
    dom = os.getenv("RAILWAY_PUBLIC_DOMAIN", "") or ""
    if dom:
        return "https://" + dom.rstrip("/").replace("https://", "").replace("http://", "")
    return (os.getenv("APP_BASE_URL", "") or "").rstrip("/")


def _approval_find_open_for(lead_phone=None, lead_email=None):
    """The open request for this lead, if any. Used by the anti-stall gate."""
    _p = (lead_phone or "").strip().lower()
    _e = (lead_email or "").strip().lower()
    with _approval_lock:
        for req in approval_requests.values():
            if not approval_is_open(req):
                continue
            if _p and (req.get("lead_phone") or "").strip().lower() == _p:
                return req
            if _e and (req.get("lead_email") or "").strip().lower() == _e:
                return req
    return None


def _approval_slot_display(iso):
    """'Thursday, August 06 at 7:00 PM ET' — how Michael reads a time."""
    try:
        dt = datetime.fromisoformat(iso)
        return dt.strftime("%A, %B %d at %-I:%M %p ET")
    except (ValueError, TypeError):
        try:
            return datetime.fromisoformat(iso).strftime("%A, %B %d at %I:%M %p ET")
        except Exception:
            return str(iso)


def _approval_email_html(req):
    """The email. One tap per option, plus a decline. No login, no app.

    Every link is a plain GET so it works from the Mail app on his phone
    without anything else being open.
    """
    base = _approval_base_url()
    tok = req["token"]
    rows = []
    for i, iso in enumerate(req.get("slots") or []):
        url = f"{base}/approve/{tok}?slot={i}"
        rows.append(
            f'<tr><td style="padding:6px 0;">'
            f'<a href="{url}" style="display:inline-block;padding:12px 20px;'
            f'background:#14532d;color:#fff;text-decoration:none;border-radius:6px;'
            f'font-family:Arial,sans-serif;font-size:15px;">'
            f'Confirm {_approval_slot_display(iso)}</a></td></tr>'
        )
    decline = f"{base}/approve/{tok}?decline=1"
    who = req.get("lead_name") or "A lead"
    biz = f" — {req['business']}" if req.get("business") else ""
    note = (f'<p style="margin:14px 0;color:#444;">{req["note"]}</p>'
            if req.get("note") else "")
    return (
        '<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;'
        'line-height:1.6;color:#222;max-width:560px;">'
        f'<p><strong>{who}{biz}</strong> is asking for a time outside your '
        'standard hours. Maya cannot book it without you.</p>'
        f'{note}'
        '<p style="margin:18px 0 6px;"><strong>Tap one and it is done</strong> — '
        'the event is created, the invite goes out, and Maya tells them:</p>'
        f'<table cellpadding="0" cellspacing="0">{"".join(rows)}</table>'
        f'<p style="margin:22px 0 6px;"><a href="{decline}" '
        'style="color:#991b1b;">None of these work</a> — Maya will offer '
        'standard hours instead.</p>'
        f'<p style="margin-top:20px;color:#777;font-size:13px;">'
        f'Request {req["id"]} · {req.get("channel") or "unknown channel"} · '
        f'{req.get("lead_email") or "no email on file"}</p>'
        '</div>'
    )


def _approval_notify_michael(req, is_reminder=False):
    """Email Michael. Returns True only if the send actually happened."""
    who = req.get("lead_name") or "a lead"
    n = len(req.get("slots") or [])
    subject = (
        f"{'Still waiting — ' if is_reminder else ''}"
        f"Approve an out-of-hours call with {who}"
        f" ({n} option{'' if n == 1 else 's'})"
    )
    try:
        # PATCH #66 — was `_email_send(...)`, which routes through the LEAD
        # suppression guard. That guard refuses every @mwmcreations.com
        # address, so this email was blocked before it was ever sent and this
        # door has never opened once. Operator mail goes down the allow-listed
        # path instead. See event_rail.operator_allowed().
        result = _email_operator(MICHAEL_EMAIL, subject,
                                 _approval_email_html(req),
                                 why=f"approval {req.get('id')}")
        ok = email_ok(result)
    except Exception as exc:
        _report_error("approval.notify", exc, f"request={req.get('id')}")
        ok = False
    if ok:
        with _approval_lock:
            _live = approval_requests.get(req["id"])
            if _live is not None:
                _live["notified_at"] = datetime.now(
                    pytz.timezone(TIMEZONE)).replace(tzinfo=None).isoformat()
                if is_reminder:
                    _live["reminders_sent"] = int(_live.get("reminders_sent") or 0) + 1
    else:
        # A notification that silently failed is the original bug wearing a
        # different hat. Make it loud.
        #
        # PATCH #66 — but loud ONCE AN HOUR, not every ten minutes. This fired
        # 6x/hour all night on AR-9CDD44 and the 40th copy carried no
        # information the 1st did not. An alarm that repeats faster than anyone
        # can act on it stops being an alarm and becomes weather — and #dev is
        # the channel MATT reads to build the morning briefing.
        _now_a = datetime.now(pytz.timezone(TIMEZONE)).replace(tzinfo=None)
        _key_a = f"approval_alarm:{req.get('id')}"
        _last_a = _APPROVAL_ALARM_SENT.get(_key_a)
        if _last_a is None or (_now_a - _last_a).total_seconds() >= 3600:
            _APPROVAL_ALARM_SENT[_key_a] = _now_a
            _suffix = "" if _last_a is None else (
                " (repeating hourly until this is fixed — first seen "
                f"{_last_a.strftime('%b %d %H:%M')})")
            _notify_error_to_dev(
                "Approval Email Not Delivered",
                f"Could not email Michael the approval request {req.get('id')} for "
                f"{who}. THE LEAD IS WAITING AND NOBODY HAS BEEN ASKED."
                f"{_suffix}",
                lead_info=f"{who} ({req.get('lead_phone') or req.get('lead_email')})",
                severity="ERROR",
            )
    return ok


def request_out_of_hours_approval(lead_name, lead_email, lead_phone, slots,
                                  business="", note="", channel=""):
    """File a real request and email Michael. Returns the id, or an error.

    This is the ONLY way Maya may claim a human is deciding something.
    """
    _tz = pytz.timezone(TIMEZONE)
    _now = datetime.now(_tz)

    clean = []
    for raw in (slots or []):
        try:
            dt = _parse_datetime_flexible(raw)
            if dt.tzinfo is None:
                dt = _tz.localize(dt)
            else:
                dt = dt.astimezone(_tz)
        except Exception:
            continue
        if dt <= _now:
            continue
        clean.append(dt.replace(tzinfo=None).isoformat())
    if not clean:
        return {"error": "No usable future times. Ask the lead which evenings "
                         "or weekend times work, then call this again."}

    rid = "AR-" + secrets.token_hex(3).upper()
    req = build_approval_request(
        rid, secrets.token_urlsafe(24), lead_name, lead_email, lead_phone,
        clean, business=business, note=note, channel=channel,
        created_at=_now.replace(tzinfo=None).isoformat(),
    )
    with _approval_lock:
        approval_requests[rid] = req

    sent = _approval_notify_michael(req)
    display = ", ".join(_approval_slot_display(s) for s in clean)
    if not sent:
        return {"error": "The request was filed but the email to Michael did "
                         "not go out. Do NOT tell the lead it is with him. Say "
                         "you will come back to them, and nothing more.",
                "request_id": rid}
    return {"ok": True, "request_id": rid, "slots": clean,
            "instruction": approval_filed_note(rid, display)}


def _approval_tell_lead(req, text):
    """Deliver a message to the lead on the channel they actually used."""
    ident = (req.get("lead_phone") or "").strip()
    try:
        if ident.lower().startswith("instagram:") or is_ig_scoped(ident):
            return bool(send_instagram_dm(
                ident.split(":", 1)[-1], body=text))
        if is_dialable(ident):
            return bool(send_whatsapp_meta(
                "whatsapp:+" + digits_of(ident), body=text))
    except Exception as exc:
        _report_error("approval.tell_lead", exc, f"request={req.get('id')}")
    _email = req.get("lead_email")
    if _email and ascii_email(_email)[1]:
        try:
            return email_ok(_email_send(
                ascii_email(_email)[0],
                "About your call with Michael",
                f"<p>{text}</p>", via="machine"))
        except Exception as exc:
            _report_error("approval.tell_lead_email", exc,
                          f"request={req.get('id')}")
    return False


def _approval_sweep():
    """Nag until answered, and close honestly when every option has passed.

    This thread is the reason a request cannot go quiet for three days.
    """
    while True:
        try:
            time.sleep(600)
            _tz = pytz.timezone(TIMEZONE)
            _now = datetime.now(_tz).replace(tzinfo=None)
            with _approval_lock:
                snapshot = list(approval_requests.values())
            for req in snapshot:
                if not approval_is_open(req):
                    continue
                if approval_has_expired(req, _now):
                    with _approval_lock:
                        _live = approval_requests.get(req["id"])
                        if _live is None or not approval_is_open(_live):
                            continue
                        _live["status"] = APPROVAL_EXPIRED
                        _live["resolved_at"] = _now.isoformat()
                    _notify_error_to_dev(
                        "Out-of-Hours Approval EXPIRED",
                        f"Every time {req.get('lead_name') or 'the lead'} offered "
                        f"has passed with no answer. Request {req['id']}. "
                        f"{approval_expiry_note(req)}",
                        lead_info=f"{req.get('lead_name')} ({req.get('lead_email')})",
                        severity="WARNING",
                    )
                    continue
                if approval_reminder_due(req, _now):
                    _approval_notify_michael(req, is_reminder=True)
        except Exception as exc:
            try:
                _report_error("approval.sweep", exc)
            except Exception:
                pass


threading.Thread(target=_approval_sweep, daemon=True).start()


@app.route("/approve/<token>", methods=["GET"])
def approve_out_of_hours(token):
    """One tap from Michael's phone. No login — the token IS the credential.

    Deliberately a GET so it works straight from the Mail app. The token is
    24 bytes of urlsafe entropy, single-purpose, and only ever sent to
    MICHAEL_EMAIL.
    """
    with _approval_lock:
        req = next((r for r in approval_requests.values()
                    if secrets.compare_digest(str(r.get("token") or ""), str(token))),
                   None)
    if req is None:
        return "<p>That approval link is not valid.</p>", 404

    if not approval_is_open(req):
        return (f"<p>Request {req['id']} was already "
                f"<strong>{req['status']}</strong>. Nothing changed.</p>"), 200

    _tz = pytz.timezone(TIMEZONE)
    _now_naive = datetime.now(_tz).replace(tzinfo=None)

    if request.args.get("decline"):
        with _approval_lock:
            req["status"] = APPROVAL_DECLINED
            req["resolved_at"] = _now_naive.isoformat()
        _approval_tell_lead(req, (
            f"Hi {req.get('lead_name') or 'there'} — I wasn't able to get an "
            "evening confirmed on Michael's side, and I'm sorry for the wait. "
            f"He does have standard hours open, weekdays {STANDARD_HOURS_START} "
            "AM to 5 PM ET — tell me a day that works and I'll get it booked. "
            "Or if it's easier, we can take it by email."))
        return "<p>Declined. The lead has been told and offered standard hours.</p>", 200

    try:
        idx = int(request.args.get("slot", "-1"))
    except (TypeError, ValueError):
        idx = -1
    slots = req.get("slots") or []
    if not (0 <= idx < len(slots)):
        return "<p>That time is no longer one of the options.</p>", 400

    chosen = slots[idx]
    if chosen not in approval_live_slots(req, _now_naive):
        return ("<p>That time has already passed. Open the most recent email "
                "for the options that are still live.</p>"), 409

    event_id = book_appointment(
        slot_id=chosen,
        lead_name=req.get("lead_name") or "",
        lead_email=req.get("lead_email") or "",
        lead_business=req.get("business") or "",
        lead_phone=req.get("lead_phone"),
        callback_phone=req.get("lead_phone"),
        appointment_type="strategy_call",
        booked_via=req.get("channel") or None,
    )
    # Patch #57 refusals come back as a dict, and a dict is truthy.
    if isinstance(event_id, dict) or not event_id:
        why = (event_id.get("reason") if isinstance(event_id, dict)
               else "the calendar write failed")
        _notify_error_to_dev(
            "Approved Call Could Not Be Booked",
            f"You approved {_approval_slot_display(chosen)} for "
            f"{req.get('lead_name')} but the booking was refused: {why}. "
            "The request is still open and the lead has NOT been told.",
            lead_info=f"{req.get('lead_name')} ({req.get('lead_email')})",
            severity="ERROR",
        )
        return (f"<p>Approved, but the booking could not be created: {why}<br>"
                f"Nothing was sent to the lead. This is in #dev.</p>"), 200

    with _approval_lock:
        req["status"] = APPROVAL_APPROVED
        req["chosen_slot"] = chosen
        req["resolved_at"] = _now_naive.isoformat()

    told = _approval_tell_lead(req, (
        f"Good news — Michael can do {_approval_slot_display(chosen)}. "
        "You'll get the calendar invite by email shortly. Talk then!"))
    with _approval_lock:
        if told:
            req["lead_told_at"] = _now_naive.isoformat()

    if not told:
        _notify_error_to_dev(
            "Approved But Lead Not Reachable",
            f"{_approval_slot_display(chosen)} is booked for "
            f"{req.get('lead_name')}, but the confirmation could not be "
            "delivered on their channel. They may not know.",
            lead_info=f"{req.get('lead_name')} ({req.get('lead_email')})",
            severity="WARNING",
        )

    return (f"<p><strong>Booked — {_approval_slot_display(chosen)}.</strong><br>"
            f"{'The lead has been told and the invite is on its way.' if told else 'Booked, but we could not reach the lead — see #dev.'}"
            "</p>"), 200


@app.route("/admin/approvals", methods=["GET"])
def admin_approvals():
    """Read-only. What is waiting on Michael right now."""
    if not _admin_secret_ok(request.values.get("secret", "")):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    _tz = pytz.timezone(TIMEZONE)
    _now = datetime.now(_tz).replace(tzinfo=None)
    with _approval_lock:
        rows = list(approval_requests.values())
    return jsonify({
        "ok": True,
        "as_of": datetime.now(_tz).isoformat(),
        "open": [approval_health_line(r, _now) for r in rows if approval_is_open(r)],
        "requests": [
            {k: v for k, v in r.items() if k != "token"} for r in rows
        ],
    }), 200


def cancel_appointment(sender=None, lead_name="", cancel_reason="", event_date=""):
    """
    Cancel an existing appointment from Michael's Google Calendar.

    Strategy:
      1. If lead_data has a stored event_id for this sender, delete that event directly.
      2. Search upcoming calendar events for the lead's name in the summary.
      3. Search by sender's phone number in event description.
      4. Search by date/time if event_date is provided (handles "Unknown" leads).
      5. Search by attendee email matching lead_data.

    Returns a dict with success/failure info.
    """
    try:
        service = get_calendar_service()
        event_id = None
        event_summary = ""
        found_event = None  # Keep full event for name backfill

        # Strategy 1: Use stored event_id from lead_data
        if sender and sender in lead_data and lead_data[sender].get("event_id"):
            event_id = lead_data[sender]["event_id"]
            print(f"[cancel_appointment] Found stored event_id: {event_id}")
            try:
                found_event = service.events().get(calendarId=CALENDAR_ID, eventId=event_id).execute(num_retries=3)
                event_summary = found_event.get("summary", "Appointment")
            except Exception:
                event_summary = f"Appointment with {lead_name}"

        # Fetch upcoming events for strategies 2-5
        events = []
        if not event_id:
            tz = pytz.timezone(TIMEZONE)
            now = datetime.now(tz)
            time_max = now + timedelta(days=60)
            events_result = service.events().list(
                calendarId=CALENDAR_ID,
                timeMin=now.isoformat(),
                timeMax=time_max.isoformat(),
                singleEvents=True,
                orderBy="startTime"
            ).execute(num_retries=3)
            events = events_result.get("items", [])

        # Strategy 2: Search calendar by lead name (skip if name is Unknown/empty)
        _skip_name = not lead_name or lead_name.lower() in ("unknown", "there", "")
        if not event_id and not _skip_name:
            print(f"[cancel_appointment] Searching calendar for events matching '{lead_name}'")
            for ev in events:
                summary = ev.get("summary", "")
                description = ev.get("description", "")
                search_text = f"{summary} {description}".lower()
                if lead_name.lower() in search_text:
                    event_id = ev["id"]
                    event_summary = summary
                    found_event = ev
                    print(f"[cancel_appointment] Found matching event: {event_summary} (ID: {event_id})")
                    break

        # Strategy 3: Search by phone number in event description
        if not event_id and sender:
            clean_phone = sender.replace("whatsapp:", "").replace("+", "")
            for ev in events:
                description = ev.get("description", "")
                if clean_phone in description:
                    event_id = ev["id"]
                    event_summary = ev.get("summary", "Appointment")
                    found_event = ev
                    print(f"[cancel_appointment] Found event by phone: {event_summary} (ID: {event_id})")
                    break

        # Strategy 4: Search by attendee email (from lead_data)
        if not event_id and sender and sender in lead_data:
            lead_email = lead_data[sender].get("email", "")
            if lead_email:
                print(f"[cancel_appointment] Searching by attendee email: {lead_email}")
                for ev in events:
                    attendees = ev.get("attendees", [])
                    for att in attendees:
                        if att.get("email", "").lower() == lead_email.lower():
                            event_id = ev["id"]
                            event_summary = ev.get("summary", "Appointment")
                            found_event = ev
                            print(f"[cancel_appointment] Found event by attendee email: {event_summary}")
                            break
                    if event_id:
                        break

        # Strategy 5: Search by date/time (handles Unknown leads)
        if not event_id and event_date:
            print(f"[cancel_appointment] Searching by date/time: {event_date}")
            try:
                tz = pytz.timezone(TIMEZONE)
                # Parse the date — Maya should pass ISO format e.g. "2026-06-25T10:00:00"
                target_dt = datetime.fromisoformat(event_date)
                if target_dt.tzinfo is None:
                    target_dt = tz.localize(target_dt)
                # Look for Studio Visit events within 2 hours of the target time
                for ev in events:
                    start = ev.get("start", {})
                    start_str = start.get("dateTime", "")
                    if not start_str:
                        continue
                    ev_start = datetime.fromisoformat(start_str)
                    if ev_start.tzinfo is None:
                        ev_start = tz.localize(ev_start)
                    time_diff = abs((ev_start - target_dt).total_seconds())
                    # Match: within 2 hours AND looks like a studio visit (not recurring tasks)
                    summary = ev.get("summary", "")
                    is_visit = any(kw in summary.lower() for kw in ("studio visit", "visit", "walk", "meeting", "consultation"))
                    if time_diff <= 7200 and is_visit:
                        event_id = ev["id"]
                        event_summary = summary
                        found_event = ev
                        print(f"[cancel_appointment] Found event by date match: {event_summary} (ID: {event_id})")
                        break
                    # Exact time match even without visit keywords
                    if time_diff <= 60:
                        event_id = ev["id"]
                        event_summary = summary
                        found_event = ev
                        print(f"[cancel_appointment] Found event by exact time match: {event_summary}")
                        break
            except Exception as date_err:
                print(f"[cancel_appointment] Date parse error: {date_err}")

        # Backfill lead name from the found event if lead is "Unknown"
        if found_event and sender and sender in lead_data:
            stored_name = lead_data[sender].get("name", "")
            if not stored_name or stored_name.lower() in ("unknown", "there", ""):
                # Extract name from event description ("Lead: Firstname Lastname")
                desc = found_event.get("description", "")
                import re as _re
                name_match = _re.search(r"Lead:\s*(.+?)(?:\n|$)", desc)
                if name_match:
                    real_name = name_match.group(1).strip()
                    lead_data[sender]["name"] = real_name
                    print(f"[cancel_appointment] Backfilled lead name: '{real_name}' (was '{stored_name}')")
                    if not lead_name or lead_name.lower() in ("unknown", "there", ""):
                        lead_name = real_name

        if not event_id:
            print(f"[cancel_appointment] No matching event found for {lead_name} / {sender} / date:{event_date}")
            return {
                "success": False,
                "error": f"Could not find an upcoming appointment for {lead_name}. Try providing the appointment date/time (e.g. 'Thursday at 10am'). The appointment may have already been cancelled or may not exist in the system."
            }

        # Delete the calendar event
        service.events().delete(
            calendarId=CALENDAR_ID,
            eventId=event_id,
            sendUpdates="all"  # Notify attendees about the cancellation
        ).execute(num_retries=3)
        print(f"[cancel_appointment] Successfully deleted event {event_id}: {event_summary}")

        # Update lead_data
        if sender and sender in lead_data:
            lead_data[sender]["booked"] = False
            lead_data[sender]["event_id"] = None

        # Notify Slack
        _notify_appointment_cancelled(
            lead_name=lead_name or (lead_data.get(sender, {}).get("name", "Unknown")),
            sender=sender or "Unknown",
            event_summary=event_summary,
            cancel_reason=cancel_reason or "No reason provided"
        )

        # Update Google Sheets
        try:
            if sender:
                update_lead_columns(sender, {
                    "WhatsApp Status": "Cancelled",
                    "Appointment Booked": "N",
                    "Notes": f"Cancelled: {cancel_reason}",
                })
        except Exception as sheet_err:
            print(f"⚠️ Sheet cancellation update failed (non-fatal): {sheet_err}")

        # Notify Michael via WhatsApp
        michael_phone = os.getenv("MICHAEL_PHONE")
        if michael_phone and META_ACCESS_TOKEN:
            try:
                clean_sender = (sender or "").replace("whatsapp:", "")
                notification = (
                    f"❌ *Appointment Cancelled*\n\n"
                    f"👤 Lead: {lead_name}\n"
                    f"📱 Phone: {clean_sender}\n"
                    f"📅 Event: {event_summary}\n"
                    f"💬 Reason: {cancel_reason}\n\n"
                    f"Maya handled the cancellation automatically."
                )
                send_whatsapp_meta(michael_phone, body=notification)
                print(f"✅ Michael notified of cancellation via WhatsApp")
            except Exception as notify_err:
                print(f"⚠️ Could not notify Michael of cancellation: {notify_err}")

        return {
            "success": True,
            "cancelled_event": event_summary,
            "message": f"Successfully cancelled: {event_summary}"
        }

    except Exception as e:
        print(f"[cancel_appointment] ERROR: {e}")
        return {"success": False, "error": f"Failed to cancel appointment: {str(e)}"}


def _parse_datetime_flexible(dt_string):
    """
    Parse a datetime string in ISO 8601 or other common formats.
    Returns a naive or aware datetime object; caller handles timezone.
    """
    try:
        return datetime.fromisoformat(dt_string)
    except ValueError:
        pass
    for fmt in (
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%dT%H:%M",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%d",
    ):
        try:
            return datetime.strptime(dt_string, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognised datetime format: {dt_string!r}")


def check_specific_slot(requested_datetime):
    """
    Check if a specific requested time is free on the MWM Creations calendar.
    Returns {"available": True, "slot_id": ..., "display": ...} or {"available": False}.
    All-day events are ignored (same logic as get_available_slots).
    """
    print(f"[check_specific_slot] raw input: {requested_datetime!r}")
    try:
        service = get_calendar_service()
        tz = pytz.timezone(TIMEZONE)

        # Parse the requested time; assume Eastern if no timezone info
        candidate = _parse_datetime_flexible(requested_datetime)
        if candidate.tzinfo is None:
            candidate = tz.localize(candidate)
        else:
            candidate = candidate.astimezone(tz)

        print(f"[check_specific_slot] parsed candidate: {candidate.isoformat()}")

        # Must be a weekday between 9 AM and 4:30 PM
        if candidate.weekday() >= 5:
            # PATCH #58 — same door as the evening case below.
            print(f"[check_specific_slot] weekend (weekday={candidate.weekday()}) — approval path offered")
            return {
                "available": False,
                "reason": "weekends are outside standard hours",
                "needs_approval": True,
                "out_of_hours_reason": "weekend",
                "slot_id": candidate.isoformat(),
                "instruction": no_approval_tool_note(),
            }
        if not (9 <= candidate.hour < 17) or (candidate.hour == 16 and candidate.minute > 0):
            # PATCH #58 — this used to be a WALL. It returned "not available"
            # and nothing else, so Maya, with no tool that could ask a human
            # anything, invented one: "let me flag this for Michael". Nothing
            # was ever filed. Andrea Battis was strung along for three days.
            # It is now a DOOR: the answer names the path through it.
            print(f"[check_specific_slot] out of hours (hour={candidate.hour}) — approval path offered")
            return {
                "available": False,
                "reason": f"outside standard hours ({STANDARD_HOURS_START} AM – 5 PM ET)",
                "needs_approval": True,
                "out_of_hours_reason": out_of_hours_reason(candidate),
                "slot_id": candidate.isoformat(),
                "instruction": no_approval_tool_note(),
            }
        # Must be in the future
        now_et = datetime.now(tz)
        if candidate <= now_et:
            print(f"[check_specific_slot] rejected: in the past (candidate={candidate.isoformat()}, now={now_et.isoformat()})")
            return {"available": False, "reason": "that time has already passed"}

        slot_end = candidate + timedelta(minutes=60)
        # 15-min buffer before and after to avoid back-to-back meetings
        window_start = candidate - timedelta(minutes=15)
        window_end = slot_end + timedelta(minutes=15)

        events_result = service.events().list(
            calendarId=CALENDAR_ID,
            timeMin=window_start.isoformat(),
            timeMax=window_end.isoformat(),
            singleEvents=True,
            orderBy="startTime"
        ).execute(num_retries=3)

        blocking_events = []
        for event in events_result.get("items", []):
            start_info = event.get("start", {})
            end_info = event.get("end", {})
            # Skip all-day events
            if "dateTime" not in start_info or "dateTime" not in end_info:
                continue
            # Skip FREE events (transparency="transparent") — they're reminders,
            # not real blocks. Only "opaque" (busy) events block availability.
            if event.get("transparency") == "transparent":
                continue
            ev_start = datetime.fromisoformat(start_info["dateTime"]).astimezone(tz)
            ev_end = datetime.fromisoformat(end_info["dateTime"]).astimezone(tz)
            # Check overlap against the BUFFERED window, not the raw slot time.
            # This must match book_appointment's race guard logic — any busy event
            # inside the buffer window blocks the slot (prevents back-to-back meetings).
            if ev_start < window_end and ev_end > window_start:
                blocking_events.append(f"{event.get('summary', 'Unnamed')} ({ev_start.strftime('%H:%M')}–{ev_end.strftime('%H:%M')})")

        if blocking_events:
            print(f"[check_specific_slot] rejected: blocked by events: {blocking_events}")
            return {"available": False, "reason": "that time is already booked"}

        print(f"[check_specific_slot] AVAILABLE: {candidate.isoformat()}")
        return {
            "available": True,
            "slot_id": candidate.isoformat(),
            "display": candidate.strftime("%A, %B %d at %I:%M %p EST")
        }

    except Exception as e:
        print(f"[check_specific_slot] ERROR: {e}")
        return {"available": False, "reason": "could not verify that time"}


def studio_visit_gate(tool_input, sender):
    """PATCH #74 — may this booking become an IN-PERSON studio visit?

    Returns None to allow, or a dict to hand straight back to Maya as a refusal.

    Michael, Aug 10 2026, after losing a 10 AM hour to a hobbyist musician:
    "we only bring the right type of leads — business owners, entrepreneurs,
    people that can spend at least $349."

    The rule is older than the incident. MAYA.md §51, Jul 29, written the day
    Dondrique Lewis was correctly told "$100 isn't in our range" and was handed
    a founder slot anyway: "Declining the number is not enough — the booking
    must not happen." It lived only in an agent notebook, which nothing in this
    process reads, so for twelve days nothing enforced it. It is enforced here.

    Strategy calls are deliberately NOT gated. A call costs thirty remote
    minutes and is exactly where an unqualified lead is supposed to land.
    """
    declined = bool((lead_data.get(sender) or {}).get("budget_declined")) if sender else False

    # S84: the floor is source-conditional. `ad_id` / `utm_campaign` /
    # `ad_referral` have been on the lead record since S27 — nothing had
    # ever read them, so a lead who arrived on the $349 campaign was being
    # qualified at $249 and the campaign undercut its own economics.
    _attr = (lead_data.get(sender) or {}) if sender else {}
    _floor = event_rail.applicable_floor(
        ad_id=_attr.get("ad_id"),
        utm_campaign=_attr.get("utm_campaign"),
        ad_referral=_attr.get("ad_referral"),
    )

    # PATCH #75 — a CALL is gated too, at a lower bar. #74 kept unqualified
    # leads out of the studio and left them landing on Michael's calendar
    # instead, which is the only diary that cannot be cloned. Michael, the
    # same day: "Lance is another Joseph. Not even worth it for the call."
    if tool_input.get("appointment_type", "studio_visit") != "studio_visit":
        ok, why = event_rail.strategy_call_verdict(
            role=tool_input.get("lead_role"),
            business=tool_input.get("lead_business"),
            stated_budget=tool_input.get("stated_budget"),
            budget_declined=declined,
            floor=_floor,
        )
        if ok:
            return None
        print(f"[book_appointment] REFUSED strategy_call — {why}")
        try:
            _TALLY.bump("booking.strategy_call_unqualified", why[:120])
        except Exception:
            pass
        try:
            _notify_error_to_dev(
                "Unqualified Founder Call Blocked",
                f"{tool_input.get('lead_name', 'A lead')} was refused a strategy "
                f"call: {why} (role={tool_input.get('lead_role')!r}, "
                f"business={tool_input.get('lead_business')!r}, "
                f"stated_budget={tool_input.get('stated_budget')!r}). "
                f"Maya was redirected to pricing + the booking link.",
                lead_info=f"{tool_input.get('lead_name', '')} ({sender})",
                severity="INFO",
            )
        except Exception:
            pass
        return {"error": why}

    ok, why = event_rail.studio_visit_verdict(
        role=tool_input.get("lead_role"),
        business=tool_input.get("lead_business"),
        stated_budget=tool_input.get("stated_budget"),
        budget_declined=declined,
        floor=_floor,
    )

    # Remember a stated sub-floor number FOREVER. Dondrique came back eight
    # days after being declined; a gate that forgets holds for one conversation.
    try:
        stated = tool_input.get("stated_budget")
        if (not ok and stated is not None and sender and sender in lead_data
                and float(stated) < float(_floor)):
            lead_data[sender]["budget_declined"] = True
    except (TypeError, ValueError):
        pass

    if ok:
        return None

    print(f"[book_appointment] REFUSED studio_visit — {why}")
    try:
        _TALLY.bump("booking.studio_visit_unqualified", why[:120])
    except Exception:
        pass
    try:
        _notify_error_to_dev(
            "Unqualified Studio Visit Blocked",
            f"{tool_input.get('lead_name', 'A lead')} was refused an in-person "
            f"studio visit: {why} (role={tool_input.get('lead_role')!r}, "
            f"business={tool_input.get('lead_business')!r}, "
            f"stated_budget={tool_input.get('stated_budget')!r}). "
            f"Maya was redirected to the free strategy call.",
            lead_info=f"{tool_input.get('lead_name', '')} ({sender})",
            severity="INFO",
        )
    except Exception:
        pass
    return {"error": why}


def handle_tool_call(tool_name, tool_input, sender=None):
    """Execute a tool call and return the result as a dict."""
    if tool_name == "get_available_slots":
        slots = get_available_slots()
        if slots:
            return {"slots": slots}
        else:
            return {"error": "Calendar check failed or no preferred slots found. Ask the lead to suggest a preferred day and time, then use check_specific_slot."}

    elif tool_name == "check_specific_slot":
        return check_specific_slot(tool_input["requested_datetime"])

    elif tool_name == "request_out_of_hours_approval":
        return request_out_of_hours_approval(
            lead_name=tool_input.get("lead_name", ""),
            lead_email=tool_input.get("lead_email", ""),
            lead_phone=sender,
            slots=tool_input.get("slots") or [],
            business=tool_input.get("business", ""),
            note=tool_input.get("note", ""),
            channel=resolve_channel(sender),
        )

    elif tool_name == "book_appointment":
        # ── PATCH #57 gate 1: exchange proposals are not booked ──
        # Read from the LEAD's own turns, never from Maya's — her property
        # management script says "One partnership = dozens of compliant
        # clients", and scanning her side would refuse every one of those.
        _hist = (ig_conversation_history.get(sender)
                 or conversation_history.get(sender)
                 or []) if sender else []
        _barter = barter_signal_in_history(_hist)
        if _barter == BARTER_YES:
            print(f"[book_appointment] REFUSED — barter proposal from {sender}")
            try:
                _notify_error_to_dev(
                    "Barter Booking Blocked",
                    f"{tool_input.get('lead_name', 'A lead')} proposed an exchange "
                    f"rather than payment. Booking refused; Maya redirected them "
                    f"to {PARTNERSHIP_INBOX}.",
                    lead_info=f"{tool_input.get('lead_name', '')} ({sender})",
                    severity="INFO",
                )
            except Exception:
                pass
            return {"error": barter_refusal_note(tool_input.get("lead_name"))}

        # ── PATCH #74 gate 2: qualification, studio visits only ──
        _q_refusal = studio_visit_gate(tool_input, sender)
        if _q_refusal:
            return _q_refusal

        event_id = book_appointment(
            slot_id=tool_input["slot_id"],
            lead_name=tool_input["lead_name"],
            lead_email=tool_input["lead_email"],
            lead_business=tool_input["lead_business"],
            lead_phone=sender,
            callback_phone=tool_input.get("callback_phone"),
            appointment_type=tool_input.get("appointment_type", "studio_visit"),
            # Patch #30: pass the resolved channel explicitly. This is THE
            # call-site that produced every mislabelled event — it omitted the
            # argument, so the old default stamped "WhatsApp" on Instagram
            # bookings. `sender` is "instagram:<IGSID>" for IG threads.
            booked_via=resolve_channel(sender),
        )
        # PATCH #57 — a refusal comes back as a dict, and a dict is truthy.
        # Without this the old `if event_id:` would treat "no number to dial"
        # as a successful booking and fire the whole confirmation chain.
        if isinstance(event_id, dict):
            return {"error": event_id.get("instruction") or event_id.get("reason")}
        if event_id:
            # Update Google Sheets row with booking status
            try:
                update_booking_in_sheets(
                    sender=sender,
                    appointment_type=tool_input.get("appointment_type", "studio_visit"),
                    slot_id=tool_input["slot_id"],
                    lead_name=tool_input.get("lead_name", ""),
                    lead_email=tool_input.get("lead_email", ""),
                    lead_business=tool_input.get("lead_business", ""),
                )
            except Exception as sheets_err:
                print(f"â ï¸ Sheets booking update error (non-fatal): {sheets_err}")

            # ââ Notify Hub â triggers confirmation email + WhatsApp + Calendar ââ
            try:
                appt_type  = tool_input.get("appointment_type", "studio_visit")
                hub_event  = "booking_confirmed_tour" if appt_type == "studio_visit" else "booking_confirmed_call"
                # Mark lead as booked and store event_id + lead details for cancellation support
                if sender and sender in lead_data:
                    lead_data[sender]["booked"] = True
                    # PATCH #49A — `booked` alone is unusable as a stop signal.
                    # It is set here and never cleared on a no-show or a
                    # cancellation, so it has always meant "booked at some
                    # point", not "has an appointment coming". #48B read it as
                    # the latter and silently cancelled a follow-up sequence in
                    # production. A flag without a timestamp cannot answer
                    # "did this happen before or after the sequence was armed?"
                    lead_data[sender]["booked_at"] = datetime.now(
                        pytz.timezone(TIMEZONE)).isoformat()
                    lead_data[sender]["event_id"] = event_id
                    # Backfill lead name/email/business from booking — fixes "Unknown" leads
                    _book_name = tool_input.get("lead_name", "").strip()
                    _book_email = tool_input.get("lead_email", "").strip()
                    _book_biz = tool_input.get("lead_business", "").strip()
                    if _book_name and (not lead_data[sender].get("name") or lead_data[sender].get("name", "").lower() in ("unknown", "there", "")):
                        lead_data[sender]["name"] = _book_name
                        print(f"[book_appointment] Backfilled lead name: {_book_name}")
                    if _book_email and not lead_data[sender].get("email"):
                        lead_data[sender]["email"] = _book_email
                        print(f"[book_appointment] Backfilled lead email: {_book_email}")
                    if _book_biz and not lead_data[sender].get("business"):
                        lead_data[sender]["business"] = _book_biz
                fire_hub_event(
                    event_type  = hub_event,
                    lead_name   = tool_input.get("lead_name"),
                    lead_phone  = sender,
                    lead_email  = tool_input.get("lead_email"),
                    payload     = {
                        "booking_time": tool_input["slot_id"],
                        "booking_type": appt_type,
                    },
                )
            except Exception as hub_err:
                print(f"â ï¸ Hub booking event error (non-fatal): {hub_err}")


            # ── Pipeline Event: BOOKING ──
            _ld_book = lead_data.get(sender, {})
            _book_agents = ["Maya", "Susan", "Eric"]
            if _ld_book.get("email"):
                _book_agents.append("LARA")
            _post_pipeline_event(
                "BOOKING",
                lead_name=tool_input.get("lead_name", ""),
                lead_phone=sender,
                source=_ld_book.get("source", "WhatsApp"),
                old_stage="Engaged",
                new_stage="Booked",
                assigned_agents=_book_agents,
                context=f"Booked {tool_input.get('appointment_type', 'studio_visit')} for {tool_input.get('slot_id', 'N/A')}",
                extra_fields={
                    "Email": tool_input.get("lead_email", "N/A"),
                    "Business": tool_input.get("lead_business", "N/A"),
                }
            )

            return {"success": True, "event_id": event_id}
        else:
            return {"success": False, "error": "Could not book the appointment. Please try again."}

    elif tool_name == "cancel_appointment":
        return cancel_appointment(
            sender=sender,
            lead_name=tool_input.get("lead_name", ""),
            cancel_reason=tool_input.get("cancel_reason", "No reason provided"),
            event_date=tool_input.get("event_date", "")
        )

    return {"error": f"Unknown tool: {tool_name}"}


