# ── Daily Briefing Daemon (Session 30.14b) ──────────────────────────
def _daily_briefing_thread():
    """Sends daily briefing email at 7 AM Eastern every day."""
    import time
    import pytz as _pytz
    from datetime import datetime, timedelta
    import traceback

    EASTERN = _pytz.timezone("America/New_York")
    BRIEFING_HOUR = 7
    PERSONAL_CAL = "michael@mwmcreations.com"
    MWM_CAL = "c_03s30bthurplevpk6a264h7n34@group.calendar.google.com"

    def _seconds_until_next(hour):
        now = datetime.now(EASTERN)
        target = now.replace(hour=hour, minute=0, second=0, microsecond=0)
        if now >= target:
            target += timedelta(days=1)
        return (target - now).total_seconds()

    def _fetch_events(cal_service, calendar_id, date_obj):
        start = date_obj.isoformat() + "T00:00:00"
        end = date_obj.isoformat() + "T23:59:59"
        try:
            result = cal_service.events().list(
                calendarId=calendar_id,
                timeMin=start + "-04:00",
                timeMax=end + "-04:00",
                singleEvents=True,
                orderBy="startTime",
                timeZone="America/New_York",
            ).execute(num_retries=3)
            return result.get("items", [])
        except Exception:
            return []

    def _format_event(ev):
        s = ev.get("start", {})
        summary = ev.get("summary", "(sem titulo)")
        if "dateTime" in s:
            try:
                from datetime import datetime as _dt
                dt = _dt.fromisoformat(s["dateTime"].replace("Z", "+00:00"))
                return f"  {dt.astimezone(EASTERN).strftime('%H:%M')} - {summary}"
            except Exception:
                return f"  {s['dateTime'][11:16]} - {summary}"
        return f"  (dia inteiro) - {summary}"

    def _build_and_send():
        from datetime import date
        import base64
        from email.mime.text import MIMEText

        today = date.today()
        dias = {
            0: "Segunda-feira", 1: "Terca-feira", 2: "Quarta-feira",
            3: "Quinta-feira", 4: "Sexta-feira", 5: "Sabado", 6: "Domingo"
        }
        meses = {
            1: "Janeiro", 2: "Fevereiro", 3: "Marco", 4: "Abril",
            5: "Maio", 6: "Junho", 7: "Julho", 8: "Agosto",
            9: "Setembro", 10: "Outubro", 11: "Novembro", 12: "Dezembro"
        }
        date_str = f"{dias.get(today.weekday(), '')}, {today.day} de {meses.get(today.month, '')} de {today.year}"

        cal = get_calendar_service(impersonate=MICHAEL_EMAIL)
        personal = _fetch_events(cal, PERSONAL_CAL, today)
        mwm = _fetch_events(cal, MWM_CAL, today)

        lines = [
            "Bom dia, Michael!", "",
            f"Briefing Diario - {date_str}", "",
            "Agenda de Hoje:", "",
        ]
        has = False
        if personal:
            has = True
            lines.append("Calendario Pessoal:")
            lines.extend(_format_event(e) for e in personal)
            lines.append("")
        if mwm:
            has = True
            lines.append("Calendario MWM CREATIONS:")
            lines.extend(_format_event(e) for e in mwm)
            lines.append("")
        if not has:
            lines.append(
                "Nenhum evento agendado para hoje em nenhum dos "
                "calendarios (Pessoal e MWM CREATIONS)."
            )
            lines.append("")
            if today.weekday() >= 5:
                lines.append(
                    "Seu fim de semana esta livre! "
                    "Aproveite para descansar."
                )
            else:
                lines.append(
                    "Seu dia esta livre! Boa oportunidade "
                    "para focar em projetos pendentes."
                )
            lines.append("")
        lines.extend([
            "Se precisar de algo, estou aqui.", "",
            "ANA | MWM Creations AI Assistant",
        ])

        body = "\n".join(lines)
        subject = f"Briefing Diario - {date_str}"

        gmail = get_gmail_service(impersonate=MICHAEL_EMAIL)
        msg = MIMEText(body, "plain")
        msg["To"] = MICHAEL_EMAIL
        msg["From"] = MICHAEL_EMAIL
        msg["Subject"] = subject
        raw = base64.urlsafe_b64encode(msg.as_bytes()).decode()
        gmail.users().messages().send(
            userId="me", body={"raw": raw}
        ).execute()  # S28: NO retries on message sends — ambiguous 5xx retry could double-send
        print(f"[BRIEFING] Sent daily briefing for {date_str}")

    print("[BRIEFING] Daily briefing thread started")
    while True:
        try:
            _heartbeat("daily_briefing")
            wait = _seconds_until_next(BRIEFING_HOUR)
            print(f"[BRIEFING] Next briefing in {wait/3600:.1f}h")
            # Sleep in 15-min chunks so watchdog sees heartbeats
            remaining = wait
            while remaining > 0:
                chunk = min(remaining, 900)  # 15 min max
                time.sleep(chunk)
                remaining -= chunk
                _heartbeat("daily_briefing")
            _build_and_send()
        except Exception as exc:
            print(f"[BRIEFING] Error: {exc}")
            traceback.print_exc()
            time.sleep(600)  # retry in 10 min on error



# ─── S6.7b: WhatsApp delivery-status callbacks → error bus ──────────────────
# Jul 5 billing incident + US-marketing-pause discovery were both invisible
# because status webhooks were discarded. This captures them: per-status log,
# daily counters (pg key wa_delivery_counters:YYYY-MM-DD), failed → error bus
# keyed by Meta error code, and a consecutive-failure streak escalation.
_wa_status_streak = {"failed": 0}

def send_wa_utility_template(to, template_name, body_params, phone_number_id=None, lang="en_US"):
    """Send an approved WhatsApp TEMPLATE via Meta Cloud API (S24b).

    Templates are exempt from the 24h window — that is their entire purpose —
    but still respect the bad-number suppression list. body_params fill the
    template's {{1}}..{{n}} body variables in order. Returns the API response
    dict on success, None on failure (caller decides the fallback)."""
    _ok, _why = wa_send_eligibility(to, is_template=True)
    if not _ok:
        print(f"[WA-TEMPLATE] BLOCKED {template_name} to {_wa_tail(to)} — {_why}")
        return None
    pn_id = phone_number_id or META_PHONE_NUMBER_ID
    phone = to.replace("whatsapp:", "").lstrip("+")
    url = f"https://graph.facebook.com/v19.0/{pn_id}/messages"
    headers = {
        "Authorization": f"Bearer {META_ACCESS_TOKEN}",
        "Content-Type": "application/json",
    }
    payload = {
        "messaging_product": "whatsapp",
        "to": phone,
        "type": "template",
        "template": {
            "name": template_name,
            "language": {"code": lang},
            "components": [{
                "type": "body",
                "parameters": [{"type": "text", "text": str(p)} for p in body_params],
            }],
        },
    }
    try:
        r = http_requests.post(url, headers=headers, json=payload, timeout=15)
        if r.status_code == 200:
            print(f"[WA-TEMPLATE] {template_name} sent to {_wa_tail(to)}")
            return r.json()
        print(f"[WA-TEMPLATE] {template_name} FAILED {r.status_code}: {r.text[:200]}")
        _report_error("wa_template_send", f"{template_name} HTTP {r.status_code}",
                      f"to={_wa_tail(to)} {r.text[:150]}")
        return None
    except Exception as e:
        _report_error("wa_template_send", e, f"{template_name} to={_wa_tail(to)}")
        return None



