        if sender not in lead_data:
            lead_data[sender] = {"source": "WhatsApp", "first_contact_time": datetime.now(pytz.timezone(TIMEZONE))}
        lead_data[sender]["last_message_time"] = datetime.now(pytz.timezone(TIMEZONE))

