def _send_welcome_email_async(to_email, lead_name, source="form"):
    """Send the welcome email in a background thread. Non-blocking, non-fatal."""
    def _do_send():
        try:
            # S24: To-header guard. Lead rows sometimes hold two names/emails jammed
            # into one field ("a@x.com / b@y.com") -> Gmail 400 "Invalid To header".
            # Extract real addresses: first one is To, the rest become CC. Fail loud
            # (existing error path) if no valid address can be extracted.
            import re as _re
            _addrs = _re.findall(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", str(to_email or ""))
            if not _addrs:
                _report_error("Welcome email send",
                              Exception("no valid email address in To field"),
                              f"raw_to={str(to_email)[:120]}")
                _post_to_slack_async(SLACK_DEV_CHANNEL,
                    f"⚠️ Welcome email SKIPPED — unparseable To field: {str(to_email)[:120]} ({lead_name})")
                return
            _clean_to = _addrs[0]
            _clean_cc = ",".join(_addrs[1:]) if len(_addrs) > 1 else None
            if _clean_to != str(to_email).strip():
                print(f"[Welcome Email] To-guard normalized {str(to_email)[:80]!r} -> to={_clean_to} cc={_clean_cc}")
            html = _build_welcome_email_html(lead_name)
            _send_kwargs = {}
            if _clean_cc:
                _send_kwargs["cc"] = _clean_cc
            result = send_gmail(
                to=_clean_to,
                subject="Thank you for reaching out — MWM Creations & Studios",
                body_html=html,
                **_send_kwargs
            )
            if result.get("ok"):
                print(f"[Welcome Email] Sent to {to_email} ({lead_name}) via {source}")
                # S28: stamp welcome time so followup_scheduler can compute
                # Susan's 24h-then-3d cadence per lead email.
                try:
                    import pg_store as _fp
                    if _fp.enabled():
                        _fp.save_state("welcome_email_at:" + _clean_to.lower(),
                                       datetime.now(pytz.timezone(TIMEZONE)).isoformat())
                except Exception as _sx:
                    print(f"[Welcome Email] welcome stamp failed (non-fatal): {_sx}")
                _post_to_slack_async(SLACK_SUSAN_CHANNEL,
                    f"*AUTO — Welcome Email Sent*\n"
                    f"To: {to_email} ({lead_name})\n"
                    f"Source: {source}\n"
                    f"Status: Delivered\n"
                    f"Note: This was the automated welcome. Susan — please send a personalized follow-up based on their form answers."
                )
            else:
                _report_error("Welcome email send", Exception(str(result)[:200]), f"to={to_email}")  # S3b.2
                _post_to_slack_async(SLACK_DEV_CHANNEL,
                    f"⚠️ Welcome email FAILED for {to_email} ({lead_name}): {str(result)[:200]}"
                )
        except Exception as e:
            print(f"[Welcome Email] Error sending to {to_email}: {e}")
            _post_to_slack_async(SLACK_DEV_CHANNEL,
                f"⚠️ Welcome email ERROR for {to_email}: {str(e)[:200]}"
            )
    threading.Thread(target=_do_send, daemon=True).start()


# S24: env-only, fail-closed. The repo is public — a hardcoded default token
# meant anyone reading the source could send mail as info@. If the env var is
# missing the endpoint refuses to send instead of accepting a known default.
SEND_EMAIL_TOKEN = os.getenv("SEND_EMAIL_TOKEN", "")
LARA_SEND_TOKEN = os.getenv("LARA_SEND_TOKEN", "")  # S26: per-agent token (independent revocation)
SUSAN_SEND_TOKEN = os.getenv("SUSAN_SEND_TOKEN", "")  # S28: Susan's per-agent token (she was on the dead shared default since Jul 16)

def _api_auth_token(data):
    """S26: multi-token auth for the agent endpoints (/api/send-email,
    /api/send-wa-media). Accepts the token in the JSON body ("token") OR an
    Authorization: Bearer header (alternate transport — the header-vs-body
    trap cost a morning cycle on Jul 22). Returns (ok, via_label).
    Fail-closed: no server tokens configured -> caller returns 503."""
    supplied = str((data or {}).get("token", "") or "")
    if not supplied:
        _auth = request.headers.get("Authorization", "")
        if _auth.startswith("Bearer "):
            supplied = _auth[7:].strip()
    if not supplied:
        return False, None
    if SEND_EMAIL_TOKEN and supplied == SEND_EMAIL_TOKEN:
        return True, "master"
    if LARA_SEND_TOKEN and supplied == LARA_SEND_TOKEN:
        return True, "lara"
    if SUSAN_SEND_TOKEN and supplied == SUSAN_SEND_TOKEN:
        return True, "susan"  # S28
    return False, None


@app.route('/api/send-wa-media', methods=['POST'])
def api_send_wa_media():
    """S25a: Universal agent endpoint — send a WhatsApp attachment (document/
    image/video/audio) to a lead via the Meta Cloud API.

    Why: browser automation cannot attach files in WhatsApp Web (the send step
    rejects injected File objects — "file not supported"), so agent sessions
    (LARA/MAYA) route ad-hoc media through here instead.

    JSON body:
        token: auth token (required — same SEND_EMAIL_TOKEN as /api/send-email)
        to: recipient phone, any format (required)
        media_url: PUBLIC direct-download URL (required). Google Drive share
                   links are auto-converted to uc?export=download form.
        filename: display filename e.g. "CallSheet.pdf" (recommended — drives
                  type classification for extension-less URLs)
        caption: optional caption under the attachment

    Media is a FREE-FORM send: the eligibility gate applies (suppression +
    24h window). A closed window returns 409 with the reason instead of
    burning the send.
    """
    try:
        data = request.get_json(force=True)
        if not SEND_EMAIL_TOKEN and not LARA_SEND_TOKEN and not SUSAN_SEND_TOKEN:
            return jsonify({"success": False, "error": "endpoint disabled: no server token configured"}), 503
        _auth_ok, _via = _api_auth_token(data)
        if not _auth_ok:
            return jsonify({"success": False, "error": "Invalid or missing token"}), 401
        to = re.sub(r"\D", "", str(data.get("to", "")))
        media_url = str(data.get("media_url", "")).strip()
        filename = str(data.get("filename", "")).strip() or None
        caption = str(data.get("caption", "")).strip() or None
        if not to or len(to) < 10:
            return jsonify({"success": False, "error": "Missing/invalid 'to' phone"}), 400
        if not media_url.startswith("http"):
            return jsonify({"success": False, "error": "media_url must be a public http(s) URL"}), 400
        _gd = re.search(r"drive\.google\.com/(?:file/d/([-\w]{20,})|open\?id=([-\w]{20,}))", media_url)
        if _gd:
            _gid = _gd.group(1) or _gd.group(2)
            media_url = f"https://drive.google.com/uc?export=download&id={_gid}"
        _ok, _why = wa_send_eligibility("+" + to, is_template=False)
        if not _ok:
            # S26: closed 24h window -> fall back to the approved DOCUMENT template
            # (mwm_file_delivery) instead of refusing. Suppressed numbers stay
            # blocked (the template gate re-checks suppression).
            _rname = str(data.get("recipient_name", "")).strip() or "there"
            _flabel = str(data.get("file_label", "")).strip() or (filename or "your file")
            _tpl = send_wa_document_template(f"whatsapp:+{to}", media_url, filename, _rname, _flabel)
            if _tpl:
                _tmid = ""
                try:
                    _tmid = (_tpl.get("messages") or [{}])[0].get("id", "")
                except Exception:
                    pass
                _post_to_slack_async(SLACK_PIPELINE_CHANNEL,
                    f"\U0001F4CE *MEDIA SENT via TEMPLATE (window closed)* — "
                    f"{filename or media_url.split('/')[-1][:40]} \u2192 ...{to[-4:]} \u00b7 via={_via}")
                return jsonify({"success": True, "message_id": _tmid, "sent_via": "template"})
            return jsonify({"success": False,
                            "error": f"send refused pre-flight: {_why}",
                            "hint": "free-form window closed AND template fallback failed/blocked "
                                    "(suppressed number, or template send error — see #dev)"}), 409
        result = send_whatsapp_meta(f"whatsapp:+{to}", media_url=media_url,
                                    filename=filename, caption=caption)
        if result:
            _label = filename or media_url.split("/")[-1][:40]
            _post_to_slack_async(SLACK_PIPELINE_CHANNEL,
                f"\U0001F4CE *MEDIA SENT (agent ad-hoc)* — {_label} \u2192 ...{to[-4:]} \u00b7 via={_via}"
                + (f" \u00b7 caption: {caption[:60]}" if caption else ""))
            _mid = ""
            try:
                _mid = (result.get("messages") or [{}])[0].get("id", "")
            except Exception:
                pass
            return jsonify({"success": True, "message_id": _mid})
        return jsonify({"success": False, "error": "Meta send failed after retries (see #dev alert)"}), 502
    except Exception as e:
        return jsonify({"success": False, "error": str(e)[:200]}), 500


@app.route('/api/send-email', methods=['POST'])
def api_send_email():
    """Universal email send endpoint for agent Cowork sessions.

    Agents compose their own HTML emails with full creative freedom,
    then call this endpoint to deliver from info@mwmcreations.com.

    JSON body:
        to: recipient email (required)
        subject: email subject (required)
        html_body: full HTML email content (required) — agents design this however they want
        body: plain text fallback (optional)
        attachment_filename: filename to search in _AGENTS > UPLOADS Drive folder (optional)
        attachment_drive_id: explicit Drive file ID (optional, overrides filename search)
        token: auth token (required)

    Returns:
        {"success": true, "message_id": "..."} or {"success": false, "error": "..."}
    """
    try:
        data = request.get_json(force=True)

        # Auth check (S24 fail-closed; S26 multi-token + Bearer-header transport)
        if not SEND_EMAIL_TOKEN and not LARA_SEND_TOKEN and not SUSAN_SEND_TOKEN:
            _report_error("send_email_token_missing",
                          "no send tokens set — /api/send-email is disabled",
                          "set SEND_EMAIL_TOKEN (and optionally LARA_SEND_TOKEN / SUSAN_SEND_TOKEN) in Railway Variables")
            return jsonify({"success": False, "error": "send-email disabled: no server token configured"}), 503
        _auth_ok, _via = _api_auth_token(data)
        if not _auth_ok:
            return jsonify({"success": False, "error": "Invalid or missing token"}), 401

        # Required fields
        to_email = data.get("to", "").strip()
        subject = data.get("subject", "").strip()
        html_body = data.get("html_body", "").strip()
        plain_body = data.get("body", "").strip()

        if not to_email:
            return jsonify({"success": False, "error": "Missing 'to' field"}), 400
        if not subject:
            return jsonify({"success": False, "error": "Missing 'subject' field"}), 400
        if not html_body and not plain_body:
            return jsonify({"success": False, "error": "Missing 'html_body' or 'body' field"}), 400

        # PATCH #38 — DNC gate. Before auth-adjacent work, before Drive, before
        # send. 409 is the documented suppression code in SUSAN's playbook.
        _sup, _sup_reason = email_is_suppressed(to_email)
        if _sup:
            print(f"[SEND-EMAIL API] SUPPRESSED {to_email} — {_sup_reason} (via={_via})")
            _report_error("email_send_suppressed",
                          f"send to {to_email} refused: {_sup_reason}",
                          f"via={_via} subject={subject[:80]!r} — PREVENTED, not burned")
            return jsonify({"success": False, "error": f"suppressed: {_sup_reason}",
                            "suppressed": True, "to": to_email}), 409

        # PATCH #38 — an address that cannot be delivered must fail LOUDLY here,
        # not silently bounce hours later. Live case: Anderson Brito Baez,
        # recorded as `AndersonbritoBaez@gmail.com` with an accented a. Gmail
        # rejects non-ASCII local parts, so every send to him was guaranteed to
        # bounce and nothing ever said so.
        _folded, _addr_ok, _addr_note = ascii_email(to_email)
        if not _addr_ok:
            _report_error("email_address_invalid", f"{to_email!r} is not deliverable",
                          f"{_addr_note} — refused before send (via={_via})")
            return jsonify({"success": False, "error": f"invalid recipient address: {_addr_note}",
                            "to": to_email}), 400
        if _folded != to_email.strip():
            print(f"[SEND-EMAIL API] non-ASCII address folded: {to_email!r} -> {_folded!r}")
            to_email = _folded

        # If only plain text provided, use it as HTML too
        if not html_body:
            html_body = plain_body.replace("\n", "<br>")

        # Attachment handling — supports attachment_drive_id, file_id (alias), or attachment_filename (search)
        drive_file_id = data.get("attachment_drive_id", "").strip() or data.get("file_id", "").strip() or None
        attachment_filename = data.get("attachment_filename", "").strip() or None

        if attachment_filename and not drive_file_id:
            # Search Drive for the file by name
            found = search_drive_file(attachment_filename)
            if found:
                drive_file_id = found["id"]
                print(f"[SEND-EMAIL API] Found attachment: {found['name']} ({drive_file_id})")
            else:
                return jsonify({
                    "success": False,
                    "error": f"Attachment not found on Drive: '{attachment_filename}'. Make sure it's in _AGENTS > UPLOADS folder."
                }), 404

        # Send via DWD Gmail API as info@mwmcreations.com.
        # PATCH #44C — goes through the shared sender so the follow-up stamps
        # are written in exactly ONE place for every rail, manual or automatic.
        result = _email_send(to_email, subject, html_body, drive_file_id,
                             via=_via)

        if result.get("ok"):
            print(f"[SEND-EMAIL API] Sent to {to_email} — msgId: {result['message_id']}")
            # PATCH #44C — the stamping that used to live inline here now lives
            # in _email_send(), so the automated rails stamp it too. Removing it
            # from this branch is the whole point: one writer, not two.
            return jsonify({
                "success": True,
                "message_id": result["message_id"],
                "from": SUSAN_SEND_AS,
                "to": to_email,
                "subject": subject,
                "attachment": attachment_filename or (drive_file_id if drive_file_id else None),
            })
        else:
            print(f"[SEND-EMAIL API] Failed: {result['error']}")
            return jsonify({"success": False, "error": result["error"]}), 500

    except Exception as e:
        print(f"[SEND-EMAIL API] Error: {e}")
        traceback.print_exc()
        return jsonify({"success": False, "error": str(e)[:500]}), 500


