# ═══════════════════════════════════════════════════════════════════════════════
# S17 — CALENDLY PHASE A: on-demand studio rental checkout (Stripe)
# Prices are CANONICAL AND SERVER-SIDE. The browser never supplies an amount —
# it sends (hours, editing) and the machine computes the price. Anything else
# lets a customer book 5 hours for $1.
# Mirrors /book-studio's published pricing (studio $249/hr, +$100/hr editing).
# ═══════════════════════════════════════════════════════════════════════════════
STUDIO_RENTAL_PRICING = {
    "studio":  {1: 24900, 2: 49800, 3: 74700, 4: 99600, 5: 124500},   # cents
    "editing": {1: 34900, 2: 69800, 3: 104700, 4: 139600, 5: 174500},
}
STUDIO_RENTAL_HOLD_MIN = int(os.getenv("STUDIO_RENTAL_HOLD_MIN", "15"))
SITE_BASE_URL = os.getenv("SITE_BASE_URL", "https://mwmcreations.com")


def _rental_price_cents(hours, editing):
    """Authoritative price lookup. Returns None if the tier is invalid.

    STRICT: hours must be a whole number 1-5. A float like 1.5 must NOT be
    silently truncated to 1 — that would charge for 1h while the slot is held
    for 1.5h. Anything not exactly an integer tier is refused.
    """
    if isinstance(hours, bool):
        return None
    if isinstance(hours, float) and not hours.is_integer():
        return None
    if isinstance(hours, str):
        hours = hours.strip()
        if not hours.isdigit():
            return None
    try:
        h = int(hours)
    except (TypeError, ValueError):
        return None
    tier = "editing" if editing else "studio"
    return STUDIO_RENTAL_PRICING.get(tier, {}).get(h)


@app.route('/studio-checkout', methods=['POST'])
def studio_checkout():
    """S17: create a Stripe Checkout Session for an on-demand studio rental.

    Called by WP (/book-studio) AFTER it has written a `pending` booking row
    and is holding the slot. Auth = X-MWM-Portal-Secret (S12 pattern).

    Body: {booking_id, date: YYYY-MM-DD, start_time: HH:MM, hours: 1..5,
           editing: bool, name, email}
    Returns: {ok, url, session_id, amount_cents}
    """
    _sc_secret = os.getenv("WP_PORTAL_SECRET", "")
    if not _sc_secret:
        _report_error("studio_checkout", "WP_PORTAL_SECRET not set")
        return jsonify({"ok": False, "error": "not configured"}), 503
    if request.headers.get("X-MWM-Portal-Secret", "") != _sc_secret:
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    data = request.get_json(force=True, silent=True) or {}
    booking_id = str(data.get("booking_id", "")).strip()
    date       = str(data.get("date", "")).strip()
    start_time = str(data.get("start_time", ""))[:5]
    hours      = data.get("hours")
    editing    = bool(data.get("editing"))
    name       = str(data.get("name", "")).strip()[:120]
    email      = str(data.get("email", "")).strip()[:200]

    if not (booking_id and date and start_time and email):
        return jsonify({"ok": False, "error": "missing fields"}), 400

    amount = _rental_price_cents(hours, editing)
    if amount is None:
        _report_error("studio_checkout", f"invalid tier hours={hours!r} editing={editing!r}")
        return jsonify({"ok": False, "error": "invalid tier"}), 400

    label = f"{int(hours)}h Studio + Editing" if editing else f"{int(hours)}h Podcast Studio"
    desc  = f"{date} at {start_time} — 1500 Park Center Dr, Suite 230, Orlando FL"

    # Patch #36 — forward-write the lead_key. Enrichment, never a gate: a
    # resolver failure must never stop a paying customer from checking out.
    try:
        _lead_key, _lead_key_via = _resolve_lead_key_for_payment(email, name)
    except Exception as _lkx:
        _lead_key, _lead_key_via = None, "error"
        _report_error("studio_checkout.lead_key", _lkx, f"booking={booking_id}")

    try:
        # Stripe Checkout Session (form-encoded; rob_stripe._stripe_post pattern)
        payload = {
            "mode": "payment",
            # S22 E2E finding: without this, Stripe offers every dashboard-enabled
            # method incl. ACH bank debit, which settles in 1-4 days — the session
            # completes UNPAID, our handler (correctly) doesn't confirm, and the
            # 15-min hold expires long before the money moves. Card settles
            # instantly, matching the hold model. Rentals are card-only.
            "payment_method_types[0]": "card",
            "success_url": f"{SITE_BASE_URL}/book-studio/?booking=success&id={booking_id}",
            "cancel_url":  f"{SITE_BASE_URL}/book-studio/?booking=cancelled&id={booking_id}",
            "customer_email": email,
            "line_items[0][price_data][currency]": "usd",
            "line_items[0][price_data][unit_amount]": str(amount),
            "line_items[0][price_data][product_data][name]": label,
            "line_items[0][price_data][product_data][description]": desc,
            "line_items[0][quantity]": "1",
            "metadata[kind]": "studio_rental",
            "metadata[booking_id]": booking_id,
            "metadata[date]": date,
            "metadata[start_time]": start_time,
            "metadata[hours]": str(int(hours)),
            "metadata[editing]": "1" if editing else "0",
            "metadata[name]": name,
            "metadata[email]": email,
            "metadata[lead_key_via]": _lead_key_via,
            "expires_at": str(int(time.time()) + max(STUDIO_RENTAL_HOLD_MIN, 30) * 60),
        }
        # Only written when we actually resolved one. An empty metadata value
        # would be indistinguishable from "we never tried".
        if _lead_key:
            payload["metadata[lead_key]"] = _lead_key

        import rob_stripe as _rs
        res = _rs._stripe_post("checkout/sessions", payload)
        if not res or res.get("error") or not res.get("url"):
            _report_error("studio_checkout.stripe",
                          str((res or {}).get("error", "no url"))[:200],
                          f"booking={booking_id}")
            return jsonify({"ok": False, "error": "stripe failed"}), 502

        import pg_store as _pg
        if _pg.enabled():
            try:
                _pg.save_state(f"studio_rental_session:{res.get('id')}", {
                    "booking_id": booking_id, "date": date, "start_time": start_time,
                    "hours": int(hours), "editing": editing, "name": name,
                    "email": email, "amount_cents": amount,
                    "lead_key": _lead_key, "lead_key_via": _lead_key_via,
                    "created": datetime.now(pytz.timezone(TIMEZONE)).isoformat(),
                })
            except Exception as _px:
                _report_error("studio_checkout.persist", _px, f"booking={booking_id}")

        print(f"[RENTAL] checkout created booking={booking_id} {label} ${amount/100:.2f} "
              f"lead_key={_lead_key or '-'} via={_lead_key_via} "
              f"session={str(res.get('id'))[-8:]}")
        return jsonify({"ok": True, "url": res.get("url"),
                        "session_id": res.get("id"), "amount_cents": amount}), 200
    except Exception as _cx:
        _report_error("studio_checkout", _cx, f"booking={booking_id}")
        return jsonify({"ok": False, "error": "exception"}), 500


def _confirm_rental_in_wp(booking_id, session_id, amount_cents):
    """Tell WP the rental is paid → flip pending → confirmed. WP then runs the
    existing S12 chain (client email + gcal + #matt alert).

    S21: MUST send a non-default User-Agent. The host WAF (Bluehost/Endurance
    mod_security) returns HTTP 406 to any request whose UA is the default
    'python-requests/*' — the same block studio_package.py already works around
    (WP_UA). This call was missed: booking #51 (Jul 15) silently 406'd here, so
    the client PAID in Stripe but WP never confirmed it (no email, no calendar).
    Now retries and alerts LOUDLY so a paid-but-unconfirmed booking is never
    silent again. WP confirm is idempotent, so retry is safe."""
    import time as _t
    url = os.getenv("WP_PORTAL_PROVISION_URL",
                    "https://mwmcreations.com/wp-admin/admin-ajax.php")
    secret = os.getenv("WP_PORTAL_SECRET", "")
    headers = {
        "X-MWM-Portal-Secret": secret,
        "User-Agent": "MWM-SalesMachine/1.0 (+https://mwmcreations.com)",
    }
    body = {
        "action": "mwm_studio_confirm_rental",
        "booking_id": booking_id,
        "session_id": session_id,
        "amount_cents": amount_cents,
    }
    last = ""
    for attempt in range(3):
        try:
            r = http_requests.post(url, data=body, headers=headers, timeout=10)
            ok = r.status_code == 200 and '"success":true' in (r.text or "").lower().replace(" ", "")
            print(f"[RENTAL] WP confirm booking={booking_id} -> {r.status_code} ok={ok} (attempt {attempt+1}/3)")
            if ok:
                return True
            last = f"HTTP {r.status_code}: {(r.text or '')[:150]}"
        except Exception as _wx:
            last = repr(_wx)
            print(f"[RENTAL] WP confirm booking={booking_id} attempt {attempt+1}/3 error: {_wx}")
        if attempt < 2:
            _t.sleep(2 ** attempt)
    _report_error("rental_confirm_wp_failed",
                  f"WP confirm FAILED for PAID booking #{booking_id} after 3 attempts",
                  f"{last} — payment captured in Stripe but WP booking is NOT confirmed "
                  f"(no client email, no calendar event). Needs manual reconcile.")
    try:
        _post_to_slack_async(
            SLACK_DEV_CHANNEL,
            f":rotating_light: *Paid studio rental #{booking_id} did NOT confirm in WP* — {last}\n"
            f"Stripe captured payment but WP never confirmed it (no client email, no calendar). "
            f"Manual reconcile needed.")
    except Exception:
        pass
    return False


def handle_studio_rental_paid(event):
    """Route a checkout.session.completed event that is a studio rental.
    Idempotent on the Stripe event id. Returns True if handled (so the package
    handler can be skipped), False if this isn't a rental event."""
    import pg_store as _pg
    session = (event.get("data", {}) or {}).get("object", {}) or {}
    meta = session.get("metadata", {}) or {}
    if meta.get("kind") != "studio_rental":
        return False

    event_id   = event.get("id", "")
    booking_id = meta.get("booking_id", "")
    idem_key   = f"studio_rental_evt:{event_id}"
    if _pg.enabled():
        try:
            if _pg.load_state(idem_key, False):
                print(f"[RENTAL] duplicate event {event_id} — skipped")
                return True
        except Exception:
            pass

    paid = session.get("payment_status") == "paid"
    amount = session.get("amount_total", 0)
    _rk = meta.get("lead_key", "")
    _rk_via = meta.get("lead_key_via", "")
    print(f"[RENTAL] checkout.session.completed booking={booking_id} "
          f"paid={paid} amount={amount} lead_key={_rk or '-'} via={_rk_via or 'pre-#36'}")

    if not paid:
        # S22: delayed-settlement method (e.g. ACH) slipped through — the money
        # arrives days later via async_payment_succeeded, which nothing handles.
        # Alert LOUDLY so it gets reconciled by hand; checkout is card-only now,
        # so this firing at all means something re-enabled a delayed method.
        _report_error("rental_delayed_payment",
                      f"rental booking #{booking_id} completed checkout UNPAID",
                      "delayed-settlement payment method used — booking will NOT "
                      "auto-confirm when it settles; manual reconcile required")
        try:
            _post_to_slack_async(
                SLACK_DEV_CHANNEL,
                f":rotating_light: *Studio rental #{booking_id} used a DELAYED payment method* "
                f"(ACH/bank). It will settle in days and will NOT auto-confirm — manual "
                f"reconcile needed when it settles. Checkout should be card-only; investigate.")
        except Exception:
            pass

    confirmed = True
    if paid:
        # S22 gap #2/#3: capture the confirm result — the #matt message must
        # never show green on a failed confirm, and the idem key must only be
        # written on success so Stripe's automatic retries can self-heal a
        # transient confirm failure (booking #51 could not, because the event
        # was marked processed despite the 406).
        confirmed = _confirm_rental_in_wp(booking_id, session.get("id", ""), amount)
        _sr_status = ("" if confirmed else
                      "\n:rotating_light: *WP CONFIRM FAILED* — client has NOT "
                      "received a confirmation email and the calendar is NOT "
                      "updated. See #dev alert. Stripe will retry this event.")
        try:
            _post_to_slack_async(
                "#matt",
                f":moneybag: *Studio rental PAID* — {meta.get('name','?')} "
                f"{('`' + _rk + '`') if _rk else ('(lead unmatched)' if _rk_via == 'unmatched' else '')} "
                f"({meta.get('email','?')})\n"
                f"{meta.get('hours','?')}h "
                f"{'Studio + Editing' if meta.get('editing')=='1' else 'Podcast Studio'} · "
                f"{meta.get('date','?')} {meta.get('start_time','?')} · "
                f"${amount/100:.2f} · booking #{booking_id}{_sr_status}")
        except Exception:
            pass

    if _pg.enabled() and confirmed:
        try:
            _pg.save_state(idem_key, True)
        except Exception:
            pass
    return True


# S7.1 — STRIPE WEBHOOK: Studio Package purchase -> portal account +
# welcome email + PACKAGE_PURCHASED + LARA/#matt alerts (studio_package.py)
# Fast-ACK: verify signature, then process in a background thread so
# Stripe never times out and retries stack idempotently on event.id.
# ══════════════════════════════════════════════════════════════════════
@app.route('/webhook/stripe', methods=['POST'])
def stripe_webhook():
    payload = request.get_data()
    sig = request.headers.get("Stripe-Signature", "")
    if not _studio.webhook_secret_configured():
        _report_error("stripe_webhook", "Stripe webhook secret not set (env or pg_store)")
        return jsonify({"error": "not configured"}), 503
    if not _studio.verify_stripe_signature(payload, sig):
        print("[STRIPE] Webhook rejected — bad signature")
        return jsonify({"error": "invalid signature"}), 400
    try:
        _sw_event = json.loads(payload)
    except Exception:
        return jsonify({"error": "bad payload"}), 400

    def _sw_process(ev):
        try:
            # S17: on-demand studio rentals are routed first. Returns True if it
            # owned the event, so the package handler never sees a rental.
            if ev.get("type") == "checkout.session.completed" and handle_studio_rental_paid(ev):
                return
            _sw_res = _studio.handle_stripe_event(ev)
            print(f"[STRIPE] {ev.get('type')} ({ev.get('id')}) -> {_sw_res}")
        except Exception as _sw_e:
            _report_error("stripe_webhook.process", _sw_e, f"event={ev.get('id')}")

    threading.Thread(target=_sw_process, args=(_sw_event,), daemon=True).start()
    return jsonify({"received": True}), 200


# S25d: in-process cache for the availability feed — portal date-clicks were paying
# a live Google Calendar query per request (Michael measured ~8s slot loads, Jul 22).
_SA_CACHE = {}
_SA_CACHE_TTL = 120  # seconds

@app.route('/studio-availability', methods=['GET'])
def studio_availability():
    """S15 + S25d: read-only availability feed for the WP portal's slot filter.
    Returns busy blocks (local HH:MM) from the MWM CREATIONS calendar.
    S25d: optional days=N (1..31) range mode — ONE calendar query covers the whole
    range (busy_by_date), and responses are cached in-process for 120s. Legacy
    single-day "busy" shape is preserved for the requested date.
    Auth = X-MWM-Portal-Secret (same shared secret as /webhook/studio-booking).
    Skips transparent (free) events and all-day events per S15 policy."""
    _sa_secret = os.getenv("WP_PORTAL_SECRET", "")
    if not _sa_secret:
        _report_error("studio_availability", "WP_PORTAL_SECRET not set")
        return jsonify({"error": "not configured"}), 503
    if request.headers.get("X-MWM-Portal-Secret", "") != _sa_secret:
        print("[STUDIO-AVAIL] rejected — bad secret")
        return jsonify({"error": "unauthorized"}), 401
    _sa_date = (request.args.get("date") or "").strip()
    try:
        _sa_day = datetime.strptime(_sa_date, "%Y-%m-%d")
    except Exception:
        return jsonify({"error": "bad date"}), 400
    try:
        _sa_days = int(request.args.get("days", "1"))
    except Exception:
        _sa_days = 1
    _sa_days = max(1, min(31, _sa_days))
    _sa_key = (_sa_date, _sa_days)
    _sa_hit = _SA_CACHE.get(_sa_key)
    if _sa_hit and (time.time() - _sa_hit[0]) < _SA_CACHE_TTL:
        return jsonify(_sa_hit[1])
    try:
        _sa_tz = pytz.timezone(TIMEZONE)
        _sa_range_start = _sa_tz.localize(_sa_day)
        _sa_range_end = _sa_range_start + timedelta(days=_sa_days)
        _sa_svc = get_calendar_service()
        _sa_events = _sa_svc.events().list(
            calendarId=CALENDAR_ID,
            timeMin=_sa_range_start.isoformat(),
            timeMax=_sa_range_end.isoformat(),
            singleEvents=True,
            orderBy="startTime",
            maxResults=2500,
        ).execute(num_retries=3)
        _sa_items = _sa_events.get("items", [])
        _sa_by_date = {}
        for _sa_i in range(_sa_days):
            _sa_start = _sa_range_start + timedelta(days=_sa_i)
            _sa_end = _sa_start + timedelta(days=1)
            _sa_busy = []
            for _sa_ev in _sa_items:
                if _sa_ev.get("transparency") == "transparent":
                    continue  # marked Free — not a real block (incl. default all-day reminders)
                _sa_s = _sa_ev.get("start", {})
                _sa_e = _sa_ev.get("end", {})
                try:
                    if "dateTime" in _sa_s and "dateTime" in _sa_e:
                        _sa_bs = datetime.fromisoformat(_sa_s["dateTime"]).astimezone(_sa_tz)
                        _sa_be = datetime.fromisoformat(_sa_e["dateTime"]).astimezone(_sa_tz)
                    elif "date" in _sa_s and "date" in _sa_e:
                        # S15.1: all-day event explicitly marked Busy — blocks whole day(s).
                        # (Google defaults all-day events to Free/transparent, filtered above.)
                        _sa_bs = _sa_tz.localize(datetime.strptime(_sa_s["date"], "%Y-%m-%d"))
                        _sa_be = _sa_tz.localize(datetime.strptime(_sa_e["date"], "%Y-%m-%d"))  # end date is exclusive
                    else:
                        continue
                except Exception:
                    continue
                if _sa_be <= _sa_start or _sa_bs >= _sa_end:
                    continue
                _sa_cs = max(_sa_bs, _sa_start)
                _sa_ce = min(_sa_be, _sa_end)
                # S15.1 fix: a block running to (or past) next midnight must serialize as
                # "24:00" — "00:00" made multi-day events collapse to zero-length blocks
                # that the plugin discarded (found by Michael: Jul 23-26 convention showed open).
                _sa_end_str = "24:00" if _sa_ce >= _sa_end else _sa_ce.strftime("%H:%M")
                _sa_busy.append({"start": _sa_cs.strftime("%H:%M"), "end": _sa_end_str})
            _sa_by_date[_sa_start.strftime("%Y-%m-%d")] = _sa_busy
        _sa_payload = {
            "date": _sa_date,
            "days": _sa_days,
            "timezone": TIMEZONE,
            "busy": _sa_by_date.get(_sa_date, []),
            "busy_by_date": _sa_by_date,
        }
        _SA_CACHE[_sa_key] = (time.time(), _sa_payload)
        if len(_SA_CACHE) > 200:
            _SA_CACHE.clear()  # crude bound; a cleared cache rebuilds in one query
        print(f"[STUDIO-AVAIL] {_sa_date}+{_sa_days}d served fresh")
        return jsonify(_sa_payload)
    except Exception as _sa_exc:
        _report_error("studio_availability", _sa_exc, f"date={_sa_date}")
        return jsonify({"error": "internal"}), 500


@app.route('/webhook/studio-booking', methods=['POST'])
def studio_booking_webhook():
    """S12: WP portal pushes booking events here (booking_created / booking_cancelled /
    booking_cancelled_late). Auth = X-MWM-Portal-Secret shared secret (same as provisioning).
    Fast-ACK + background processing (Stripe-webhook pattern). Idempotent per booking_id+event."""
    _sb_secret = os.getenv("WP_PORTAL_SECRET", "")
    if not _sb_secret:
        _report_error("studio_booking_webhook", "WP_PORTAL_SECRET not set")
        return jsonify({"error": "not configured"}), 503
    if request.headers.get("X-MWM-Portal-Secret", "") != _sb_secret:
        print("[STUDIO-BOOKING] Webhook rejected — bad secret")
        return jsonify({"error": "unauthorized"}), 401
    try:
        _sb_evt = request.get_json(force=True) or {}
        _SA_CACHE.clear()  # S25d: booking changes invalidate the availability cache
    except Exception:
        return jsonify({"error": "bad payload"}), 400
    if _sb_evt.get("event") not in ("booking_created", "booking_cancelled", "booking_cancelled_late"):
        return jsonify({"error": "unknown event"}), 400

    def _sb_process(evt):
        import pg_store as _sbpg
        try:
            event = evt.get("event")
            bid = str(evt.get("booking_id") or "")
            if not bid:
                return
            idem_key = f"studio_booking_evt:{bid}:{event}"
            if _sbpg.load_state(idem_key):
                print(f"[STUDIO-BOOKING] duplicate {idem_key} — skipped")
                return
            name = evt.get("client_name") or "Client"
            date = evt.get("date") or ""
            start = str(evt.get("start_time") or "")[:5]  # HH:MM — WP sends HH:MM:SS
            end = str(evt.get("end_time") or "")[:5]
            if event == "booking_created":
                gcal_note = "calendar ⚠️ failed"
                _sb_state = "failed"          # PATCH #59 — pessimistic default
                _sb_degraded = ""
                try:
                    # PATCH #69 — ASK FOR DELEGATION. Domain-wide delegation has
                    # been granted to this service account the whole time
                    # (client 116770307274894749674, scope .../auth/calendar) —
                    # but Google only honours it when the code IMPERSONATES a
                    # user. `book_appointment` does; this webhook never did, so
                    # every portal booking authenticated as a bare robot, and a
                    # bare robot may not invite attendees.
                    #
                    # The proof is in the calendar itself: Maya-booked events
                    # read `creator: michael@mwmcreations.com` and carry their
                    # attendee. Portal events read `creator: maya-calendar@…
                    # iam.gserviceaccount.com` and carry none. Same account,
                    # same grant, different call.
                    #
                    # This was escalated to Michael for days as "grant DWD —
                    # one admin click". It was never his to fix.
                    _sb_delegate = os.getenv("GOOGLE_DELEGATE_EMAIL")
                    try:
                        _sb_svc = (get_calendar_service(impersonate=_sb_delegate)
                                   if _sb_delegate else get_calendar_service())
                    except Exception as _sb_dwd_err:
                        # Same narrow fallback as book_appointment: only the
                        # delegation-config errors. Anything else must raise.
                        if ("unauthorized_client" in str(_sb_dwd_err)
                                or "invalid_grant" in str(_sb_dwd_err)):
                            print(f"[STUDIO-BOOKING] delegation unavailable "
                                  f"({_sb_dwd_err}) — falling back to direct access")
                            _sb_svc = get_calendar_service()
                        else:
                            raise
                    _sb_body = {
                        "summary": f"🎬 Studio: {name} ({evt.get('duration')}h)",
                        "description": (
                            f"Studio Package portal booking #{bid}\n"
                            f"Client: {name} ({evt.get('client_email','')})\n"
                            f"Notes: {evt.get('notes') or '—'}\n"
                            f"Source: portal (auto-synced by machine S12)"
                        ),
                        "start": {"dateTime": f"{date}T{start}:00", "timeZone": TIMEZONE},
                        "end": {"dateTime": f"{date}T{end}:00", "timeZone": TIMEZONE},
                        "location": STUDIO_ADDRESS,
                    }
                    # ── S-1/S-2/S-2b (Patch #30) · Path C, the PAID portal ──
                    # This write-site was not in the original S-1/S-2 scope and
                    # is the worst of the four: Todd Berger's booking #56 had
                    # NO overrideReminders at all, and the client's email lived
                    # only in the description text, so he was not an attendee
                    # and no calendar mail could reach him even in principle.
                    # NEVER strict here — the client has already paid.
                    _sb_email = (evt.get("client_email") or "").strip()
                    try:
                        _sb_body, _sb_issues = harden_event_body(
                            _sb_body,
                            source_identifier=(evt.get("client_phone") or _sb_email),
                            attendee_email=_sb_email or None,
                            context="studio_booking_webhook",
                            strict=False,
                            reporter=_report_error,
                            default_location=STUDIO_ADDRESS,
                            channel_hint="Portal",
                            require_attendee=True,
                        )
                        if _sb_issues:
                            _post_to_slack_async(SLACK_DEV_CHANNEL, (
                                f"⚠️ *Portal booking #{bid} created with rail issues* — {name}\n"
                                + "\n".join(f"• {i}" for i in _sb_issues)
                            ))
                    except Exception as _sb_rail_err:
                        print(f"[EVENT-RAIL] portal harden failed (non-fatal): {_sb_rail_err}")
                    # ── PATCH #59 ──────────────────────────────────────
                    # This insert used to be a single attempt. On Aug 6 it
                    # threw 403 forbiddenForServiceAccounts for Vanessa
                    # Serrano's booking #59 — the service account may not
                    # invite attendees without Domain-Wide Delegation — and
                    # because it threw, NO EVENT WAS CREATED AT ALL. The
                    # studio read as free for a slot a paying client had
                    # booked. book_appointment already had this ladder; this
                    # path did not.
                    #
                    # The event is what protects the studio from being
                    # double-booked. The invite is a courtesy WordPress has
                    # already delivered by email. If only one can survive,
                    # it is the event.
                    _sb_state = "ok"
                    _sb_degraded = ""
                    try:
                        _sb_created = _sb_svc.events().insert(
                            calendarId=CALENDAR_ID, body=_sb_body, sendUpdates="all"
                        ).execute(num_retries=3)
                    except Exception as _sb_first:
                        if not is_attendee_permission_error(_sb_first):
                            raise
                        _sb_degraded = "no Domain-Wide Delegation on the booking service account"
                        print(f"[STUDIO-BOOKING] #{bid} attendee insert refused — "
                              f"retrying without attendees")
                        _sb_retry = strip_attendees(_sb_body)
                        _sb_retry["description"] = (
                            (_sb_retry.get("description") or "")
                            + "\n\n" + attendee_fallback_note(_sb_email))
                        _sb_created = _sb_svc.events().insert(
                            calendarId=CALENDAR_ID, body=_sb_retry, sendUpdates="none"
                        ).execute(num_retries=3)
                        _sb_state = "degraded"
                        _report_error(
                            "studio_booking.gcal_no_attendee",
                            "Created WITHOUT the client as attendee — service "
                            "account lacks Domain-Wide Delegation. Studio time "
                            "IS blocked; calendar invites are off until DWD is "
                            "granted.", f"booking={bid}")
                    _sbpg.save_state(f"studio_booking_gcal:{bid}", {"event_id": _sb_created.get("id", "")})
                    gcal_note = "calendar ✅" if _sb_state == "ok" else "calendar ✅ (no invite)"
                except Exception as _sb_e:
                    _sb_state = "failed"
                    _sb_degraded = str(_sb_e)[:180]
                    _report_error("studio_booking.gcal_insert", _sb_e, f"booking={bid}")
                # PATCH #59 — the old line said "No action needed" even on
                # the run where the calendar write had just failed. An alert
                # that tells you to ignore a failure is worse than no alert.
                _post_to_slack_async(SLACK_MATT_CHANNEL, booking_sync_alert(
                    name, f"{date} {start}–{end} ({evt.get('duration')}h)",
                    bid, _sb_state, _sb_degraded))
                if _sb_state == "failed":
                    _post_to_slack_async(SLACK_DEV_CHANNEL, (
                        f"🔴 *Portal booking #{bid} is NOT on the calendar* — "
                        f"{name}, {date} {start}–{end}. The slot reads as free "
                        f"and can be double-booked.\n`{_sb_degraded}`"))
            else:
                late = event == "booking_cancelled_late"
                gcal_note = ""
                try:
                    _sb_rec = _sbpg.load_state(f"studio_booking_gcal:{bid}") or {}
                    _sb_gid = _sb_rec.get("event_id") if isinstance(_sb_rec, dict) else _sb_rec
                    if _sb_gid:
                        get_calendar_service().events().delete(calendarId=CALENDAR_ID, eventId=_sb_gid).execute(num_retries=3)
                        gcal_note = "calendar event removed ✅"
                    else:
                        gcal_note = "no calendar event on file (booked pre-S12?)"
                except Exception as _sb_e:
                    _report_error("studio_booking.gcal_delete", _sb_e, f"booking={bid}")
                    gcal_note = "calendar removal ⚠️ failed"
                _post_to_slack_async(SLACK_MATT_CHANNEL, (
                    f"🚫 *STUDIO CANCELLATION* — {name}: {date} {start}–{end} · booking #{bid} · "
                    f"{'<24h — hours FORFEITED per policy' if late else 'hours returned to package'} · "
                    f"{gcal_note} · cancellation email sent by WP."
                ))
            _sbpg.save_state(idem_key, {"processed_at": datetime.now().isoformat()})
        except Exception as _sb_e:
            _report_error("studio_booking_webhook.process", _sb_e, f"event={evt.get('event')} id={evt.get('booking_id')}")

    threading.Thread(target=_sb_process, args=(_sb_evt,), daemon=True).start()
    return jsonify({"received": True}), 200


@app.route('/health', methods=['GET'])
def health_check():
    """Comprehensive health check endpoint with thread + API monitoring."""
    thread_health = _get_thread_health()
    all_threads_ok = all(s.get("healthy", False) for s in thread_health.values())

    # API key presence checks (never expose values)
    api_keys = {
        "OPENAI_API_KEY": bool(os.getenv("OPENAI_API_KEY", "")),
        "SLACK_BOT_TOKEN": bool(os.getenv("SLACK_BOT_TOKEN", "")),
        "META_ACCESS_TOKEN": bool(os.getenv("META_ACCESS_TOKEN", "")),
        "META_PAGE_ACCESS_TOKEN": bool(os.getenv("META_PAGE_ACCESS_TOKEN", "")),
        "INSTAGRAM_PAGE_ID": bool(os.getenv("INSTAGRAM_PAGE_ID", "")),  # IG DM Phase 1
        "INSTAGRAM_ACCESS_TOKEN": bool(os.getenv("INSTAGRAM_ACCESS_TOKEN", "")),  # IG DM token
        "GOOGLE_CREDENTIALS_JSON": bool(os.getenv("GOOGLE_CREDENTIALS_JSON", "") or os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "")),  # S0.1: calendar/gmail/sheets auth
        # GOOGLE_SHEETS_ID deprecated Session 31 — Pipeline Canvas is source of truth
    }
    all_keys_ok = all(api_keys.values())

    overall = "healthy" if (all_threads_ok and all_keys_ok) else "degraded"
    status_code = 200 if overall == "healthy" else 503

    import uuid as _uuid_health
    response = jsonify({
        "status": overall,
        # PATCH #62 — WHICH BUILD IS THIS? Carried open since Jul 30.
        #
        # The standing rule on this board is "no deploy claims without a commit
        # hash plus prod evidence", and until now there has been no way to get
        # the second half. Every "shipped" claim has rested on the watcher
        # saying it pushed, which is a claim about the Mac, not about Railway.
        # Twice a fix was reported as live and was not (#49, the SKILL.md
        # thread count). Railway injects the SHA it built; this simply reports
        # it, so anyone — human or agent — can settle it with one curl.
        "build": {
            "commit": (os.getenv("RAILWAY_GIT_COMMIT_SHA", "")
                       or os.getenv("SOURCE_COMMIT", "") or "unknown")[:12],
            "branch": os.getenv("RAILWAY_GIT_BRANCH", "") or "unknown",
            "deployed_at": os.getenv("RAILWAY_DEPLOYMENT_CREATED_AT", "") or "unknown",
            "booted_at": _PROCESS_START.isoformat(),
            "note": ("compare `commit` against the hash in DEPLOY_RESULT.json — "
                     "if they differ, the patch is committed but NOT running"),
        },
        # PATCH #72 — countable answers instead of a Railway log nobody reads.
        "counters": _TALLY.snapshot(),
        "lead_rows": {
            "verdict": _lead_row_verdict(
                _TALLY.get("sheets.lead_row_created"),
                _TALLY.get("sheets.lead_row_FAILED"),
                _TALLY.get("sheets.lead_row_skipped_duplicate"),
                _TALLY.get("sheets.lead_row_gate_not_new"))[0],
            "why": _lead_row_verdict(
                _TALLY.get("sheets.lead_row_created"),
                _TALLY.get("sheets.lead_row_FAILED"),
                _TALLY.get("sheets.lead_row_skipped_duplicate"),
                _TALLY.get("sheets.lead_row_gate_not_new"))[1],
            "note": ("counters reset on every deploy — read them against "
                     "`thread_registry.uptime_minutes`, not against yesterday"),
        },
        "threads": thread_health,
        # Patch #33: never let a caller compare this count against a baseline
        # without knowing whether every thread has had a chance to register.
        "thread_registry": {
            "count": len(thread_health),
            "uptime_minutes": round((datetime.now(pytz.timezone(TIMEZONE))
                                     - _PROCESS_START).total_seconds() / 60.0, 1),
            "warmup_complete": (datetime.now(pytz.timezone(TIMEZONE)) - _PROCESS_START)
                               > timedelta(minutes=THREAD_REGISTRY_WARMUP_MIN),
            "note": ("count is FINAL — every thread has had time to register"
                     if (datetime.now(pytz.timezone(TIMEZONE)) - _PROCESS_START)
                        > timedelta(minutes=THREAD_REGISTRY_WARMUP_MIN)
                     else f"count is INCOMPLETE — under {THREAD_REGISTRY_WARMUP_MIN}m "
                          f"since boot, threads register only after their first "
                          f"heartbeat. DO NOT compare against a baseline yet."),
        },
        "api_keys_present": api_keys,
        "uptime": str(datetime.now(pytz.timezone(TIMEZONE))),
        "nonce": str(_uuid_health.uuid4()),  # unique per request — proves response is not cached
        "lead_count": len(lead_data),
        "active_conversations": len(conversation_history),
        "ig_dm_conversations": len(ig_conversation_history),
        "ig_dm_enabled": bool(INSTAGRAM_PAGE_ID),
        "pipeline_stats": _get_pipeline_stats(),
        "profile_photo_updated": os.path.exists("/tmp/profile_photo_updated"),
        "calendar_sa_email": _get_calendar_sa_email(),  # S5.2: for ACL grant
    })
    # Prevent Railway/CDN/browser from caching health responses
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    response.headers["Surrogate-Control"] = "no-store"  # Railway CDN edge proxy
    response.headers["Vary"] = "*"  # Force proxy to treat every request as unique
    return response, status_code


# Cached stats from the last canvas sync (reads from Google Sheets).
# This survives Railway deploys because the sync runs every 30 min and
# populates it from the real source of truth (Sheets), not lead_data.
_cached_pipeline_stats = {}


def _get_pipeline_stats():
    """Return pipeline metrics from the last canvas sync (Sheets-backed).
    Falls back to in-memory lead_data if sync hasn't run yet."""
    if _cached_pipeline_stats:
        return _cached_pipeline_stats
    # Fallback: count from in-memory lead_data (may be empty after deploy)
    now = datetime.now(pytz.timezone(TIMEZONE))
    booked = sum(1 for d in lead_data.values() if d.get("booked"))
    cold = sum(1 for d in lead_data.values() if d.get("cold_fired"))
    active = len(lead_data) - booked - cold
    return {
        "total_leads": len(lead_data),
        "active": active,
        "booked": booked,
        "cold": cold,
        "timestamp": now.isoformat(),
        "source": "lead_data (in-memory)",
    }


# ═══════════════════════════════════════════════════════════════════
# WEBHOOK SMOKE TEST — verifies _handle_incoming can process a
# message without crashing. Runs the full code path up to (but NOT
# including) sending a WhatsApp reply. Use after every deploy.
# ═══════════════════════════════════════════════════════════════════

@app.route('/webhook-test', methods=['POST'])
def webhook_smoke_test():
    """
    Smoke-test the webhook pipeline without sending real WhatsApp messages.
    POST with optional JSON: {"sender": "test_000", "message": "test msg"}
    Returns 200 if _handle_incoming runs without crashing, 500 otherwise.
    """
    import traceback as _tb
    data = request.get_json(force=True, silent=True) or {}
    test_sender = data.get("sender", "smoke_test_000")
    test_msg = data.get("message", "Hi, I'm interested in booking a session.")

    try:
        # Run the full incoming handler — process_maya will spawn a thread
        # but send_whatsapp_meta will no-op for invalid phone "smoke_test_000"
        _handle_incoming(
            sender=test_sender,
            incoming_msg=test_msg,
            num_media=0,
            media_id="",
            content_type="",
            wa_value={},
            wa_messages=[],
        )
        # Clean up test data so it doesn't pollute real leads
        conversation_history.pop(test_sender, None)
        lead_data.pop(test_sender, None)
        return jsonify({
            "status": "pass",
            "message": "_handle_incoming executed without crash",
            "timestamp": datetime.now(pytz.timezone(TIMEZONE)).isoformat(),
        }), 200
    except Exception as e:
        return jsonify({
            "status": "fail",
            "error": str(e),
            "traceback": _tb.format_exc(),
            "timestamp": datetime.now(pytz.timezone(TIMEZONE)).isoformat(),
        }), 500


# FORM LEAD ENDPOINT — Inbound Website Forms
# Receives leads from website contact/inquiry forms.
# Form leads always have phone + email = full-track routing.
# Routes to: Maya (WhatsApp) + Susan (email) + Eric (retargeting) + LARA (CRM)
# ══════════════════════════════════════════════════════════════════════

@app.route('/form', methods=['POST'])
def form_webhook():
    """Handle inbound form submissions from the website."""
    try:
        data = request.get_json(force=True) if request.is_json else request.form.to_dict()
    except Exception:
        data = request.form.to_dict()

    name = (data.get("name") or data.get("full_name") or "").strip()
    email = (data.get("email") or "").strip().lower()
    phone_raw = (data.get("phone") or data.get("phone_number") or "").strip()
    message = (data.get("message") or data.get("inquiry") or data.get("notes") or "").strip()
    service = (data.get("service") or data.get("interest") or "").strip()
    business = (data.get("business") or data.get("company") or "").strip()

    # UTM tracking
    utm_source = (data.get("utm_source") or "").strip()
    utm_medium = (data.get("utm_medium") or "").strip()
    utm_campaign = (data.get("utm_campaign") or "").strip()
    utm_content = (data.get("utm_content") or "").strip()

    if not name and not email and not phone_raw:
        return jsonify({"error": "Name, email, or phone required"}), 400

    # Normalize phone
    phone_digits = re.sub(r"\D", "", phone_raw)
    if phone_digits and len(phone_digits) == 10:
        phone_digits = "1" + phone_digits
    sender_key = f"whatsapp:+{phone_digits}" if phone_digits else email or name

    # Check for existing lead (dedup by phone or email)
    existing_key, existing_data = None, None
    if phone_digits:
        existing_key, existing_data = _find_lead_by_phone(phone_digits)
    if not existing_key and email:
        existing_key, existing_data = _find_lead_by_email(email)

    if existing_key:
        # Update existing lead with new info
        if name:
            lead_data[existing_key]["name"] = name
        if email:
            lead_data[existing_key]["email"] = email
        if business:
            lead_data[existing_key]["business"] = business
        if service:
            lead_data[existing_key]["service_interest"] = service
        lead_data[existing_key]["form_submitted"] = True
        lead_data[existing_key]["form_message"] = message
        sender_key = existing_key
        print(f"[Form] Existing lead updated: {name} ({sender_key})")
    else:
        # New lead
        lead_data[sender_key] = {
            "name": name,
            "email": email,
            "phone": phone_raw,
            "business": business,
            "service_interest": service,
            "source": "Website Form",
            "form_submitted": True,
            "form_message": message,
            "first_contact_time": datetime.now(pytz.timezone(TIMEZONE)),
            "last_message_time": datetime.now(pytz.timezone(TIMEZONE)),
        }
        print(f"[Form] New lead registered: {name} ({sender_key})")

    # UTM data
    if utm_source or utm_campaign:
        lead_data[sender_key]["utm_source"] = utm_source
        lead_data[sender_key]["utm_medium"] = utm_medium
        lead_data[sender_key]["utm_campaign"] = utm_campaign
        lead_data[sender_key]["utm_content"] = utm_content

    # Log to Google Sheets
    try:
        log_new_contact_to_sheets(sender_key)
    except Exception as e:
        print(f"[Form] Sheets log error (non-fatal): {e}")

    # Calculate lead score (form leads start higher)
    try:
        _calculate_lead_score(sender_key, message)
    except Exception as _sx:
        _report_error("form_webhook:L11628", _sx)  # S6.5 silent-except sweep

    # Pipeline event
    _post_pipeline_event(
        "NEW_LEAD",
        lead_name=name,
        lead_phone=sender_key,
        source="Website Form",
        new_stage="New",
        assigned_agents=["Maya", "Susan", "Eric", "LARA"],
        context=f"Form submission: {message[:200]}" if message else f"Service interest: {service}",
        extra_fields={
            "Email": email or "N/A",
            "Service": service or "N/A",
            "UTM": f"{utm_source}/{utm_medium}/{utm_campaign}" if utm_source else "Direct",
        },
    )

    # Notify agents via Slack

    # 1. Maya — she'll initiate WhatsApp outreach
    maya_msg = (
        f"*NEW FORM LEAD*\n"
        f"Name: {name}\n"
        f"Phone: {phone_raw}\n"
        f"Email: {email}\n"
        f"Business: {business or 'N/A'}\n"
        f"Service: {service or 'N/A'}\n"
        f"Message: {message[:300] or 'N/A'}\n"
        f"Source: Website Form"
    )
    if utm_campaign:
        maya_msg += f"\nCampaign: {utm_campaign}"
    _post_to_slack_async(SLACK_MAYA_CHANNEL, maya_msg)

    # 2. Susan — email nurture sequence + auto welcome email
    if email:
        # Auto-send welcome email immediately
        _send_welcome_email_async(email, name, source="Website Form")
        # Notify Susan for personalized follow-up
        susan_msg = (
            f"*NEW FORM LEAD — Email Track*\n"
            f"Name: {name}\n"
            f"Email: {email}\n"
            f"Business: {business or 'N/A'}\n"
            f"Interest: {service or 'N/A'}\n"
            f"Message: {message[:300] or 'N/A'}\n"
            f"Welcome email: Sent automatically\n"
            f"⏳ *TIMING RULE: Wait at least 24 HOURS before sending your personalized follow-up.* "
            f"The welcome email was just sent — sending another email immediately looks spammy. "
            f"Save your draft and send it tomorrow.\n"
            f"Action: Send a personalized follow-up based on their form answers (after 24hr wait)"
        )
        _post_to_slack_async(SLACK_SUSAN_CHANNEL, susan_msg)

    # 3. LARA — CRM tracking
    if email:
        lara_msg = (
            f"*NEW FORM LEAD — CRM Entry*\n"
            f"Name: {name}\n"
            f"Email: {email}\n"
            f"Phone: {phone_raw}\n"
            f"Business: {business or 'N/A'}\n"
            f"Source: Website Form\n"
            f"Action: Create CRM record, begin follow-up sequence"
        )
        _post_to_slack_async(SLACK_LARA_CHANNEL, lara_msg)

    # 4. Eric — retargeting audience
    eric_retarget = (
        f"*FORM LEAD — Retargeting*\n"
        f"Name: {name}\n"
        f"Email: {email or 'N/A'}\n"
        f"Interest: {service or 'N/A'}"
    )
    if utm_campaign:
        eric_retarget += f"\nCampaign: {utm_campaign}"
    _post_to_slack_async(SLACK_ERIC_CHANNEL, eric_retarget)

    # 5. Matt — brief notification
    _post_to_slack_async(SLACK_MATT_CHANNEL, f"New form lead: *{name}* ({service or 'General inquiry'}). Full track activated (Maya + Susan + Eric + LARA).")

    # Auto-send WhatsApp greeting if we have a phone number
    if phone_digits and len(phone_digits) >= 10:
        first_name = name.split()[0] if name else "there"
        wa_target = f"whatsapp:+{phone_digits}"
        greeting = (
            f"Hi {first_name}! Thanks for reaching out to MWM Creations & Studios. "
            f"I'm Maya, and I'd love to help you with your {service or 'project'}. "
        )
        if message:
            greeting += "I saw your message and I'll make sure to address everything. "
        greeting += "What's the best time for a quick chat about your vision?"

        try:
            _greet_result = send_whatsapp_meta(wa_target, body=greeting)  # S2.4
            if not _greet_result:
                _post_to_slack_async(SLACK_MATT_CHANNEL, f"\u26a0\ufe0f *Lead not reached on WhatsApp:* {name} ({wa_target}) — first-touch greeting failed (no open session; Meta blocks business-initiated free-form). Manual first touch needed until an approved template exists.")
                _report_error("Lead first-touch WhatsApp (S2.4)", Exception("send returned None"), f"lead={name}")
            # Add to conversation history
            if wa_target not in conversation_history:
                conversation_history[wa_target] = []
            conversation_history[wa_target].append({"role": "assistant", "content": greeting})
            print(f"[Form] Auto-greeting sent to {wa_target}")
        except Exception as e:
            print(f"[Form] WhatsApp greeting error (non-fatal): {e}")

    return jsonify({
        "success": True,
        "lead_id": sender_key,
        "message": "Lead received and routed to all agents"
    })




# ══════════════════════════════════════════════════════════════════════
# META LEAD ADS WEBHOOK — Eric's Facebook/Instagram Ad Campaigns
# When someone fills out a Lead Ad form on Facebook or Instagram,
# Meta sends a webhook notification here. We fetch the full lead data
# from the Graph API and route it through the Sales Machine pipeline.
#
# Setup in Meta Business Suite:
#   1. Go to Business Settings → Integrations → Leads Access
#   2. Set webhook URL to: https://<railway-domain>/meta-leads
#   3. Subscribe to "leadgen" field on your Page
#   4. The same WEBHOOK_VERIFY_TOKEN is used for verification
# ══════════════════════════════════════════════════════════════════════

@app.route("/meta-leads", methods=["GET", "POST"])
def meta_leads_webhook():
    """Handle Meta Lead Ads webhooks from Eric's FB/IG campaigns."""

    # ── GET: Meta webhook verification ──
    if request.method == "GET":
        mode = request.args.get("hub.mode")
        token = request.args.get("hub.verify_token")
        challenge = request.args.get("hub.challenge")
        if mode == "subscribe" and token == WEBHOOK_VERIFY_TOKEN:
            print("[Meta Leads] Webhook verified by Meta")
            return challenge, 200
        return "Forbidden", 403

    # ── POST: Incoming lead from Meta Lead Ad ──
    data = request.get_json(force=True, silent=True) or {}

    # Meta Lead Ads send object="page" with field="leadgen"
    if data.get("object") not in ("page", "instagram"):
        return "OK", 200

    for entry in data.get("entry", []):
        for change in entry.get("changes", []):
            if change.get("field") != "leadgen":
                continue

            leadgen_value = change.get("value", {})
            leadgen_id = leadgen_value.get("leadgen_id")
            form_id = leadgen_value.get("form_id", "")
            page_id = leadgen_value.get("page_id", "")
            ad_id = leadgen_value.get("ad_id", "")
            adgroup_id = leadgen_value.get("adgroup_id", "")
            created_time = leadgen_value.get("created_time", "")

            if not leadgen_id:
                print("[Meta Leads] No leadgen_id in webhook — skipping")
                continue

            print(f"[Meta Leads] New lead ad submission: leadgen_id={leadgen_id}, form_id={form_id}, ad_id={ad_id}")

            # Fetch full lead data from Meta Graph API
            try:
                lead_url = f"https://graph.facebook.com/v19.0/{leadgen_id}"
                lead_resp = http_requests.get(
                    lead_url,
                    params={"access_token": META_PAGE_ACCESS_TOKEN},
                    timeout=15,
                )
                lead_resp.raise_for_status()
                lead_data_meta = lead_resp.json()
            except Exception as e:
                print(f"[Meta Leads] Error fetching lead data: {e}")
                _post_to_slack_async(SLACK_DEV_CHANNEL,
                    f"Meta Lead Ad error: could not fetch lead `{leadgen_id}`: {e}")
                continue

            # Parse the field_data array into a dict
            # Meta returns: {"field_data": [{"name": "email", "values": ["user@example.com"]}, ...]}
            field_data = lead_data_meta.get("field_data", [])
            fields = {}
            for field in field_data:
                fname = field.get("name", "").lower().replace(" ", "_")
                fvalues = field.get("values", [])
                fields[fname] = fvalues[0] if fvalues else ""

            # Extract standard fields (Meta form fields can have varying names)
            name = fields.get("full_name") or fields.get("name") or fields.get("first_name", "")
            if not name and fields.get("first_name"):
                name = fields.get("first_name", "")
                if fields.get("last_name"):
                    name += " " + fields["last_name"]
            email = fields.get("email", "").strip().lower()
            phone_raw = fields.get("phone_number") or fields.get("phone") or fields.get("cell_phone", "")
            company = fields.get("company_name") or fields.get("company") or fields.get("business", "")
            # Custom fields Eric might add to the form
            service_interest = fields.get("service") or fields.get("interest") or fields.get("what_service_are_you_interested_in", "")
            city = fields.get("city", "")
            state = fields.get("state", "")

            print(f"[Meta Leads] Parsed: name={name}, email={email}, phone={phone_raw}, biz={company}")

            # Normalize phone
            phone_digits = re.sub(r"\D", "", phone_raw)
            if phone_digits and len(phone_digits) == 10:
                phone_digits = "1" + phone_digits
            sender_key = f"whatsapp:+{phone_digits}" if phone_digits else email or name or f"meta_lead_{leadgen_id}"

            # Dedup check
            existing_key, existing_data = None, None
            if phone_digits:
                existing_key, existing_data = _find_lead_by_phone(phone_digits)
            if not existing_key and email:
                existing_key, existing_data = _find_lead_by_email(email)

            if existing_key:
                # Update existing lead
                if name:
                    lead_data[existing_key]["name"] = name
                if email:
                    lead_data[existing_key]["email"] = email
                if company:
                    lead_data[existing_key]["business"] = company
                lead_data[existing_key]["meta_lead_ad"] = True
                lead_data[existing_key]["ad_id"] = ad_id
                lead_data[existing_key]["form_id"] = form_id
                sender_key = existing_key
                print(f"[Meta Leads] Existing lead updated: {name} ({sender_key})")
            else:
                # New lead
                lead_data[sender_key] = {
                    "name": name,
                    "email": email,
                    "phone": phone_raw,
                    "business": company,
                    "service_interest": service_interest,
                    "source": "Meta Lead Ad",
                    "meta_lead_ad": True,
                    "leadgen_id": leadgen_id,
                    "ad_id": ad_id,
                    "form_id": form_id,
                    "adgroup_id": adgroup_id,
                    "city": city,
                    "state": state,
                    "first_contact_time": datetime.now(pytz.timezone(TIMEZONE)),
                    "last_message_time": datetime.now(pytz.timezone(TIMEZONE)),
                }
                print(f"[Meta Leads] New lead registered: {name} ({sender_key})")

            # Log to Google Sheets
            try:
                log_new_contact_to_sheets(sender_key)
            except Exception as e:
                print(f"[Meta Leads] Sheets log error (non-fatal): {e}")

            # Calculate lead score
            try:
                _calculate_lead_score(sender_key, service_interest or company)
            except Exception as _sx:
                _report_error("meta_leads_webhook:L11895", _sx)  # S6.5 silent-except sweep

            # Pipeline event
            _post_pipeline_event(
                "NEW_LEAD",
                lead_name=name,
                lead_phone=sender_key,
                source="Meta Lead Ad",
                new_stage="New",
                assigned_agents=["Maya", "Susan", "Eric", "LARA"] if email else ["Maya", "Eric"],
                context=f"Lead Ad form submission. Interest: {service_interest or 'General'}. Business: {company or 'N/A'}",
                extra_fields={
                    "Email": email or "N/A",
                    "Business": company or "N/A",
                    "Ad ID": ad_id or "N/A",
                    "City": city or "N/A",
                },
            )

            # ── Notify agents via Slack ──

            # Maya — she'll initiate WhatsApp outreach
            _lead_loc = f"{city}, {state}" if city else ""
            maya_msg = (
                f"*NEW LEAD — Meta Lead Ad*\n"
                f"Name: {name}\n"
                f"Phone: {phone_raw}\n"
                f"Email: {email or 'N/A'}\n"
                f"Business: {company or 'N/A'}\n"
                f"Interest: {service_interest or 'N/A'}\n"
            )
            if _lead_loc:
                maya_msg += f"Location: {_lead_loc}\n"
            maya_msg += f"Source: Facebook/Instagram Lead Ad"
            _post_to_slack_async(SLACK_MAYA_CHANNEL, maya_msg)

            # Susan — email nurture (if email provided) + auto welcome email
            if email:
                # Auto-send welcome email immediately
                _send_welcome_email_async(email, name, source="Meta Lead Ad")
                # Notify Susan for personalized follow-up
                _post_to_slack_async(SLACK_SUSAN_CHANNEL,
                    f"*NEW LEAD — Meta Ad Email Track*\n"
                    f"Name: {name}\n"
                    f"Email: {email}\n"
                    f"Business: {company or 'N/A'}\n"
                    f"Interest: {service_interest or 'N/A'}\n"
                    f"Welcome email: Sent automatically\n"
                    f"⏳ *TIMING RULE: Wait at least 24 HOURS before sending your personalized follow-up.* "
                    f"The welcome email was just sent — sending another email immediately looks spammy. "
                    f"Save your draft and send it tomorrow.\n"
                    f"Action: Send a personalized follow-up based on their form answers (after 24hr wait)"
                )

            # LARA — CRM (if email provided)
            if email:
                _post_to_slack_async(SLACK_LARA_CHANNEL,
                    f"*NEW LEAD — Meta Ad CRM Entry*\n"
                    f"Name: {name}\n"
                    f"Email: {email}\n"
                    f"Phone: {phone_raw}\n"
                    f"Business: {company or 'N/A'}\n"
                    f"Source: Meta Lead Ad\n"
                    f"Action: Create CRM record"
                )

            # Eric — ad performance tracking (always)
            _post_to_slack_async(SLACK_ERIC_CHANNEL,
                f"*LEAD CAPTURED — Meta Ad*\n"
                f"Name: {name}\n"
                f"Ad ID: {ad_id or 'N/A'}\n"
                f"Form ID: {form_id or 'N/A'}\n"
                f"Interest: {service_interest or 'N/A'}\n"
                f"Location: {_lead_loc or 'N/A'}\n"
                f"Lead entered pipeline. Track conversion in /api/conversions"
            )

            # Matt — brief notification
            _post_to_slack_async(SLACK_MATT_CHANNEL,
                f"New Meta Lead Ad: *{name}* ({service_interest or company or 'General inquiry'}). "
                f"Full track activated." if email else
                f"New Meta Lead Ad: *{name}* ({service_interest or company or 'General inquiry'}). "
                f"Maya + Eric track (no email)."
            )

            # Auto-send WhatsApp greeting if we have a phone number
            if phone_digits and len(phone_digits) >= 10:
                first_name = name.split()[0] if name else "there"
                wa_target = f"whatsapp:+{phone_digits}"
                greeting = (
                    f"Hi {first_name}! Thanks for your interest in MWM Creations & Studios! "
                    f"I'm Maya, and I'd love to learn more about what you're looking for. "
                )
                if service_interest:
                    greeting += f"I see you're interested in {service_interest} — great choice! "
                greeting += "What's the best time for a quick chat about your vision?"

                try:
                    _greet_result = send_whatsapp_meta(wa_target, body=greeting)  # S2.4
                    if not _greet_result:
                        _post_to_slack_async(SLACK_MATT_CHANNEL, f"\u26a0\ufe0f *Lead not reached on WhatsApp:* {name} ({wa_target}) — first-touch greeting failed (no open session; Meta blocks business-initiated free-form). Manual first touch needed until an approved template exists.")
                        _report_error("Lead first-touch WhatsApp (S2.4)", Exception("send returned None"), f"lead={name}")
                    if wa_target not in conversation_history:
                        conversation_history[wa_target] = []
                    conversation_history[wa_target].append({"role": "assistant", "content": greeting})
                    print(f"[Meta Leads] Auto-greeting sent to {wa_target}")
                except Exception as e:
                    print(f"[Meta Leads] WhatsApp greeting error (non-fatal): {e}")

    return "OK", 200


