@app.route('/book', methods=['GET'])
def booking_form_page():
    """PATCH #50A — serve the direct-booking form."""
    if not MEETING_REPORT_PIN:
        return ("<h2>Direct Booking not configured.</h2>"
                "<p>Set MEETING_REPORT_PIN on Railway.</p>"), 503
    return BOOKING_FORM_HTML, 200, {'Content-Type': 'text/html'}


@app.route('/book/verify', methods=['POST'])
def booking_form_verify():
    """Same PIN and the same day-token as the report form. One person, one PIN."""
    data = request.get_json(silent=True) or {}
    token = data.get('token')
    if token and _mr_verify_token(token):
        return jsonify({"ok": True, "token": token})
    if MEETING_REPORT_PIN and hmac.compare_digest(data.get('pin', ''), MEETING_REPORT_PIN):
        return jsonify({"ok": True, "token": _mr_make_token()})
    return jsonify({"ok": False}), 401


@app.route('/book/types', methods=['GET'])
def booking_form_types():
    """The taxonomy, served from event_rail so the form cannot drift from it.

    The alternative — hard-coding the four types in JavaScript — would put a
    second copy of the vocabulary in a file no test imports. It would agree
    with event_rail on the day it shipped and quietly stop agreeing later.
    """
    if not _mr_verify_token(request.headers.get('X-MR-Token', '')):
        return jsonify({"ok": False, "error": "auth"}), 401

    _types = {}
    for _k in BOOKING_TYPE_ORDER:
        _s = BOOKING_TYPES[_k]
        _plan = CONFIRMATION_PLAN.get(_s["kind"]) or []
        _client_h = sorted({h for who, h in _plan if who == "client"}, reverse=True)
        _crew_h = sorted({h for who, h in _plan if who == "crew"}, reverse=True)
        _lead_time = lambda h: (f"{int(h // 24)}d" if h >= 168 else f"{int(h)}h")
        _bits = []
        if _client_h:
            _bits.append("client " + " · ".join(_lead_time(h) for h in _client_h))
        if _crew_h:
            _bits.append("crew " + " · ".join(_lead_time(h) for h in _crew_h))
        _types[_k] = {
            "label": _s["label"], "hint": _s["hint"],
            "title": _s["title"], "default_minutes": _s["default_minutes"],
            "needs_address": booking_needs_address(_k),
            "billing_options": billing_options_for(_k),
            "billing_asked": billing_is_asked(_k),
            "default_location": booking_location(_k, "", STUDIO_ADDRESS,
                                                 STRATEGY_CALL_LOCATION),
            "ladder": "; ".join(_bits) or "no reminders",
        }
    return jsonify({
        "ok": True,
        "types": _types, "type_order": list(BOOKING_TYPE_ORDER),
        "relationships": {k: {"label": v["label"], "hint": v["hint"],
                              "sells": v["sells"]}
                          for k, v in RELATIONSHIPS.items()},
        "relationship_order": list(RELATIONSHIP_ORDER),
        "billing": {k: {"label": v} for k, v in BILLING.items()},
        "billing_order": list(BILLING_ORDER),
        # One number, defined in event_rail, governing both the browser hint
        # and anything server-side that ever needs it. A 30 hard-coded in the
        # JavaScript would drift the first time Michael changes his mind.
        "buffer_min": BOOKING_BUFFER_MIN,
    }), 200


@app.route('/book/availability', methods=['GET'])
def booking_form_availability():
    """PATCH #50D — what is already on the calendar, for the form's day strip.

    Michael asked for this and gave the reason: he is on the phone, the client
    asks for Thursday afternoon, and until now answering meant leaving the form
    and opening Google Calendar — the habit this whole patch exists to replace.
    A booking form that cannot answer "is that free?" sends him straight back to
    the tool that was losing the instrumentation.

    Deliberately NOT /studio-availability. That route is the WordPress portal's
    public-facing feed: it is authed by WP_PORTAL_SECRET, and it returns opaque
    busy blocks with no titles because a member of the public must not learn
    who is in our studio. Michael needs the opposite — he needs to see that the
    09:00 block is Bolfer's shoot so he can tell the client what is actually
    happening. Same calendar query, different audience, different auth.

    Titles only. No attendee address is ever serialised here.
    """
    if not _mr_verify_token(request.headers.get('X-MR-Token', '')):
        return jsonify({"ok": False, "error": "auth"}), 401

    _tz = pytz.timezone(TIMEZONE)
    _from = (request.args.get("from") or "").strip()
    try:
        _d0 = _tz.localize(datetime.strptime(_from, "%Y-%m-%d"))
    except Exception:
        _now = datetime.now(_tz)
        _d0 = _tz.localize(datetime(_now.year, _now.month, _now.day))
    try:
        _days = int(request.args.get("days", "21"))
    except Exception:
        _days = 21
    _days = max(1, min(60, _days))

    _ck = ("bookform", _d0.strftime("%Y-%m-%d"), _days)
    _hit = _SA_CACHE.get(_ck)
    if _hit and (time.time() - _hit[0]) < _SA_CACHE_TTL:
        return jsonify(_hit[1])

    try:
        _svc = get_calendar_service()
        _items = _svc.events().list(
            calendarId=CALENDAR_ID,
            timeMin=_d0.isoformat(),
            timeMax=(_d0 + timedelta(days=_days)).isoformat(),
            singleEvents=True, orderBy="startTime", maxResults=2500,
        ).execute(num_retries=3).get("items", [])
    except Exception as _ax:
        _report_error("booking_form.availability", _ax, f"from={_from}")
        return jsonify({"ok": False, "error": "calendar unavailable"}), 502

    _by_date = {}
    for _i in range(_days):
        _ds = _d0 + timedelta(days=_i)
        _de = _ds + timedelta(days=1)
        _blocks = []
        for _ev in _items:
            if _ev.get("transparency") == "transparent":
                continue                       # marked Free — not a real block
            _st, _en = _ev.get("start", {}), _ev.get("end", {})
            try:
                if "dateTime" in _st and "dateTime" in _en:
                    _bs = datetime.fromisoformat(_st["dateTime"]).astimezone(_tz)
                    _be = datetime.fromisoformat(_en["dateTime"]).astimezone(_tz)
                    _allday = False
                elif "date" in _st and "date" in _en:
                    _bs = _tz.localize(datetime.strptime(_st["date"], "%Y-%m-%d"))
                    _be = _tz.localize(datetime.strptime(_en["date"], "%Y-%m-%d"))
                    _allday = True
                else:
                    continue
            except Exception:
                continue
            if _be <= _ds or _bs >= _de:
                continue
            _cs, _ce = max(_bs, _ds), min(_be, _de)
            # S15.1 — a block reaching next midnight must serialise as "24:00";
            # "00:00" made multi-day events collapse to zero length and vanish.
            _blocks.append({
                "start": _cs.strftime("%H:%M"),
                "end": "24:00" if _ce >= _de else _ce.strftime("%H:%M"),
                "title": (_ev.get("summary") or "(untitled)")[:60],
                "all_day": _allday,
                "mine": classify_event(_ev)[0] == KIND_INTERNAL,
            })
        _blocks.sort(key=lambda b: b["start"])
        _by_date[_ds.strftime("%Y-%m-%d")] = _blocks

    _payload = {"ok": True, "timezone": TIMEZONE,
                "from": _d0.strftime("%Y-%m-%d"), "days": _days,
                "by_date": _by_date}
    _SA_CACHE[_ck] = (time.time(), _payload)
    if len(_SA_CACHE) > 200:
        _SA_CACHE.clear()
    return jsonify(_payload), 200


@app.route('/book/submit', methods=['POST'])
def booking_form_submit():
    """PATCH #50A — turn form answers into a fully instrumented calendar event.

    Order matters here:
      1. validate PURELY (event_rail.validate_booking) — no I/O until the
         answers are known good, so a bad submission never half-creates.
      2. compute title / location / description from the vocabulary.
      3. hand the body to harden_event_body(), the SAME S-1 gate the Maya
         command path uses. This form does not get its own weaker rail.
      4. only then write.

    sendUpdates="none" matches every other insert in this file: Google's own
    invite mail is not our confirmation rail, and firing both would double up
    on the client.
    """
    _data = request.get_json(silent=True) or {}
    if not _mr_verify_token(_data.get('token', '')):
        return jsonify({"ok": False, "error": "auth"}), 401

    _errs, _c = validate_booking(_data)
    if _errs:
        return jsonify({"ok": False, "message": "Nothing was created — fix these:",
                        "errors": _errs}), 400

    _tz = pytz.timezone(TIMEZONE)
    try:
        _start = _tz.localize(datetime.strptime(
            f"{_c['date']} {_c['start']}", "%Y-%m-%d %H:%M"))
    except Exception:
        return jsonify({"ok": False, "message": "That date and time did not parse.",
                        "errors": ["check the date and start time"]}), 400
    _end = _start + timedelta(minutes=int(_c["minutes"]))

    _title = booking_title(_c["type"], _c["name"])
    if not _title:
        return jsonify({"ok": False, "message": "Could not build a title.",
                        "errors": ["pick a booking type and give a name"]}), 400
    _loc = booking_location(_c["type"], _c["location"],
                            STUDIO_ADDRESS, STRATEGY_CALL_LOCATION)
    _desc = booking_description(
        _c["name"], _c["email"], phone=_c["phone"], business=_c["business"],
        type_key=_c["type"], relationship=_c["relationship"],
        billing=_c["billing"], amount=_c["amount"], notes=_c["notes"])

    _kind = booking_kind(_c["type"])
    # S87: the commercial record goes where the CLIENT CANNOT READ IT. The
    # description is copy they receive by email; this is bookkeeping.
    _priv = booking_private_props(
        phone=_c["phone"], business=_c["business"], type_key=_c["type"],
        relationship=_c["relationship"], billing=_c["billing"],
        amount=_c["amount"], booked_by="Direct Booking form")
    _body = {
        "summary": _title,
        "description": _desc,
        "location": _loc,
        "extendedProperties": {"private": _priv},
        "start": {"dateTime": _start.isoformat(), "timeZone": TIMEZONE},
        "end": {"dateTime": _end.isoformat(), "timeZone": TIMEZONE},
    }

    # The identifier decides the source channel, so prefer the dialable number
    # — a lead we can WhatsApp is reachable on the rail that works best.
    _ident = _c["phone"] or _c["email"]
    try:
        _body, _issues = harden_event_body(
            _body,
            source_identifier=_ident,
            attendee_email=_c["email"],
            context="booking_form.create",
            strict=False,
            reporter=_report_error,
            require_attendee=True,
            require_postal=(venue_of(_kind) != VENUE_VIRTUAL),
            stated_reminder_channel=_c["reminder"],   # S85: ask, do not infer
        )
    except Exception as _hx:
        return jsonify({"ok": False, "message": "The Event Rail refused this booking.",
                        "errors": [str(_hx)[:300]]}), 400

    # ── PATCH #80 — the third instance of the SAME defect ───────────────
    # "Service accounts cannot invite attendees without Domain-Wide
    # Delegation of Authority." DWD has been granted to this service
    # account the whole time; Google only honours it when the code
    # IMPERSONATES a user. `book_appointment` does. The studio-booking
    # webhook did not until #69. THIS form — #50A — was never touched by
    # #69, and it is the one Michael actually types into.
    #
    # It also failed in the worst possible way: `require_attendee=True`
    # guarantees an attendee is on the body, so the insert was guaranteed
    # to 403, and the handler returned "nothing created". Michael got a
    # red box and an empty calendar.
    #
    # #69's ruling applies here verbatim: the event is what protects the
    # studio from being double-booked; the invite is a courtesy. If only
    # one can survive, it is the event.
    _bf_delegate = os.getenv("GOOGLE_DELEGATE_EMAIL")
    try:
        _svc = (get_calendar_service(impersonate=_bf_delegate)
                if _bf_delegate else get_calendar_service())
    except Exception as _bf_dwd_err:
        # Only the delegation-config errors fall back. Anything else must raise.
        if ("unauthorized_client" in str(_bf_dwd_err)
                or "invalid_grant" in str(_bf_dwd_err)):
            print(f"[BOOK-FORM] delegation unavailable ({_bf_dwd_err}) — "
                  f"falling back to the bare service account")
            _svc = get_calendar_service()
        else:
            raise

    _bf_degraded = ""
    try:
        try:
            _created = _svc.events().insert(
                calendarId=CALENDAR_ID, body=_body, sendUpdates="none"
            ).execute(num_retries=3)
        except Exception as _bf_first:
            if not is_attendee_permission_error(_bf_first):
                raise
            _bf_degraded = "no Domain-Wide Delegation on the booking service account"
            print("[BOOK-FORM] attendee insert refused — retrying without attendees "
                  "so the slot is still blocked")
            _bf_retry = strip_attendees(_body)
            _bf_retry["description"] = ((_bf_retry.get("description") or "")
                                        + "\n\n" + attendee_fallback_note(_c["email"]))
            _created = _svc.events().insert(
                calendarId=CALENDAR_ID, body=_bf_retry, sendUpdates="none"
            ).execute(num_retries=3)
            _report_error(
                "booking_form.gcal_no_attendee",
                "Booking form created the event WITHOUT the client as attendee — "
                "the service account could not invite. The studio time IS blocked; "
                "the client has NOT been invited and no RSVP can be read.",
                f"title={_title}")
    except Exception as _cx:
        _report_error("booking_form.insert", _cx, f"title={_title}")
        return jsonify({"ok": False, "message": "Calendar write failed — nothing created.",
                        "errors": [str(_cx)[:300]]}), 502
    try:
        _SA_CACHE.clear()
    except Exception:
        pass

    _eid = _created.get("id", "")
    _link = _created.get("htmlLink", "")

    # ── put them on the record, but only where that is honest ──
    # A referral belongs in the pipeline. An existing client is already there,
    # and a partner or a vendor is not a prospect and must not be turned into
    # one by a side effect of booking a room.
    _lead_note = ""
    try:
        _lk, _lr = _find_lead_by_email(_c["email"])
        if _lr:
            _lr["booked"] = True
            _lr["booked_at"] = datetime.now(_tz).isoformat()   # #49A
            _lr["event_id"] = _eid
            for _f, _v in (("name", _c["name"]), ("business", _c["business"]),
                           ("phone", re.sub(r"\D", "", _c["phone"] or ""))):
                if _v and not str(_lr.get(_f) or "").strip():
                    _lr[_f] = _v
            # PATCH #52 — record WHAT they are, so a later reader does not have
            # to infer it from the calendar event. Never downgrades: someone
            # already marked a client is not turned back into a prospect
            # because this booking happened to be filed as a new lead.
            _lr["relationship"] = _c["relationship"]
            if relationship_converted(_c["relationship"]):
                _lr["status"] = "client"
            _lead_note = "existing lead record updated"
        elif relationship_in_pipeline(_c["relationship"]):
            # PATCH #52 — was `== "new_lead"`, which meant an existing client
            # not yet in the store, or a lead who paid on the call, got NO
            # record at all. The condition is now "does this person belong in
            # the pipeline", which is what it always meant.
            _key = re.sub(r"\D", "", _c["phone"] or "") or _c["email"].strip().lower()
            _conv = relationship_converted(_c["relationship"])
            lead_data[_key] = {
                "name": _c["name"], "email": _c["email"],
                "phone": re.sub(r"\D", "", _c["phone"] or ""),
                "business": _c["business"],
                "source": "Direct — booked by Michael",
                # A converted person must not read as an open prospect on the
                # board. Deliberately NOT writing `outcome: "Won"` or
                # `product` — those drive revenue reporting, which Rob owns
                # from Stripe, and a booking is not a payment. Michael records
                # the package and the money on the Daily Event Report.
                "status": "client" if _conv else "booked",
                "relationship": _c["relationship"],
                "booked": True,
                "booked_at": datetime.now(_tz).isoformat(),
                "event_id": _eid,
                "first_contact_time": datetime.now(_tz),
                "last_message_time": datetime.now(_tz),
            }
            _lead_note = ("new client record created (not a prospect — never pitched)"
                          if _conv else "new lead record created")
        else:
            _lead_note = (f"no lead record — {RELATIONSHIPS[_c['relationship']]['label'].lower()}"
                          f", deliberately not added to the sales pipeline")
    except Exception as _lx:
        _report_error("booking_form.lead_write", _lx, f"email={_c['email'][:40]}")
        _lead_note = "lead record not written (reported)"

    _plan = CONFIRMATION_PLAN.get(_kind) or []
    _when = _start.strftime("%A, %B %d at %I:%M %p")
    _conf = (f"{len(_plan)} confirmation(s) scheduled automatically"
             if _plan else "no confirmation ladder for this type")

    try:
        _post_to_slack_async(SLACK_PIPELINE_CHANNEL, (
            f"\U0001f4c5 *DIRECT BOOKING — {BOOKING_TYPES[_c['type']]['label']}*\n"
            f"*Client:* {_c['name']}" + (f" ({_c['business']})" if _c['business'] else "") + "\n"
            f"*When:* {_when}\n*Where:* {_loc}\n"
            f"*Relationship:* {RELATIONSHIPS[_c['relationship']]['label']}"
            f"{'' if relationship_sells(_c['relationship']) else '  — sales rail OFF'}\n"
            f"*Billing:* {BILLING[_c['billing']]}"
            + (f" — {_c['amount']}" if _c['billing'] == 'paid' and _c['amount'] else "") + "\n"
            f"*Confirmations:* {_conf}\n"
            f"_Booked by Michael via /book — {_lead_note}._"
        ))
    except Exception:
        pass
    if _issues:
        try:
            _post_to_slack_async(SLACK_DEV_CHANNEL, (
                f":warning: *Direct booking created WITH rail issues* — `{_title}`\n"
                + "\n".join(f"• {i}" for i in _issues)
                + "\n_The event exists. These are gaps a human should close._"))
        except Exception:
            pass

    # #80: if the invite was dropped, SAY SO on the success screen. A booking
    # that silently lost its attendee reads as fully wired and is not — that
    # is how Marcia and Vanessa sat for weeks as "no-attendee" events.
    if _bf_degraded:
        _issues = list(_issues or []) + [
            "Client was NOT invited — " + _bf_degraded + ". The studio time is "
            "blocked and the event exists, but there is no invite and no RSVP "
            "to read. Send the client a note yourself."]
    return jsonify({
        "ok": True, "event_id": _eid, "link": _link,
        "title": _title, "when": _when, "location": _loc,
        "confirmations": _conf, "lead": _lead_note,
        "attendee_dropped": bool(_bf_degraded),
        "issues": _issues,
    }), 200


@app.route('/meeting-report', methods=['GET'])
def meeting_report_page():
    """Serve the meeting report form."""
    if not MEETING_REPORT_PIN:
        return "<h2>Meeting Report not configured.</h2><p>Set MEETING_REPORT_PIN environment variable on Railway.</p>", 503
    return MEETING_REPORT_HTML, 200, {'Content-Type': 'text/html'}


@app.route('/meeting-report/verify', methods=['POST'])
def meeting_report_verify():
    """Verify PIN or existing token."""
    data = request.get_json(silent=True) or {}
    # Check existing token
    token = data.get('token')
    if token and _mr_verify_token(token):
        return jsonify({"ok": True, "token": token})
    # Check PIN
    pin = data.get('pin', '')
    if hmac.compare_digest(pin, MEETING_REPORT_PIN):
        return jsonify({"ok": True, "token": _mr_make_token()})
    return jsonify({"ok": False}), 401


@app.route('/meeting-report/meetings', methods=['GET'])
def meeting_report_meetings():
    """Fetch today's or this week's calendar events for the meeting picker."""
    token = request.headers.get('X-MR-Token', '')
    if not _mr_verify_token(token):
        return jsonify({"ok": False, "error": "auth"}), 401

    range_param = request.args.get('range', 'today')
    et = pytz.timezone("US/Eastern")
    now = datetime.now(et)

    try:
        cal = get_calendar_service(impersonate=MICHAEL_EMAIL)
    except Exception:
        try:
            cal = get_calendar_service()
        except Exception as e:
            print(f"[MEETING REPORT] Calendar auth error: {e}")
            return jsonify({"ok": False, "message": "Calendar not available"})

    meetings = []
    mwm_cal = CALENDAR_ID  # MWM production calendar
    personal_cal = MICHAEL_EMAIL  # Personal calendar

    if range_param == 'week':
        # Get rest of this week (today through Sunday)
        days_until_sunday = 6 - now.weekday()
        dates = [now.date() + timedelta(days=d) for d in range(0, days_until_sunday + 1)]
    elif range_param == 'yesterday':
        dates = [now.date() - timedelta(days=1)]
    else:
        dates = [now.date()]

    day_names = {0: "Mon", 1: "Tue", 2: "Wed", 3: "Thu", 4: "Fri", 5: "Sat", 6: "Sun"}

    for d in dates:
        start_str = d.isoformat() + "T00:00:00-04:00"
        end_str = d.isoformat() + "T23:59:59-04:00"

        for cal_id in [mwm_cal, personal_cal]:
            try:
                result = cal.events().list(
                    calendarId=cal_id,
                    timeMin=start_str,
                    timeMax=end_str,
                    singleEvents=True,
                    orderBy="startTime",
                    timeZone="America/New_York",
                ).execute(num_retries=3)
                events = result.get("items", [])
            except Exception:
                events = []

            for ev in events:
                summary = ev.get("summary", "")
                if not summary:
                    continue
                # Skip all-day events and internal calendar items
                start_info = ev.get("start", {})
                if "dateTime" not in start_info:
                    continue
                # Skip events that look internal (no attendees, recurring meetings, etc.)
                # Focus on events that have a person's name or "studio visit", "meeting", "consultation"
                try:
                    dt = datetime.fromisoformat(start_info["dateTime"].replace("Z", "+00:00"))
                    time_str = dt.astimezone(et).strftime("%-I:%M %p")
                except Exception:
                    time_str = start_info["dateTime"][11:16]

                # Extract name/business from the event title (Jul 8 2026 matcher fix:
                # "Studio Visit — Dr. Scott Robinson (...)" must yield the PERSON, not "Studio Visit")
                name, business = parse_event_summary(summary)

                date_label = ""
                if range_param == 'yesterday':
                    date_label = f"Yesterday — {day_names.get(d.weekday(), '')} {d.strftime('%-m/%-d')}"
                elif range_param == 'week' and d != now.date():
                    date_label = f"{day_names.get(d.weekday(), '')} {d.strftime('%-m/%-d')}"

                meetings.append({
                    "name": name,
                    "business": business,
                    "time": time_str,
                    "date_label": date_label,
                    "event_id": ev.get("id", ""),
                })

    # Deduplicate by event_id
    seen = set()
    unique = []
    for m in meetings:
        eid = m["event_id"]
        if eid not in seen:
            seen.add(eid)
            unique.append(m)

    return jsonify({"ok": True, "meetings": unique})


OUTCOME_LABELS = {
    "client_won": {"emoji": "\U0001F389", "label": "CLIENT WON", "pipeline": "CLIENT_WON"},
    "follow_up": {"emoji": "\U0001F504", "label": "FOLLOW-UP NEEDED", "pipeline": "FOLLOW_UP"},
    "studio_package_pitched": {"emoji": "\U0001F4E6", "label": "STUDIO PACKAGE PITCHED", "pipeline": "PACKAGE_PITCHED"},
    "completed": {"emoji": "✅", "label": "COMPLETED", "pipeline": "VISIT_COMPLETE"},
    "not_interested": {"emoji": "❌", "label": "NOT INTERESTED", "pipeline": "CLIENT_LOST"},
    "no_show": {"emoji": "\U0001F6AB", "label": "NO-SHOW", "pipeline": "NO_SHOW"},
}


@app.route('/meeting-report/submit', methods=['POST'])
def meeting_report_submit():
    """Process a meeting report submission."""
    data = request.get_json(silent=True) or {}

    # Auth check
    if not _mr_verify_token(data.get('token', '')):
        return jsonify({"ok": False, "error": "auth"}), 401

    test_mode = data.get('test_mode', False)
    test_log = []

    name = data.get('name', '').strip()
    business = data.get('business', '').strip()
    outcome = data.get('outcome', '')
    notes = data.get('notes', '').strip()
    service = data.get('service', '').strip()
    next_steps = data.get('next_steps', '').strip()
    event_id = data.get('event_id', '')

    if not name or outcome not in OUTCOME_LABELS:
        return jsonify({"ok": False, "message": "Missing required fields."}), 400

    oc = OUTCOME_LABELS[outcome]

    # ── PATCH #39 · what should the machine do about this outcome? ──────
    # Resolve the lead FIRST so the plan is built from what we actually know
    # about reaching them, not from what we would prefer. Michael does not
    # have to tell us the channel — the machine already knows it from the
    # identifier, and it knows it more reliably than he does.
    # PATCH #40 — resolve from the CALENDAR EVENT first, not from the name.
    # Michael clicks a meeting button; the form fills the name from the event
    # title. A title is a display string — it drifts, it carries the business
    # in brackets, and one nested bracket made the exact-name lookup miss
    # entirely (Krista Neeley, Aug 3). The event's ATTENDEE EMAIL is a real
    # key: stable, unique, and already on the invite. Use it.
    _p39_key = _p39_rec = None
    _evt_email = ""
    if event_id:
        try:
            _p40_svc = get_calendar_service()
            _p40_ev = _p40_svc.events().get(calendarId=CALENDAR_ID,
                                            eventId=event_id).execute(num_retries=2)
            for _a in (_p40_ev.get("attendees") or []):
                _ae = str((_a or {}).get("email") or "").strip()
                _ael = _ae.lower()
                if (_ae and "@" in _ae
                        and not _ael.endswith(("mwmcreations.com", "mwmscreens.com"))
                        and "group.calendar.google.com" not in _ael):
                    _evt_email = _ae
                    break
        except Exception as _p40x:
            _report_error("p40.event_lookup", _p40x, f"event={event_id}")

    if _evt_email:
        _p39_key, _p39_rec = _find_lead_by_email(_evt_email)
    if not _p39_key:
        _p39_key, _p39_rec = _find_lead_by_name(name)
    if not _p39_key:
        for _e in extract_emails(notes):
            _p39_key, _p39_rec = _find_lead_by_email(_e)
            if _p39_key:
                break
    _p39_rec = _p39_rec or {}
    # The invite address is a deliverable email even when NO lead record
    # matched — so an unmatched lead is still reachable instead of silently
    # unautomatable.
    _p39_email = (_p39_rec.get("email") or "").strip() or _evt_email
    if not _p39_email:
        _p39_any = extract_emails(notes)
        _p39_email = sorted(_p39_any)[0] if _p39_any else ""
    _p39_channel = resolve_channel(_p39_key or "", _p39_rec.get("source") or "")
    _p39_hours = None
    try:
        _lm = _p39_rec.get("last_message_time")
        if _lm:
            _lm = _lm if isinstance(_lm, datetime) else datetime.fromisoformat(str(_lm))
            if _lm.tzinfo is None:
                _lm = pytz.timezone(TIMEZONE).localize(_lm)
            _p39_hours = (datetime.now(pytz.timezone(TIMEZONE)) - _lm).total_seconds() / 3600
    except Exception:
        _p39_hours = None
    _plan = outcome_plan(outcome, _p39_channel, bool(_p39_email), _p39_hours)

    et = pytz.timezone("US/Eastern")
    now = datetime.now(et)
    date_str = now.strftime("%A, %B %d, %Y at %I:%M %p ET")

    # Build #pipeline message
    pipeline_msg = f"{oc['emoji']} *EVENT REPORT — {oc['label']}*\n\n"
    pipeline_msg += f"*Lead:* {name}\n"
    if business:
        pipeline_msg += f"*Business:* {business}\n"
    pipeline_msg += f"*Outcome:* {oc['label']}\n"
    pipeline_msg += f"*Date:* {date_str}\n"
    if notes:
        pipeline_msg += f"\n*Meeting Notes:*\n{notes}\n"
    if service:
        pipeline_msg += f"\n*Service & Price:* {service}\n"
    if next_steps:
        pipeline_msg += f"\n*Next Steps:* {next_steps}\n"
    pipeline_msg += "\n_Submitted by Michael via Daily Event Report_"

    # Post to #pipeline
    if not test_mode:
        post_to_slack(SLACK_PIPELINE_CHANNEL, pipeline_msg)
    else:
        test_log.append({"action": "Post to #pipeline", "channel": "SLACK_PIPELINE_CHANNEL", "message_preview": pipeline_msg[:200]})

    # ── S24: EDITING-PIPELINE AUTO-ROUTE ──
    # When a completed event report mentions editing/delivery in its next steps
    # or notes, route it to #lara so the editing tracker picks it up without
    # anyone re-reading #pipeline. LARA's Mon/Wed/Fri scan stays as backstop.
    try:
        _edit_text = f"{next_steps} {notes}".lower()
        _edit_hits = [k for k in ("edit", "editar", "edicao", "edição", "deliver") if k in _edit_text]
        # PATCH #39 — Michael, Aug 3: "all our shoots require editing."
        # The old gate ALSO required a keyword in the notes, so writing
        # "went great" silently routed nothing. A keyword match pretending
        # to be a rule. `completed` now routes UNCONDITIONALLY; client_won
        # keeps the keyword test because a signed client is not always a shoot.
        _route_edit = (outcome == "completed") or (bool(_edit_hits) and outcome == "client_won")
        if _route_edit:
            _lara_msg = (
                f"🎞️ *EDITING PIPELINE — new item from event report*\n"
                f"*Project:* {name}" + (f" ({business})" if business else "") + "\n"
                f"*Outcome:* {oc['label']} · {date_str}\n"
                + (f"*Next steps:* {next_steps}\n" if next_steps else "")
                + (f"*Notes:* {notes[:300]}\n" if notes else "")
                + ("_Auto-routed (every completed shoot goes to editing — Patch #39). "
                   if outcome == "completed"
                   else "_Auto-routed (matched: " + ", ".join(_edit_hits) + "). ")
                + "LARA: add to EDITING_PIPELINE.json (status AWAITING_EDIT) so the dashboard stays current._"
            )
            if not test_mode:
                post_to_slack(SLACK_LARA_CHANNEL, _lara_msg)
            else:
                test_log.append({"action": "Post to #lara (editing auto-route)", "channel": "SLACK_LARA_CHANNEL", "message_preview": _lara_msg[:200]})
    except Exception as _lara_e:
        print(f"[record-outcome] lara auto-route error (non-fatal): {_lara_e}")

    # Build #matt summary
    matt_msg = ""
    if outcome == "client_won":
        matt_msg = f"{oc['emoji']} *New client signed!* {name}"
        if business:
            matt_msg += f" ({business})"
        matt_msg += "\n"
        if service:
            matt_msg += f"*Package:* {service}\n"
        if next_steps:
            matt_msg += f"*Next:* {next_steps}\n"
        matt_msg += "\n_LARA — please set up production tracking for this new client._"
    elif outcome == "follow_up":
        matt_msg = f"{oc['emoji']} *Follow-up needed:* {name}"
        if business:
            matt_msg += f" ({business})"
        matt_msg += "\n"
        if notes:
            matt_msg += f"*Notes:* {notes}\n"
        if next_steps:
            matt_msg += f"*Next:* {next_steps}\n"
        matt_msg += "\n_Maya — please continue nurturing this lead via WhatsApp._"
    elif outcome == "studio_package_pitched":
        matt_msg = f"{oc['emoji']} *Studio Package pitched:* {name}"
        if business:
            matt_msg += f" ({business})"
        matt_msg += "\n"
        if notes:
            matt_msg += f"*Notes:* {notes}\n"
        matt_msg += ("\n_Arming email follow-up sequence (T+1h recap · T+2d value · T+6d nudge) via "
                     "Susan's Gmail — confirmation follows. Maya picks up any WhatsApp replies._")
    elif outcome == "not_interested":
        matt_msg = f"{oc['emoji']} *Lead lost:* {name}"
        # PATCH #39 — "not interested" is the ONE outcome that must never
        # trigger outreach. But it IS automated: the automation is STOPPING.
        # Previously it set a status and the lead could still resurface in
        # Susan's digest and the re-engagement queue.
        if not test_mode and _p39_email:
            try:
                import pg_store as _ni
                if _ni.enabled():
                    _ni.save_state("email_suppressed:" + _p39_email.lower(), {
                        "at": datetime.now(pytz.timezone(TIMEZONE)).isoformat(),
                        "reason": "not_interested (event report)",
                        "by": "meeting_report", "lead": name,
                    })
                    print(f"[P39] suppressed {_p39_email} — not_interested")
            except Exception as _nx:
                _report_error("p39.suppress", _nx, f"lead={name}")
        if _p39_rec:
            _p39_rec["do_not_contact"] = True
            _p39_rec["cold_fired"] = True
        if business:
            matt_msg += f" ({business})"
        matt_msg += "\n"
        if notes:
            matt_msg += f"*Reason:* {notes}\n"
    elif outcome == "completed":
        matt_msg = f"{oc['emoji']} *Event completed:* {name}"
        if business:
            matt_msg += f" ({business})"
        matt_msg += "\n"
        if notes:
            matt_msg += f"*Notes:* {notes}\n"
        matt_msg += "\n_No further action needed._"
    elif outcome == "no_show":
        matt_msg = f"{oc['emoji']} *No-show:* {name}"
        if business:
            matt_msg += f" ({business})"
        matt_msg += " didn't show up for their meeting.\n"
        matt_msg += "\n_Maya — please reach out to reschedule._"

    # ── PATCH #39 · say what was armed and when it ENDS ────────────────
    # Ezechiel Garcon took four emails across six weeks because no sequence
    # knew how to stop. Every plan now carries a close condition, and every
    # report states it, so nobody has to remember.
    try:
        _pl = []
        _pl.append(f"\n\n*Channel on file:* {_p39_channel}"
                   + (f" · email `{_p39_email}`" if _p39_email else " · *no email on file*"))
        if _plan.get("suppress"):
            _pl.append("\n🔇 *SUPPRESSED* — added to do-not-contact. No sequence, "
                       "no digest, no re-engagement. Nothing further is sent.")
        elif _plan.get("internal_only"):
            _pl.append(f"\n⚙️ *Internal automation only* — {_plan['why']}")
        elif _plan.get("steps"):
            if plan_is_deliverable(_plan):
                # PATCH #46B — was `via {ch}`, which printed the raw channel
                # constant: "via Website Chat" for what is an email. Michael
                # reads this line to know what the machine will do; it has to
                # name the thing that actually happens.
                _steps = " · ".join(
                    (f"T+{int(h)}h" if h < 48 else f"T+{int(h)//24}d")
                    + f" {k} by {delivery_label(ch)}"
                    for h, ch, k in _plan["steps"])
                _pl.append(f"\n🤖 *Armed:* {_steps}")
                if _plan.get("close_after_days"):
                    _pl.append(f"\n⏹️ *Closes after {_plan['close_after_days']} days* "
                               f"with no reply — then off the digest, no re-engagement.")
                _pl.append(f"\n_{_plan['why']}_")
            else:
                # S-4: never report a sequence as armed when no step can land.
                _pl.append(f"\n🔴 *CANNOT REACH THIS LEAD AUTOMATICALLY* — channel is "
                           f"{_p39_channel}, no email on file"
                           + (", and the Instagram 24h window is CLOSED"
                              if _p39_channel == CH_INSTAGRAM_LABEL else "")
                           + f".\n*{_plan.get('owner') or 'MICHAEL'}: this one needs a human.* "
                           f"Nothing was armed — reporting it instead of pretending.")
        if _plan.get("editing"):
            _pl.append("\n🎞️ Routed to the editing pipeline.")
        matt_msg += "".join(_pl)
    except Exception as _px:
        _report_error("p39.plan_summary", _px, f"lead={name}")

    if not test_mode:
        post_to_slack(SLACK_MATT_CHANNEL, matt_msg)
    else:
        test_log.append({"action": "Post to #matt", "channel": "SLACK_MATT_CHANNEL", "message_preview": matt_msg[:200]})

    # PATCH #39 — persist the armed plan on the lead record so the sender
    # (Patch #40) has a durable, inspectable worklist. Stored, not sent:
    # nothing in #39 messages a client.
    try:
        if _p39_rec and _plan.get("steps") and plan_is_deliverable(_plan):
            _p39_rec["outcome_seq"] = {
                "outcome": outcome,
                "armed_at": datetime.now(pytz.timezone(TIMEZONE)).isoformat(),
                "channel": _p39_channel,
                "email": _p39_email,
                "steps": [[h, ch, k] for h, ch, k in _plan["steps"]],
                "next_step": 0,
                "close_after_days": _plan.get("close_after_days"),
                "owner": _plan.get("owner"),
                # PATCH #46A — carry what Michael actually agreed with the
                # client. Without it the T+48h nudge asks "still thinking it
                # over?" of someone who has already committed to a dated next
                # step, which reads as though we forgot the meeting. Trimmed
                # because it goes into a client-facing message.
                "agreed_next": str(next_steps or "").strip()[:300],
                "done": False,
            }
    except Exception as _sx:
        _report_error("p39.arm", _sx, f"lead={name}")

    # Update Google Sheets — find the lead row and update status
    if not test_mode:
        try:
            _update_lead_sheet_status(name, outcome, notes, service, next_steps)
        except Exception as e:
            print(f"[MEETING REPORT] Sheets update error (non-blocking): {e}")
    else:
        test_log.append({"action": "Update Google Sheets CRM", "to": name, "message_preview": f"outcome={outcome}, notes={notes[:80] if notes else 'none'}"})

    # ── S7: Studio Package pitched -> arm the email-first follow-up sequence ──
    if outcome == "studio_package_pitched":
        # PATCH #41 — use the lead ALREADY RESOLVED above (#40: calendar
        # attendee email -> name -> notes) instead of re-deriving it here.
        #
        # This block had its own private lookup: exact name match, or an email
        # that happened to appear in the free-text NOTES. #40 taught the rest
        # of the handler to resolve from the invite, but this block never
        # learned — so on Krista Neeley (title carries a nested bracket, notes
        # empty) it would have found nothing and posted "sequence NOT armed"
        # while every other part of the same report resolved her correctly.
        # Two lookups for one lead is how one of them silently rots.
        _sp_found = None
        if _p39_key and _p39_rec:
            _sp_found = _p39_key
            if not test_mode:
                _studio.start_pitch_sequence(_p39_key, _p39_rec)
                post_to_slack(SLACK_MATT_CHANNEL,
                    f"\U0001F4E6 ✅ Follow-up sequence ARMED for *{name}* "
                    f"(lead record: {_p39_key} · {_p39_email or 'no email'}) — "
                    f"T+1h recap · T+2d value · T+6d nudge, closes day 10.")
            else:
                test_log.append({"action": "Arm studio pitch sequence", "lead": _p39_key})
        if not _sp_found and not test_mode:
            post_to_slack(SLACK_MATT_CHANNEL,
                f"\U0001F4E6 Studio Package pitched to *{name}* but NO LEAD RECORD MATCHED — "
                f"follow-up sequence NOT armed.\n"
                f"_Tried, in order: calendar attendee email"
                + (f" (`{_evt_email}`)" if _evt_email else " (event had no external attendee)")
                + f", exact name `{name}`, then any email in the notes._\n"
                f"*Fix:* add their email to the CRM record and re-report, or Susan follows up "
                f"manually. The pitch itself is logged either way.")

    # ── Post-Visit Follow-Up (WhatsApp template OR IG DM) ──
    # Check lead source: if they came from Instagram, send reschedule via IG DM.
    # Otherwise, send WhatsApp template (works outside 24h window).
    template_sent = False
    ig_dm_sent = False
    _lead_source = "N/A"
    if outcome != "not_interested":
        # Determine lead source: check lead_data for instagram: key matching this name
        _lead_source = "WhatsApp"  # default
        _lead_igsid = None
        clean_lead_name = (name or "").strip().lower()
        for _ld_key, _ld_val in lead_data.items():
            if _ld_key.startswith("instagram:") and _ld_val.get("name", "").strip().lower() == clean_lead_name:
                _lead_source = "Instagram"
                _lead_igsid = _ld_key.replace("instagram:", "")
                break

        if _lead_source == "Instagram" and _lead_igsid:
            # ── CASCADE: IG DM → WhatsApp template → Susan email ──
            # Instagram leads: try IG DM first. If 24h window is closed (403),
            # fall back to WhatsApp template (if we have their phone). If neither
            # works, Susan's no-show email (sent separately) is the safety net.
            first_name = (name or "there").split()[0]
            if outcome == "no_show":
                ig_msg = (
                    f"Hi {first_name}! We missed you today — no worries at all, things happen! "
                    f"Would you like to reschedule? We'd love to find a time that works better for you. 😊"
                )
            elif outcome == "client_won":
                ig_msg = (
                    f"Thank you so much, {first_name}! We're thrilled to work with you. "
                    f"Our team will be in touch shortly with next steps! 🎉"
                )
            elif outcome == "follow_up":
                ig_msg = (
                    f"Great meeting you, {first_name}! Thanks for taking the time. "
                    f"I'll follow up with more details soon. Feel free to reach out if you have any questions! 😊"
                )
            else:
                ig_msg = None

            if ig_msg:
                # Step 1: Check if we already know the IG window is closed
                if _lead_igsid in _ig_403_blocked:
                    print(f"[MEETING REPORT] IG window closed for {first_name} (IGSID in 403 blocklist) — skipping to WhatsApp fallback")
                else:
                    # Step 2: Try IG DM
                    if not test_mode:
                        try:
                            _ig_result = send_instagram_dm(_lead_igsid, body=ig_msg)
                            if _ig_result:
                                ig_dm_sent = True
                                print(f"[MEETING REPORT] IG DM follow-up sent to {first_name} (IGSID: {_lead_igsid[:6]}...)")
                        except Exception as e:
                            print(f"[MEETING REPORT] IG DM send error: {e}")
                    else:
                        # Simulate: check if window is blocked
                        _ig_result = None if _lead_igsid in _ig_403_blocked else "TEST_SIMULATED"
                        if _ig_result:
                            ig_dm_sent = True
                        test_log.append({"action": "IG DM" + (" (BLOCKED - 403)" if not _ig_result else ""), "to": f"IGSID:{_lead_igsid[:8]}...", "message_preview": ig_msg[:100]})

                # Step 3: If IG DM failed, fall back to WhatsApp template
                if not ig_dm_sent:
                    print(f"[MEETING REPORT] IG DM unavailable for {first_name} — trying WhatsApp fallback")
                    try:
                        lead_phone = _lookup_lead_phone(name)
                        if lead_phone:
                            if not test_mode:
                                template_sent = _send_post_visit_template(lead_phone, name, outcome, notes)
                            else:
                                template_sent = True  # Simulate success
                                test_log.append({"action": "WhatsApp Template (IG fallback)", "to": lead_phone[:8] + "...", "message_preview": f"template={POST_VISIT_TEMPLATES.get(outcome, 'N/A')}"})
                            if template_sent:
                                print(f"[MEETING REPORT] WhatsApp fallback succeeded for IG lead {first_name}")
                        else:
                            print(f"[MEETING REPORT] No phone found for IG lead '{name}' — Susan email is the fallback")
                    except Exception as e:
                        print(f"[MEETING REPORT] WhatsApp fallback error (non-blocking): {e}")

                    # Step 4: If WhatsApp also failed, make sure Susan knows she's the only channel
                    if not template_sent:
                        _susan_urgent_msg = (
                            f"⚠️ *URGENT — ONLY CONTACT CHANNEL*\n"
                            f"*{name}*" + (f" ({business})" if business else "") + f" is an Instagram lead.\n"
                            f"IG DM window is closed and no WhatsApp available.\n"
                            f"*Email is the only way to reach them.* Please prioritize this follow-up."
                        )
                        if not test_mode:
                            _post_to_slack_async(SLACK_SUSAN_CHANNEL, _susan_urgent_msg)
                        else:
                            test_log.append({"action": "Slack DM to Susan (URGENT - only channel)", "to": "SLACK_SUSAN_CHANNEL", "message_preview": _susan_urgent_msg[:200]})
        else:
            # WhatsApp template path (default for non-IG leads)
            try:
                lead_phone = _lookup_lead_phone(name)
                if lead_phone:
                    if not test_mode:
                        template_sent = _send_post_visit_template(lead_phone, name, outcome, notes)
                    else:
                        template_sent = True  # Simulate success
                        test_log.append({"action": "WhatsApp Template", "to": lead_phone[:8] + "...", "message_preview": f"template={POST_VISIT_TEMPLATES.get(outcome, 'N/A')}"})
                else:
                    print(f"[MEETING REPORT] No phone found for '{name}' — template not sent")
            except Exception as e:
                print(f"[MEETING REPORT] Template send error (non-blocking): {e}")

    # Build actions list for success screen
    actions = [
        "✅ Posted event result to #pipeline",
        "✅ Notified Matt in #matt",
    ]
    _is_ig_lead = (_lead_source == "Instagram")
    if outcome == "client_won":
        actions.append("✅ LARA will set up production tracking")
        actions.append("✅ Rob will set up invoicing")
        if ig_dm_sent:
            actions.append("✅ Maya sent welcome message via Instagram DM")
        elif template_sent and _is_ig_lead:
            actions.append("✅ IG window closed — Maya sent welcome via WhatsApp instead")
        elif template_sent:
            actions.append("✅ Maya sent welcome message via WhatsApp")
        elif _is_ig_lead:
            actions.append("⚠️ IG window closed, no WhatsApp available — Susan will email")
    elif outcome == "follow_up":
        actions.append("✅ Maya will continue nurture")
        if ig_dm_sent:
            actions.append("✅ Maya sent follow-up message via Instagram DM")
        elif template_sent and _is_ig_lead:
            actions.append("✅ IG window closed — Maya sent follow-up via WhatsApp instead")
        elif template_sent:
            actions.append("✅ Maya sent follow-up message via WhatsApp")
        elif _is_ig_lead:
            actions.append("⚠️ IG window closed, no WhatsApp available — Susan will email")
        if service:
            actions.append("✅ Susan can send follow-up email with portfolio")
    elif outcome == "completed":
        actions.append("✅ Event marked as completed — no follow-up needed")
    elif outcome == "no_show":
        actions.append("✅ Maya will reach out to reschedule")
        if ig_dm_sent:
            actions.append("✅ Maya sent reschedule message via Instagram DM")
        elif template_sent and _is_ig_lead:
            actions.append("✅ IG window closed — Maya sent reschedule via WhatsApp instead")
        elif template_sent:
            actions.append("✅ Maya sent reschedule message via WhatsApp")
        elif _is_ig_lead:
            actions.append("⚠️ IG window closed, no WhatsApp available — Susan email is only channel")
        # Notify Susan to send a no-show follow-up email
        _susan_noshow_msg = (
            f"📧 *NO-SHOW EMAIL NEEDED*\n"
            f"*{name}*" + (f" ({business})" if business else "") + " was a no-show.\n"
            f"Please send a friendly no-show follow-up email — express understanding, suggest rescheduling.\n"
        )
        if notes:
            _susan_noshow_msg += f"*Notes from Michael:* {notes}\n"
        if not test_mode:
            _post_to_slack_async(SLACK_SUSAN_CHANNEL, _susan_noshow_msg)
        else:
            test_log.append({"action": "Slack DM to Susan (no-show email)", "to": "SLACK_SUSAN_CHANNEL", "message_preview": _susan_noshow_msg[:200]})
        actions.append("✅ Susan notified to send no-show email")

    actions.append("✅ CRM updated in Google Sheets")

    # Track this event as reported so Golden Hour / No-Show detectors stop reminding
    if event_id:
        if not test_mode:
            _mr_reported_events[event_id] = outcome
            _golden_hour_processed.add(event_id)
            _noshow_processed.add(event_id)
        else:
            test_log.append({"action": "Track event as reported", "to": f"event_id={event_id}", "message_preview": f"Would mark as {outcome} in _mr_reported_events, _golden_hour_processed, _noshow_processed"})

    print(f"[MEETING REPORT{'—TEST' if test_mode else ''}] {oc['label']}: {name} ({business or 'no business'}) — submitted by Michael")

    if test_mode:
        # Determine cascade info for test report
        _test_cascade = "N/A"
        if outcome != "not_interested":
            if ig_dm_sent:
                _test_cascade = "IG DM sent"
            elif template_sent:
                _test_cascade = "WhatsApp fallback" if (_lead_source == "Instagram") else "WhatsApp template sent"
            else:
                _test_cascade = "Email only (Susan)" if (_lead_source == "Instagram") else "No follow-up sent"
        return jsonify({
            "ok": True,
            "test_mode": True,
            "actions": actions,
            "test_log": test_log,
            "source_detected": _lead_source,
            "cascade_result": _test_cascade,
        })

    return jsonify({"ok": True, "actions": actions})


def _update_lead_sheet_status(name, outcome, notes="", service="", next_steps=""):
    """Find the lead by name in Google Sheets and update their status + notes.

    PATCH #62 — the last three arguments are OPTIONAL, and that is the fix.

    This function grew from two parameters to five. One caller was updated,
    one was wrapped in a lambda that pads the missing three, and one —
    `/admin/register-client`, shipped in #55A — was not. It failed twice on
    Aug 5 (13:56 and 14:06) with:

        _update_lead_sheet_status() missing 3 required positional arguments:
        'notes', 'service', 'next_steps'                    name=Gema Hiatt

    The client record was created and the Leads-sheet write was lost, both
    times. The repair path repaired the record and left the sheet behind it —
    a paid client whose row still reads as an unconverted lead.

    Defaults rather than a fixed call site, deliberately: a call site can be
    fixed and the next one written wrong. Three fields that are optional in
    the sheet should have been optional in the signature.
    """
    sheet_id = os.getenv("GOOGLE_SHEETS_ID", "")
    if not sheet_id:
        return

    try:
        creds_json = os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "") or os.getenv("GOOGLE_CREDENTIALS_JSON", "")  # S0.1
        if not creds_json:
            return
        creds = service_account.Credentials.from_service_account_info(
            json.loads(creds_json),
            scopes=["https://www.googleapis.com/auth/spreadsheets"]
        )
        svc = build("sheets", "v4", credentials=creds)
    except Exception as e:
        print(f"[MEETING REPORT] Sheets auth error: {e}")
        return

    # Map outcome to CRM status
    status_map = {
        "client_won": "Client Won",
        "follow_up": "Follow-up Needed",
        "completed": "Completed",
        "not_interested": "Not Interested",
        "no_show": "No-Show — Reschedule",
        "studio_package_pitched": "Studio Package — Pitched",
    }
    new_status = status_map.get(outcome, outcome)

    # Get current month's tab name
    now = datetime.now(pytz.timezone("US/Eastern"))
    month_tab = now.strftime("%b %Y")  # e.g. "Jun 2026"

    try:
        result = svc.spreadsheets().values().get(
            spreadsheetId=sheet_id,
            range=f"'{month_tab}'!A:T"
        ).execute(num_retries=3)
        rows = result.get("values", [])
    except Exception:
        # Try without quotes
        try:
            result = svc.spreadsheets().values().get(
                spreadsheetId=sheet_id,
                range=f"{month_tab}!A:T"
            ).execute(num_retries=3)
            rows = result.get("values", [])
        except Exception as e:
            print(f"[MEETING REPORT] Could not read tab '{month_tab}': {e}")
            return

    if not rows:
        return

    # Find the lead by name (col C = index 2) OR by email from notes (col F = index 5) — Jul 8 2026 fix
    _mr_emails = extract_emails(notes)
    def _mr_row_match(row):
        if len(row) > 2 and row[2].strip().lower() == name.strip().lower():
            return True
        return bool(_mr_emails and len(row) > 5 and row[5].strip().lower() in _mr_emails)
    target_row = None
    for i, row in enumerate(rows):
        if _mr_row_match(row):
            target_row = i + 1  # 1-indexed for Sheets API
            break

    if not target_row:
        # Try all tabs
        for tab_name in ["Jun 2026", "May 2026", "Apr 2026", "Mar 2026"]:
            if tab_name == month_tab:
                continue
            try:
                result = svc.spreadsheets().values().get(
                    spreadsheetId=sheet_id,
                    range=f"'{tab_name}'!A:T"
                ).execute(num_retries=3)
                rows = result.get("values", [])
                for i, row in enumerate(rows):
                    if _mr_row_match(row):
                        target_row = i + 1
                        month_tab = tab_name
                        break
                if target_row:
                    break
            except Exception:
                continue

    if not target_row:
        print(f"[MEETING REPORT] Lead '{name}' not found in any sheet tab")
        return

    # Update Status (col H = index 7), Notes (col J = index 9)
    # Build the notes update
    meeting_note = f"[Meeting {now.strftime('%m/%d')}] {new_status}"
    if notes:
        meeting_note += f" — {notes}"
    if service:
        meeting_note += f" | Package: {service}"
    if next_steps:
        meeting_note += f" | Next: {next_steps}"

    try:
        # Update Status column (H)
        svc.spreadsheets().values().update(
            spreadsheetId=sheet_id,
            range=f"'{month_tab}'!H{target_row}",
            valueInputOption="RAW",
            body={"values": [[new_status]]}
        ).execute(num_retries=3)

        # Append to Notes column (J)
        existing_notes = ""
        if target_row <= len(rows) and len(rows[target_row - 1]) > 9:
            existing_notes = rows[target_row - 1][9]
        updated_notes = f"{existing_notes}\n{meeting_note}".strip() if existing_notes else meeting_note

        svc.spreadsheets().values().update(
            spreadsheetId=sheet_id,
            range=f"'{month_tab}'!J{target_row}",
            valueInputOption="RAW",
            body={"values": [[updated_notes]]}
        ).execute(num_retries=3)

        print(f"[MEETING REPORT] Updated '{name}' in '{month_tab}' row {target_row}: status={new_status}")
    except Exception as e:
        print(f"[MEETING REPORT] Sheets update error for '{name}': {e}")


# ══════════════════════════════════════════════════════════════════════
# POST-VISIT WHATSAPP TEMPLATES — Session 31
# Sends Meta-approved template messages after Michael submits a
# Meeting Report. Works OUTSIDE the 24-hour WhatsApp session window.
# ══════════════════════════════════════════════════════════════════════

POST_VISIT_TEMPLATES = {
    "follow_up":       "maya_post_visit_followup_v2",
    "no_show":         "maya_post_visit_noshow",
    "client_won":      "maya_post_visit_welcome",
    "not_interested":  None,  # No outreach for lost leads
    "studio_package_pitched": None,  # S7: email sequence owns post-pitch touches
}

POST_VISIT_WABA_ID = META_WABA_ID


def _lookup_lead_phone(name):
    """Look up a lead's phone number from Google Sheets by name.
    Returns the phone number string or None if not found.
    """
    sheet_id = os.getenv("GOOGLE_SHEETS_ID", "")
    if not sheet_id:
        return None

    try:
        creds_json = os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON", "") or os.getenv("GOOGLE_CREDENTIALS_JSON", "")  # S0.1
        if not creds_json:
            return None
        creds = service_account.Credentials.from_service_account_info(
            json.loads(creds_json),
            scopes=["https://www.googleapis.com/auth/spreadsheets.readonly"]
        )
        svc = build("sheets", "v4", credentials=creds)
    except Exception as e:
        print(f"[POST-VISIT] Sheets auth error for phone lookup: {e}")
        return None

    # Search current month tab first, then recent months
    et = pytz.timezone("US/Eastern")
    now = datetime.now(et)
    current_tab = now.strftime("%b %Y")
    tabs_to_search = [current_tab]
    for months_back in range(1, 4):
        prev = now - timedelta(days=30 * months_back)
        tab_name = prev.strftime("%b %Y")
        if tab_name not in tabs_to_search:
            tabs_to_search.append(tab_name)

    clean_name = name.strip().lower()

    for tab_name in tabs_to_search:
        try:
            result = svc.spreadsheets().values().get(
                spreadsheetId=sheet_id,
                range=f"'{tab_name}'!A:T"
            ).execute(num_retries=3)
            rows = result.get("values", [])
        except Exception:
            continue

        for row in rows:
            # Name is column C (index 2), Phone is column E (index 4)
            if len(row) > 4 and row[2].strip().lower() == clean_name:
                phone = row[4].strip()
                if phone and re.sub(r"\D", "", phone):
                    print(f"[POST-VISIT] Found phone for '{name}' in '{tab_name}': {phone[:6]}...")
                    return phone

    print(f"[POST-VISIT] Phone not found for '{name}' in any tab")
    return None


def _send_post_visit_template(phone, name, outcome, notes=""):
    """Send a post-visit WhatsApp template message based on meeting outcome.
    Uses Meta Cloud API templates — works outside the 24h session window.
    Returns True if sent, False otherwise.
    """
    template_name = POST_VISIT_TEMPLATES.get(outcome)
    if not template_name:
        print(f"[POST-VISIT] No template for outcome '{outcome}' — skipping")
        return False

    if not phone:
        print(f"[POST-VISIT] No phone number — cannot send template")
        return False

    meta_token = META_ACCESS_TOKEN
    phone_number_id = META_PHONE_NUMBER_ID

    if not meta_token or not phone_number_id:
        print("[POST-VISIT] Missing META_ACCESS_TOKEN or META_PHONE_NUMBER_ID")
        return False

    clean_phone = re.sub(r"\D", "", phone.replace("whatsapp:", ""))
    first_name = (name or "there").split()[0]

    url = f"https://graph.facebook.com/v20.0/{phone_number_id}/messages"
    headers = {
        "Authorization": f"Bearer {meta_token}",
        "Content-Type": "application/json",
    }

    # All post-visit templates use a body with {{1}} = first name
    payload = {
        "messaging_product": "whatsapp",
        "to": clean_phone,
        "type": "template",
        "template": {
            "name": template_name,
            "language": {"code": "en_US"},
            "components": [
                {
                    "type": "body",
                    "parameters": [{"type": "text", "text": first_name}],
                }
            ],
        },
    }

    try:
        resp = http_requests.post(url, json=payload, headers=headers, timeout=30)
        resp.raise_for_status()
        result = resp.json()
        msg_id = result.get("messages", [{}])[0].get("id", "")
        print(f"✅ [POST-VISIT] Template '{template_name}' sent to {clean_phone[:6]}... (msg_id={msg_id})")

        # Notify in #pipeline for visibility
        _post_to_slack_async(
            SLACK_PIPELINE_CHANNEL,
            f"\U0001f4ac *POST-VISIT TEMPLATE SENT*\n"
            f"*Lead:* {name}\n"
            f"*Template:* `{template_name}`\n"
            f"*Via:* Maya WhatsApp (outside 24h window)\n"
            f"_Triggered by Michael's Meeting Report_"
        )
        return True
    except Exception as e:
        err_detail = str(e)
        if hasattr(e, "response") and e.response is not None:
            err_detail = e.response.text
        print(f"❌ [POST-VISIT] Template send failed: {err_detail}")

        # If template not approved yet, log but don't alert
        if "not exist" in err_detail.lower() or "not found" in err_detail.lower() or "470" in err_detail:
            print(f"[POST-VISIT] Template '{template_name}' may not be approved yet — skipping silently")
        else:
            _notify_error_to_dev(
                "Post-Visit Template Failed",
                f"Could not send '{template_name}' to {clean_phone[:6]}...: {err_detail}",
                lead_info=f"Name: {name}, Outcome: {outcome}",
                severity="WARNING"
            )
        return False


# PATCH #48A — the ONLY fields this endpoint may write. An allowlist, not a
# denylist, so a field added next month is closed until someone opens it on
# purpose. `outcome_seq`, `do_not_contact`, `booked`, `outcome` and `product`
# are machine state and stay off this list permanently: an admin route that can
# clear do_not_contact is a compliance hole with a URL attached.
LEAD_UPDATE_ALLOWED = ("name", "business", "email", "phone", "title",
                       "address", "website", "linkedin", "instagram", "note")


@app.route('/admin/lead-update', methods=['POST'])
def admin_lead_update():
    """PATCH #48A — add contact details to an existing lead. Additive only.

    POST /admin/lead-update?secret=<UPLOAD_SECRET>
      {"q": "<name|email|key>", "fields": {"phone": "...", "address": "..."}}

    Written because Michael photographed a business card and there was no way
    to put it on the record: the repo has writers for status, bookings and new
    contacts, and nothing that adds a phone number to a lead that already
    exists.

    Applies to EVERY matching record, capped at 3. That is the feature. Rodolfo
    Silva exists twice, and updating one copy is how you end up with a lead
    whose phone number depends on which copy you happen to read.
    """
    if not _admin_secret_ok(request.args.get("secret")):
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    _payload = request.get_json(silent=True) or {}
    _q = str(_payload.get("q") or "").strip().lower()
    _fields = _payload.get("fields") or {}
    if not _q:
        return jsonify({"ok": False, "error": "q is required"}), 400
    if not isinstance(_fields, dict) or not _fields:
        return jsonify({"ok": False, "error": "fields must be a non-empty object"}), 400

    _refused = [k for k in _fields if k not in LEAD_UPDATE_ALLOWED]
    if _refused:
        return jsonify({
            "ok": False,
            "error": "refused fields (not on the allowlist)",
            "refused": _refused,
            "allowed": list(LEAD_UPDATE_ALLOWED),
            "why": "outcome_seq / do_not_contact / booked / outcome / product are "
                   "machine state and are never writable through this route",
        }), 400

    _hits = []
    for _k, _r in list(lead_data.items()):
        if not isinstance(_r, dict):
            continue
        _hay = " ".join([str(_k), str(_r.get("name") or ""),
                         str(_r.get("email") or ""), str(_r.get("phone") or "")]).lower()
        if _q in _hay:
            _hits.append((_k, _r))
    if not _hits:
        return jsonify({"ok": True, "updated": 0, "note": "no lead matched"}), 200
    if len(_hits) > 3:
        return jsonify({"ok": False, "error": f"{len(_hits)} leads matched — "
                                              f"narrow the query, refusing to "
                                              f"write that broadly"}), 400

    _changes = []
    for _k, _r in _hits:
        _per = {}
        for _f, _v in _fields.items():
            _new = str(_v or "").strip()
            if not _new:
                continue                      # never blank an existing value
            _old = str(_r.get(_f) or "").strip()
            if _old == _new:
                continue
            if _f == "phone":
                _digits = re.sub(r"\D", "", _new)
                if not _digits:
                    continue
                _new = _digits
                if _old == _new:
                    continue
            if _f == "note":
                # Notes append, never replace. Losing a note to a typo in a
                # later call is not a trade worth making.
                _r["notes"] = ((str(_r.get("notes") or "").strip() + "\n" + _new).strip())
                _per["notes"] = "appended"
                continue
            _r[_f] = _new
            _per[_f] = {"was": _old or "(empty)", "now": _new}
        if _per:
            _changes.append({"lead_key": mask_contact(_k),
                             "name": _r.get("name") or "", "changed": _per})

    if _changes:
        try:
            _pg.save_state("leads_snapshot_hint", datetime.now(
                pytz.timezone(TIMEZONE)).isoformat())
        except Exception:
            pass
        try:
            _lines = []
            for _c in _changes:
                _bits = ", ".join(
                    f"{_f} {_d['was']} -> {_d['now']}" if isinstance(_d, dict) else f"{_f} {_d}"
                    for _f, _d in _c["changed"].items())
                _lines.append(f"• *{_c['name']}* (`{_c['lead_key']}`) — {_bits}")
            _post_to_slack_async(SLACK_DEV_CHANNEL, (
                f":pencil2: *Lead record updated* — {len(_changes)} record(s)\n"
                + "\n".join(_lines)
                + "\n_via /admin/lead-update (Patch #48A). Contact fields only; "
                  "machine state is not writable through this route._"))
        except Exception as _sx:
            print(f"[LEAD-UPDATE] slack notice failed (non-fatal): {_sx}")

    return jsonify({"ok": True, "matched": len(_hits),
                    "updated": len(_changes), "changes": _changes}), 200


# ══════════════════════════════════════════════════════════════════════
# PATCH #55A · POST /admin/register-client
# ══════════════════════════════════════════════════════════════════════
# The `PAID CLIENT NOT LINKED TO A LEAD` alarm has existed since #34 and says
# "MICHAEL: confirm which lead record is theirs, or that they are new." Today
# it fired for real — Gema Hiatt / HIS Agents paid $1,400 — and the answer was
# "they are new". At which point there was nothing to act with: #47's route is
# read-only, and #48A's writer refuses `product`, `outcome` and `studio_package`
# by allowlist on purpose.
#
# So the detector could name the problem and nobody could fix it. That is the
# same failure shape as the rest of this board, one level up: the alarm was
# real, the repair path was imaginary.
#
# ROOT CAUSE, worth writing down: Gema booked herself through Calendly for the
# MWM ROADMAP 15-min call. Calendly self-bookings never touch any lead-creation
# path in this codebase, so the pipeline never learned she existed — not when
# she booked, not when she cancelled two minutes before start, and not when she
# paid. This route is the manual repair. The permanent fix is a Calendly
# webhook, which is blocked on Michael's console access.
#
# WHY THIS ROUTE MAY WRITE WHAT #48A REFUSES: because that IS the job. #48A is
# for contact details and must never be able to flip machine state. This one
# exists solely to record "this person is a client of package X", requires the
# variant to be named explicitly, and refuses by default to touch a record that
# already exists so it cannot quietly create the duplicate problem Rodolfo
# already has. `do_not_contact` is still not writable here, and suppression is
# enforced at send time regardless, so registering a client cannot re-open a
# closed door.
LEAD_REGISTER_FIELDS = ("name", "email", "phone", "business", "title",
                        "source", "notes")


@app.route('/admin/portal-clients', methods=['GET'])
def admin_portal_clients():
    """PATCH #55B — read the WP studio-portal ledger back. READ ONLY.

    The last link in the purchase chain that could not be verified from
    outside. When a package is bought, WordPress returns an access code — which
    proves a client row was created, and proves nothing about what the row
    SAYS. Whether it carries 4 contract hours and the right end date was, until
    now, only knowable from the value we sent, never from the value stored.

    That is the exact gap that has cost this board six incidents: a write
    confirmed by the writer rather than re-read from the store. `contract_hours`
    and `contract_end_date` are what the portal enforces on every booking, so
    they are the numbers that decide whether a client gets what they paid for.

    Emails are masked. The response is a ledger of active contracts, not a
    contact list, so a leaked secret does not become an export.
    """
    if not _admin_secret_ok(request.args.get("secret")):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    try:
        _rows = _studio.wp_list_clients()
    except Exception as _px:
        _report_error("admin.portal_clients", _px)
        return jsonify({"ok": False, "error": "portal read failed"}), 502
    if _rows is None:
        return jsonify({"ok": False, "error": "portal ledger unreachable"}), 502

    _q = (request.args.get("q") or "").strip().lower()
    _out = []
    for _c in _rows:
        if not isinstance(_c, dict):
            continue
        _hay = " ".join([str(_c.get("name") or ""), str(_c.get("email") or ""),
                         str(_c.get("package_name") or "")]).lower()
        if _q and _q not in _hay:
            continue
        _out.append({
            "name": _c.get("name") or "",
            "email": mask_contact(_c.get("email")),
            "package_name": _c.get("package_name") or "",
            "contract_hours": _c.get("contract_hours"),
            "hours_used": _c.get("hours_used"),
            "contract_start_date": str(_c.get("contract_start_date") or "")[:10],
            "contract_end_date": str(_c.get("contract_end_date") or "")[:10],
            "active": str(_c.get("active", "1")) == "1",
        })
    _rec_n, _mrr, _one_n, _one_total = _studio.revenue_split(
        [c for c in _rows if isinstance(c, dict) and str(c.get("active", "1")) == "1"])
    return jsonify({"ok": True, "count": len(_out), "clients": _out,
                    "recurring_contracts": _rec_n, "mrr": _mrr,
                    "one_off_clients": _one_n, "one_off_total": _one_total,
                    "as_of": datetime.now(pytz.timezone(TIMEZONE)).isoformat()}), 200


@app.route('/admin/register-client', methods=['POST'])
def admin_register_client():
    """PATCH #55A — create the lead record for a client who paid without one.

    POST /admin/register-client?secret=<UPLOAD_SECRET>
      {"name": "...", "email": "...", "phone": "...", "business": "...",
       "source": "...", "variant": "studio_trial_1mo",
       "purchased_at": "2026-08-05T13:29:00-04:00",   # optional
       "stripe_event": "evt_...",                      # optional, for the audit
       "update_existing": false}                       # must be explicit

    `variant` must be a key in studio_package.PACKAGES. The hours, term and
    deadline are read from that spec and the SAME package_term() the purchase
    path uses, so the record cannot disagree with what WordPress enforces or
    what the client was told in their welcome email.
    """
    if not _admin_secret_ok(request.args.get("secret")):
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    _p = request.get_json(silent=True) or {}
    _name = " ".join(str(_p.get("name") or "").split())
    _email = str(_p.get("email") or "").strip()
    _phone_digits = re.sub(r"\D", "", str(_p.get("phone") or ""))
    _variant = str(_p.get("variant") or "").strip()

    if len(_name) < 2:
        return jsonify({"ok": False, "error": "name is required"}), 400
    if not _email or "@" not in _email:
        return jsonify({"ok": False, "error": "a real email is required"}), 400

    _spec = None
    for _sp in _studio.PACKAGES.values():
        if _sp["kind"] == _variant:
            _spec = _sp
            break
    if _spec is None:
        return jsonify({
            "ok": False, "error": "unknown variant",
            "allowed": [s["kind"] for s in _studio.PACKAGES.values()],
            "why": "the package must be named explicitly — this route will not "
                   "guess which product someone bought",
        }), 400

    # ── refuse to duplicate ──
    _existing_key, _existing = _find_lead_by_email(_email)
    if not _existing_key and _phone_digits:
        _existing_key, _existing = _find_lead_by_phone(_phone_digits)
    if _existing_key and not bool(_p.get("update_existing")):
        return jsonify({
            "ok": False, "error": "a lead record already exists",
            "lead_key": mask_contact(_existing_key),
            "name": (_existing or {}).get("name") or "",
            "why": "pass update_existing=true to stamp the package onto it. "
                   "Refusing by default because a second record for the same "
                   "person is how a lead's phone number starts depending on "
                   "which copy you read",
        }), 409

    # ── the term, from the same maths the purchase path uses ──
    _tz = pytz.timezone(TIMEZONE)
    try:
        _bought = datetime.fromisoformat(str(_p.get("purchased_at") or "").strip())
        if _bought.tzinfo is None:
            _bought = _tz.localize(_bought)
    except Exception:
        _bought = datetime.now(_tz)
    _term = _studio.package_term(_spec, _bought)

    _rel = "new_client" if _spec.get("recurring") is False else "existing_client"
    _box = {
        "purchased": _bought.isoformat(),
        "stripe_event": str(_p.get("stripe_event") or "").strip(),
        "variant": _spec["kind"],
        "package_name": _spec["name"],
        "hours": _spec["hours"],
        "term_days": _spec["term_days"],
        "recurring": bool(_spec["recurring"]),
        "mrr": _spec["mrr"],
        "one_off": _spec.get("one_off", 0),
        "booking_deadline": _term["booking_deadline"].isoformat(),
        "registered_by": "admin/register-client (Patch #55A)",
    }

    if _existing_key:
        _rec = _existing
        _key = _existing_key
        _created = False
        for _f in LEAD_REGISTER_FIELDS:
            _v = str(_p.get(_f) or "").strip()
            if _f == "phone":
                _v = _phone_digits
            if _v and not str(_rec.get(_f) or "").strip():
                _rec[_f] = _v
    else:
        # Key convention matches the rest of the store: a dialable number keys
        # to WhatsApp, otherwise the email keys to the email rail. resolve_channel
        # reads the KEY, so getting this wrong would route her replies nowhere.
        _key = _phone_digits or _email.strip().lower()
        _new = {}
        for _f in LEAD_REGISTER_FIELDS:
            _v = str(_p.get(_f) or "").strip()
            if _f == "phone":
                _v = _phone_digits
            if _v:
                _new[_f] = _v
        _new.setdefault("source", "Direct — registered by Michael")
        _new["first_contact_time"] = _bought
        _new["last_message_time"] = _bought
        lead_data[_key] = _new
        # ── PATCH #56 — RE-FETCH. This line is the whole fix. ──
        # `lead_data` is a LeadData, and its __setitem__ WRAPS a plain dict in a
        # LeadRecord (leads_db.py:258). So `lead_data[k] = _new` does not store
        # `_new` — it stores a different object built from it. Mutating `_new`
        # afterwards writes to an orphan that nothing will ever read or persist.
        #
        # #55A did exactly that, and the consequence was worse than the lost
        # fields: the route RETURNED product/relationship/hours in its success
        # response, so it reported values it had not stored. Gema Hiatt's record
        # came back from /admin/lead-seq with outcome="" and booked=false while
        # the API had answered {"ok": true, "product": "Studio Trial — 1 Month"}.
        #
        # The existing purchase path never hit this because its `rec` comes OUT
        # of lead_data already wrapped. Only create-then-mutate is affected.
        _rec = lead_data[_key]
        _created = True

    _rec["product"] = _spec["name"]
    _rec["outcome"] = "Won"
    _rec["status"] = "client"
    _rec["relationship"] = _rel          # #52 — keeps the sales rail off them
    _rec["booked"] = True
    _rec["booked_at"] = _bought.isoformat()   # #49A — a flag with a WHEN
    _rec["studio_package"] = _box

    try:
        # PATCH #62 — pass the three fields explicitly rather than lean on the
        # new defaults. A paid client's row should say what they bought and
        # what happens next; "" would have satisfied the signature and told
        # the sheet nothing.
        _update_lead_sheet_status(
            _rec.get("name") or _name,
            _spec["sheet_status"],
            notes=(f"{_spec['name']} — {_spec['hours']}h, purchased "
                   f"{_bought.strftime('%b %d, %Y')}; books until "
                   f"{_term['booking_deadline'].strftime('%b %d, %Y')}"),
            service=_spec["name"],
            next_steps="Client onboarded — portal access issued; LARA owns delivery",
        )
    except Exception as _shx:
        _report_error("register_client.sheet", _shx, f"name={_name}")

    try:
        _post_to_slack_async(SLACK_DEV_CHANNEL, (
            f":busts_in_silhouette: *Client record {'created' if _created else 'updated'}* "
            f"— *{_rec.get('name')}* (`{mask_contact(_key)}`)\n"
            f"{_spec['name']} · {_spec['hours']}h · books until "
            f"{_term['booking_deadline'].strftime('%b %d, %Y')}\n"
            f"relationship=`{_rel}` (sales rail OFF) · "
            f"{'one-off $' + format(_spec.get('one_off', 0), ',') if not _spec['recurring'] else '$' + format(_spec['mrr'], ',') + '/mo'}\n"
            f"_via /admin/register-client (Patch #55A) — the repair path the "
            f"PAID CLIENT NOT LINKED alarm never had._"))
    except Exception:
        pass

    # PATCH #56 — report what the STORE says, never what we intended. Read the
    # record back out of lead_data by key and answer from that. #55A answered
    # from local variables and therefore claimed a write that had not landed;
    # a route that cannot tell the difference is worse than no route, because
    # its success response is the thing a human trusts instead of checking.
    _stored = lead_data.get(_key) or {}
    _sbox = _stored.get("studio_package") or {}
    _verified = (_stored.get("product") == _spec["name"]
                 and _stored.get("outcome") == "Won"
                 and bool(_stored.get("booked"))
                 and _sbox.get("variant") == _spec["kind"])
    if not _verified:
        _report_error("register_client.write_not_verified",
                      "the record does not read back as written",
                      f"key={mask_contact(_key)} product={_stored.get('product')!r} "
                      f"outcome={_stored.get('outcome')!r} booked={_stored.get('booked')!r}")
    return jsonify({
        "ok": True, "created": _created, "verified": _verified,
        "lead_key": mask_contact(_key),
        # every field below is read back out of the store, not from our intent
        "name": _stored.get("name"),
        "product": _stored.get("product"),
        "outcome": _stored.get("outcome"),
        "booked": bool(_stored.get("booked")),
        "relationship": _stored.get("relationship"),
        "status": _stored.get("status"),
        "hours": _sbox.get("hours"),
        "booking_deadline": _sbox.get("booking_deadline"),
        "sheet_status": _spec["sheet_status"],
    }), 200


@app.route('/admin/lead-seq', methods=['GET'])
def admin_lead_seq():
    """PATCH #47 — read-only: what is armed on ONE lead, and when it fires.

    /admin/lead-seq?secret=<UPLOAD_SECRET>&q=<name | email | lead key>

    Exists because `outcome_seq` lives in process memory, so every question
    about whether a sequence armed has had to be answered by INFERENCE — the
    lead resolved, the guard passed, therefore the write must have happened.
    That reasoning has been right so far and it is still not evidence, and this
    board has been burned six times by the gap between the two.

    The verdict is computed with the SAME pure functions the sender uses, so
    this reports what the sender will actually do rather than a second opinion
    that can drift out of step with it.
    """
    if not _admin_secret_ok(request.args.get("secret")):
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    _q = (request.args.get("q") or "").strip().lower()
    if not _q:
        return jsonify({"ok": False, "error": "q is required (name, email or lead key)"}), 400

    _hits = []
    for _k, _r in list(lead_data.items()):
        if not isinstance(_r, dict):
            continue
        _hay = " ".join([str(_k), str(_r.get("name") or ""),
                         str(_r.get("email") or ""), str(_r.get("phone") or "")]).lower()
        if _q in _hay:
            _hits.append((_k, _r))
    if not _hits:
        return jsonify({"ok": True, "found": 0, "matches": [],
                        "note": "no lead matched — the sequence cannot be armed on a "
                                "record that does not exist"}), 200
    if len(_hits) > 5:
        return jsonify({"ok": True, "found": len(_hits), "matches": [],
                        "note": f"{len(_hits)} leads matched — narrow the query"}), 200

    _tz = pytz.timezone(TIMEZONE)
    _now = datetime.now(_tz)
    _out = []
    for _k, _r in _hits:
        _entry = {
            "lead_key": mask_contact(_k),
            "name": _r.get("name") or "",
            "business": _r.get("business") or "",
            "email": mask_contact(_r.get("email")),
            "booked": bool(_r.get("booked")),
            "outcome": _r.get("outcome") or "",
        }
        _seq = _r.get("outcome_seq")
        if not isinstance(_seq, dict):
            _entry["armed"] = False
            _entry["why"] = ("no outcome_seq on this record — either no event report "
                             "has been submitted for them, or the outcome was one "
                             "that arms nothing (not_interested / client_won)")
            _out.append(_entry)
            continue

        _entry["armed"] = True
        _entry["outcome_reported"] = _seq.get("outcome")
        _entry["armed_at"] = _seq.get("armed_at")
        _entry["done"] = bool(_seq.get("done"))
        _entry["closed_reason"] = _seq.get("closed_reason") or ""
        _entry["sent_so_far"] = _seq.get("sent") or []
        _entry["has_agreed_next"] = bool(_seq.get("agreed_next"))   # #46A
        _entry["steps"] = [
            {"after_hours": _h, "delivered_by": delivery_label(_c), "kind": _kd}
            for _h, _c, _kd in (_seq.get("steps") or [])
        ]

        # ── the sender's OWN verdict, not a re-implementation of it ──
        _stop = seq_stop_reason(_r, _seq)
        if _stop:
            _entry["verdict"] = f"STOPPED — {_stop}"
            _out.append(_entry)
            continue
        try:
            _armed_dt = datetime.fromisoformat(str(_seq.get("armed_at")))
            if _armed_dt.tzinfo is None:
                _armed_dt = _tz.localize(_armed_dt)
            _elapsed_h = (_now - _armed_dt).total_seconds() / 3600.0
        except Exception:
            _entry["verdict"] = "BROKEN — armed_at is unparseable; the sender will close this"
            _out.append(_entry)
            continue

        _idx, _step, _status = next_due_step(_seq, _elapsed_h)
        if _status == "finished":
            _entry["verdict"] = "FINISHED — every step has been taken"
        elif seq_should_close(_seq, _elapsed_h / 24.0):
            _entry["verdict"] = "CLOSING — past close_after_days on the next pass"
        else:
            _after, _ch, _kind = _step
            _due_at = _armed_dt + timedelta(hours=float(_after))
            _entry["next_step"] = {
                "kind": _kind,
                "delivered_by": delivery_label(_ch),
                "due_at": _due_at.strftime("%a %b %d, %I:%M %p %Z"),
                "status": _status,
            }
            if _status == "due" and not within_send_window(_now):
                _entry["verdict"] = ("DUE — held until 08:00, quiet hours "
                                     "(the step is held, never skipped)")
            else:
                _entry["verdict"] = {
                    "due": "DUE — goes out on the next pass (within 20 minutes)",
                    "waiting": "WAITING — armed and counting down",
                    "stale": "STALE — its window passed; the sender will skip it and report",
                }.get(_status, _status)

            # The actual words. The whole point of this endpoint is that nobody
            # has to guess what a client is about to receive.
            try:
                _fn = _outcome_seq._first_name(_r.get("name"))
                _agreed = str(_seq.get("agreed_next") or "").strip()
                if _ch in (CH_WEB, CH_EMAIL):
                    _subj, _body = _outcome_seq._email_copy(
                        _kind, _fn, _r.get("business") or "", _agreed)
                    _entry["next_step"]["preview"] = {
                        "subject": _subj,
                        "body_text": re.sub(r"<[^>]+>", " ", _body).replace("&amp;", "&"),
                    }
                else:
                    _entry["next_step"]["preview"] = {
                        "message": _outcome_seq._short_copy(
                            _kind, _fn, _r.get("business") or "", _agreed)}
            except Exception as _pv:
                _entry["next_step"]["preview_error"] = str(_pv)[:200]
        _out.append(_entry)

    return jsonify({"ok": True, "found": len(_out), "as_of": _now.isoformat(),
                    "matches": _out}), 200


@app.route('/admin/submit-post-visit-templates', methods=['POST'])
def submit_post_visit_templates():
    """Submit post-visit WhatsApp templates to Meta for approval.
    One-time admin endpoint. Auth: BRIEFING_TOKEN.
    """
    auth = request.headers.get("Authorization", "")
    if not BRIEFING_TOKEN or not auth.startswith("Bearer "):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    if auth.split("Bearer ", 1)[1].strip() != BRIEFING_TOKEN:
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    if not META_ACCESS_TOKEN:
        return jsonify({"ok": False, "error": "META_ACCESS_TOKEN not set"}), 500

    url = f"https://graph.facebook.com/v20.0/{POST_VISIT_WABA_ID}/message_templates"
    hdrs = {"Authorization": f"Bearer {META_ACCESS_TOKEN}", "Content-Type": "application/json"}

    templates = [
        {
            "name": "maya_post_visit_followup_v2",
            "category": "MARKETING",
            "language": "en_US",
            "components": [
                {
                    "type": "BODY",
                    "text": "Hi {{1}}, it was great meeting you at MWM Studios! "
                            "Thank you for taking the time to visit. If you have "
                            "any questions or want to discuss anything further, "
                            "feel free to reach out anytime — we would love to "
                            "work with you!",
                    "example": {"body_text": [["Daniele"]]}
                }
            ]
        },
        {
            "name": "maya_post_visit_noshow",
            "category": "MARKETING",
            "language": "en_US",
            "components": [
                {
                    "type": "BODY",
                    "text": "Hi {{1}}, we missed you at the studio today! No worries "
                            "at all — I know schedules can get hectic. Would you "
                            "like to reschedule your visit? Just let me know a time "
                            "that works better for you.",
                    "example": {"body_text": [["Sarah"]]}
                }
            ]
        },
        {
            "name": "maya_post_visit_welcome",
            "category": "MARKETING",
            "language": "en_US",
            "components": [
                {
                    "type": "BODY",
                    "text": "Hi {{1}}, welcome to the MWM family! We're so excited to "
                            "work with you on your project. Our production team is "
                            "getting everything set up and we'll be in touch soon with "
                            "next steps. Thank you for choosing MWM Creations!",
                    "example": {"body_text": [["Carlos"]]}
                }
            ]
        },
    ]

    results = []
    for t in templates:
        try:
            r = http_requests.post(url, headers=hdrs, json=t, timeout=15)
            try:
                body = r.json()
            except Exception:
                body = r.text
            results.append({"name": t["name"], "status": r.status_code, "response": body})
            print(f"[POST-VISIT] Template '{t['name']}' submitted: {r.status_code}")
        except Exception as e:
            results.append({"name": t["name"], "status": "error", "response": str(e)})

    return jsonify({"ok": True, "results": results})


# ══════════════════════════════════════════════════════════════════════
# ADMIN: UPDATE WHATSAPP BUSINESS PROFILE PHOTO
# One-time utility. POST base64-encoded image to update Maya's profile.
# Auth: BRIEFING_TOKEN.
# ══════════════════════════════════════════════════════════════════════

@app.route('/admin/update-whatsapp-profile-photo', methods=['POST'])
def update_whatsapp_profile_photo():
    """Update Maya's WhatsApp Business profile picture via Meta API.

    POST JSON: {"image_base64": "<base64-encoded PNG/JPEG>", "file_type": "image/png"}
    Auth: Bearer BRIEFING_TOKEN

    Steps:
    1. Get app ID from Meta token
    2. Create resumable upload session
    3. Upload image binary
    4. Set profile picture handle on WhatsApp Business Profile
    """
    import base64 as _b64

    # Auth check
    auth = request.headers.get("Authorization", "")
    if not BRIEFING_TOKEN or not auth.startswith("Bearer "):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    if auth.split("Bearer ", 1)[1].strip() != BRIEFING_TOKEN:
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    if not META_ACCESS_TOKEN or not META_PHONE_NUMBER_ID:
        return jsonify({"ok": False, "error": "META_ACCESS_TOKEN or META_PHONE_NUMBER_ID not set"}), 500

    data = request.get_json(force=True, silent=True) or {}
    image_b64 = data.get("image_base64", "")
    file_type = data.get("file_type", "image/png")

    if not image_b64:
        return jsonify({"ok": False, "error": "image_base64 is required"}), 400

    try:
        image_bytes = _b64.b64decode(image_b64)
    except Exception as e:
        return jsonify({"ok": False, "error": f"Invalid base64: {e}"}), 400

    file_length = len(image_bytes)
    print(f"[PROFILE PHOTO] Received {file_length} bytes ({file_type})")

    try:
        # Step 1: Get app ID from token
        app_resp = http_requests.get(
            "https://graph.facebook.com/v20.0/app",
            params={"access_token": META_ACCESS_TOKEN},
            timeout=10,
        )
        if app_resp.status_code != 200:
            return jsonify({"ok": False, "error": f"Failed to get app ID: {app_resp.text}"}), 500
        app_id = app_resp.json().get("id")
        print(f"[PROFILE PHOTO] App ID: {app_id}")

        # Step 2: Create upload session
        upload_resp = http_requests.post(
            f"https://graph.facebook.com/v20.0/{app_id}/uploads",
            params={
                "file_length": file_length,
                "file_type": file_type,
                "access_token": META_ACCESS_TOKEN,
            },
            timeout=15,
        )
        if upload_resp.status_code != 200:
            return jsonify({"ok": False, "error": f"Upload session failed: {upload_resp.text}"}), 500
        session_id = upload_resp.json().get("id")
        print(f"[PROFILE PHOTO] Upload session: {session_id}")

        # Step 3: Upload image binary
        binary_resp = http_requests.post(
            f"https://graph.facebook.com/v20.0/{session_id}",
            headers={
                "Authorization": f"OAuth {META_ACCESS_TOKEN}",
                "Content-Type": file_type,
                "file_offset": "0",
            },
            data=image_bytes,
            timeout=30,
        )
        if binary_resp.status_code != 200:
            return jsonify({"ok": False, "error": f"Binary upload failed: {binary_resp.text}"}), 500
        handle = binary_resp.json().get("h")
        print(f"[PROFILE PHOTO] Got handle: {handle[:30]}...")

        # Step 4: Set profile picture
        profile_resp = http_requests.post(
            f"https://graph.facebook.com/v20.0/{META_PHONE_NUMBER_ID}/whatsapp_business_profile",
            headers={
                "Authorization": f"Bearer {META_ACCESS_TOKEN}",
                "Content-Type": "application/json",
            },
            json={
                "messaging_product": "whatsapp",
                "profile_picture_handle": handle,
            },
            timeout=15,
        )
        print(f"[PROFILE PHOTO] Profile update: {profile_resp.status_code} — {profile_resp.text}")

        if profile_resp.status_code == 200:
            return jsonify({"ok": True, "message": "Profile photo updated successfully"})
        else:
            return jsonify({"ok": False, "error": f"Profile update failed: {profile_resp.text}"}), 500

    except Exception as e:
        print(f"[PROFILE PHOTO] Error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"ok": False, "error": str(e)}), 500


# ══════════════════════════════════════════════════════════════════════
# ADMIN: INSTAGRAM TOKEN LIFECYCLE MANAGEMENT
# Session 39 — Exchange short-lived IGAAX token for 60-day long-lived
# token, and refresh long-lived tokens before they expire.
# Auth: BRIEFING_TOKEN
# ══════════════════════════════════════════════════════════════════════

def _exchange_ig_short_token(short_token: str, app_secret: str):
    """Exchange a short-lived Instagram Login API token for a 60-day long-lived token.

    Endpoint: GET https://graph.instagram.com/access_token
        ?grant_type=ig_exchange_token
        &client_secret={app_secret}
        &access_token={short_token}

    Returns dict with 'access_token', 'token_type', 'expires_in' on success,
    or None on failure.
    """
    try:
        resp = http_requests.get(
            "https://graph.instagram.com/access_token",
            params={
                "grant_type": "ig_exchange_token",
                "client_secret": app_secret,
                "access_token": short_token,
            },
            timeout=15,
        )
        data = resp.json()
        if resp.status_code == 200 and "access_token" in data:
            expires_in = data.get("expires_in", 0)
            days = expires_in // 86400
            print(f"[IG TOKEN] Exchanged short-lived token for long-lived ({days} days)")
            return data
        else:
            print(f"[IG TOKEN] Exchange failed: {data}")
            return None
    except Exception as e:
        print(f"[IG TOKEN] Exchange error: {e}")
        return None


def _refresh_ig_long_token(long_token: str):
    """Refresh a valid, non-expired long-lived Instagram token for another 60 days.

    Endpoint: GET https://graph.instagram.com/refresh_access_token
        ?grant_type=ig_refresh_token
        &access_token={long_token}

    Returns dict with new 'access_token' and 'expires_in', or None on failure.
    NOTE: Tokens that have already expired CANNOT be refreshed.
    """
    try:
        resp = http_requests.get(
            "https://graph.instagram.com/refresh_access_token",
            params={
                "grant_type": "ig_refresh_token",
                "access_token": long_token,
            },
            timeout=15,
        )
        data = resp.json()
        if resp.status_code == 200 and "access_token" in data:
            expires_in = data.get("expires_in", 0)
            days = expires_in // 86400
            print(f"[IG TOKEN] Refreshed long-lived token ({days} days)")
            return data
        else:
            print(f"[IG TOKEN] Refresh failed: {data}")
            return None
    except Exception as e:
        print(f"[IG TOKEN] Refresh error: {e}")
        return None


@app.route('/admin/ig-token-exchange', methods=['POST'])
def admin_ig_token_exchange():
    """Exchange the current IGAAX short-lived token for a 60-day long-lived token.

    POST JSON: {"action": "exchange"} or {"action": "refresh"}
    Auth: Bearer BRIEFING_TOKEN

    - "exchange": Convert a short-lived IGAAX token to a long-lived one (requires INSTAGRAM_APP_SECRET).
    - "refresh": Refresh an existing long-lived token for another 60 days.

    On success, updates the in-memory INSTAGRAM_ACCESS_TOKEN global so the running
    instance uses the new token immediately. The caller must ALSO update the Railway
    env var to persist across deploys.
    """
    global INSTAGRAM_ACCESS_TOKEN

    # Auth check
    auth = request.headers.get("Authorization", "")
    if not BRIEFING_TOKEN or not auth.startswith("Bearer "):
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    if auth.split("Bearer ", 1)[1].strip() != BRIEFING_TOKEN:
        return jsonify({"ok": False, "error": "unauthorized"}), 401

    data = request.get_json(force=True, silent=True) or {}
    action = data.get("action", "exchange")

    current_token = INSTAGRAM_ACCESS_TOKEN
    if not current_token:
        return jsonify({"ok": False, "error": "No INSTAGRAM_ACCESS_TOKEN configured"}), 400

    token_prefix = current_token[:8] + "..." if len(current_token) > 8 else "???"

    if action == "exchange":
        # Exchange short-lived → long-lived
        if not INSTAGRAM_APP_SECRET:
            return jsonify({
                "ok": False,
                "error": "INSTAGRAM_APP_SECRET env var not set. Get it from Meta Developer Dashboard → App → Instagram → Basic → Instagram App Secret"
            }), 400

        result = _exchange_ig_short_token(current_token, INSTAGRAM_APP_SECRET)
        if not result:
            return jsonify({"ok": False, "error": "Token exchange failed — see server logs"}), 500

        new_token = result["access_token"]
        expires_in = result.get("expires_in", 0)
        days = expires_in // 86400

        # Update in-memory token
        INSTAGRAM_ACCESS_TOKEN = new_token
        _persist_ig_token(new_token, result.get("expires_in", 0))  # S6.3
        new_prefix = new_token[:8] + "..." if len(new_token) > 8 else "???"

        return jsonify({
            "ok": True,
            "action": "exchange",
            "old_token_prefix": token_prefix,
            "new_token_prefix": new_prefix,
            "new_token": new_token,
            "expires_in_seconds": expires_in,
            "expires_in_days": days,
            "message": f"Token exchanged successfully. Expires in {days} days. "
                       f"UPDATE Railway env var INSTAGRAM_ACCESS_TOKEN with the new_token value to persist."
        })

    elif action == "refresh":
        # Refresh existing long-lived token
        result = _refresh_ig_long_token(current_token)
        if not result:
            return jsonify({"ok": False, "error": "Token refresh failed — token may be expired or invalid"}), 500

        new_token = result["access_token"]
        expires_in = result.get("expires_in", 0)
        days = expires_in // 86400

        # Update in-memory token
        INSTAGRAM_ACCESS_TOKEN = new_token
        _persist_ig_token(new_token, result.get("expires_in", 0))  # S6.3
        new_prefix = new_token[:8] + "..." if len(new_token) > 8 else "???"

        return jsonify({
            "ok": True,
            "action": "refresh",
            "old_token_prefix": token_prefix,
            "new_token_prefix": new_prefix,
            "new_token": new_token,
            "expires_in_seconds": expires_in,
            "expires_in_days": days,
            "message": f"Token refreshed. Expires in {days} days. "
                       f"UPDATE Railway env var INSTAGRAM_ACCESS_TOKEN with the new_token value to persist."
        })

    else:
        return jsonify({"ok": False, "error": f"Unknown action: {action}. Use 'exchange' or 'refresh'"}), 400


